def _grpc_delete_ipam(ipam_uuid: UUID) -> bool:
    """Delete an IPAM record via the database microservice."""
    try:
        stub = _get_database_stub()
        request = database_pb2.DeleteIPAMRequest(uuid=str(ipam_uuid))
        reply = _grpc_call(stub.DeleteIPAM, request)
        return bool(reply.success)
    except grpc.RpcError as e:
        LOG.error(f'gRPC DeleteIPAM failed for {ipam_uuid}: {e}')
        return False


def _grpc_update_ipam(data: IPAMData) -> bool:
    """Update an IPAM record via the database microservice."""
    try:
        stub = _get_database_stub()
        request = database_pb2.UpdateIPAMRequest(
            ipam=database_pb2.IPAMStaticData(
                uuid=str(data.uuid),
                namespace=data.namespace or '',
                network_uuid=str(data.network_uuid),
                ipblock=data.ipblock,
                version=data.version
            )
        )
        reply = _grpc_call(stub.UpdateIPAM, request)
        return bool(reply.success)
    except grpc.RpcError as e:
        LOG.error(f'gRPC UpdateIPAM failed for {data.uuid}: {e}')
        return False


# =============================================================================
# IPAM Public API Functions
# =============================================================================

def create_ipam(data: IPAMData) -> bool:
    """Create an IPAM record.

    Args:
        data: The IPAMData to insert.

    Returns:
        True if successful, False otherwise.
    """
    if _use_database_service():
        return _grpc_create_ipam(data)
    return _direct_create_ipam(data)


def get_ipam(ipam_uuid: UUID) -> Optional[IPAMData]:
    """Get IPAM static values.

    Args:
        ipam_uuid: The UUID of the IPAM.

    Returns:
        An IPAMData object, or None if not found.
    """
    # The IPAM record read here is the immutable static block definition
    # (uuid/namespace/network_uuid/ipblock/version); the mutable allocations
    # live in the ipam_reservations table and are read by other functions. So
    # this is a phase 2 immutable-tier cache candidate -- update_ipam (the
    # version-upgrade persist path) and delete_ipam evict it. See issue #3501.
    cached: Optional[IPAMData] = _object_cache_get('ipam', ipam_uuid)
    if cached is not None:
        return cached
    if _use_database_service():
        row = _grpc_get_ipam(ipam_uuid)
    else:
        row = _direct_get_ipam(ipam_uuid)
    _object_cache_put('ipam', ipam_uuid, row, config.OBJECT_CACHE_TTL_IMMUTABLE)
    return row


def delete_ipam(ipam_uuid: UUID) -> bool:
    """Delete an IPAM record.

    Args:
        ipam_uuid: The UUID of the IPAM.

    Returns:
        True if deleted, False if not found or error.
    """
    if _use_database_service():
        result = _grpc_delete_ipam(ipam_uuid)
    else:
        result = _direct_delete_ipam(ipam_uuid)
    _object_cache_evict('ipam', ipam_uuid)
    return result


def update_ipam(data: IPAMData) -> bool:
    """Update an IPAM record.

    This is used to persist version upgrades.

    Args:
        data: The IPAMData with updated values.

    Returns:
        True if updated, False if not found or error.
    """
    if _use_database_service():
        result = _grpc_update_ipam(data)
    else:
        result = _direct_update_ipam(data)
    _object_cache_evict('ipam', data.uuid)
    return result


# =============================================================================
# Network Table Definitions
# =============================================================================

def _get_networks_table() -> sa.Table:
    """Get or create the networks table definition.

    This table stores static values for Network objects. Networks are
    virtual L2 networks with optional DHCP, NAT, and DNS services.

    The table schema is generated from the NetworkData Pydantic model.
    The uuid is the primary key, with a UNIQUE constraint on vxid
    and an index on namespace.
    """
    global _networks_table
    if _networks_table is None:
        with TABLE_CREATION_LOCK:
            if _networks_table is not None:
                return _networks_table
            metadata = _get_metadata()
            _networks_table = pydantic_to_sqlalchemy_table(
                NetworkData,
                'networks',
                metadata,
                primary_key_fields=['uuid'],
                include_id_column=False
            )
            # Add UNIQUE constraint on vxid for atomic VXLAN allocation
            sa.UniqueConstraint(
                _networks_table.c.vxid, name='uq_networks_vxid')
    return _networks_table


def _get_network_attributes_table() -> sa.Table:
    """Get or create the network_attributes table definition."""
    global _network_attributes_table
    if _network_attributes_table is None:
        with TABLE_CREATION_LOCK:
            if _network_attributes_table is not None:
                return _network_attributes_table
            metadata = _get_metadata()
            _network_attributes_table = pydantic_to_sqlalchemy_table(
                NetworkAttributesData,
                'network_attributes',
                metadata,
                primary_key_fields=['uuid'],
                include_id_column=False
            )
    return _network_attributes_table


def _ensure_networks_schema(engine: sa.Engine) -> dict[str, Any]:
    """Ensure the networks table schema is up to date."""
    table_name = 'networks'
    current_ver = _get_table_version(engine, table_name)
    start_ver = current_ver
    table = _get_networks_table()

    if current_ver <= 0:
        LOG.info(f'Creating {table_name} table (version 1)')
        table.metadata.create_all(
            engine, tables=[table], checkfirst=True)

        with engine.connect() as conn:
            for idx in table.indexes:
                try:
                    idx.create(conn, checkfirst=True)
                except Exception as e:
                    LOG.debug(
                        f'Index {idx.name} creation skipped: {e}')

        current_ver = 1
        _set_table_version(engine, table_name, current_ver)

    if current_ver <= 2:
        LOG.info(f'Upgrading {table_name} table to version 3 '
                 '(add index on name column)')
        with engine.connect() as conn:
            try:
                conn.execute(sa.text(
                    'CREATE INDEX idx_networks_name ON networks(name)'))
                conn.commit()
            except (IntegrityError, OperationalError) as e:
                LOG.debug(
                    f'Index idx_networks_name already exists '
                    f'or could not be added: {e}')

        current_ver = 3
        _set_table_version(engine, table_name, current_ver)

    return {
        'table': table_name,
        'start_version': start_ver,
        'end_version': current_ver,
        'target_version': NETWORKS_VERSION,
        'migrated': start_ver != current_ver
    }


def _ensure_network_attributes_schema(
        engine: sa.Engine) -> dict[str, Any]:
    """Ensure the network_attributes table schema is up to date."""
    table_name = 'network_attributes'
    current_ver = _get_table_version(engine, table_name)
    start_ver = current_ver
    table = _get_network_attributes_table()

    if current_ver <= 0:
        LOG.info(f'Creating {table_name} table (version 1)')
        table.metadata.create_all(
            engine, tables=[table], checkfirst=True)

        with engine.connect() as conn:
            for idx in table.indexes:
                try:
                    idx.create(conn, checkfirst=True)
                except Exception as e:
                    LOG.debug(
                        f'Index {idx.name} creation skipped: {e}')

        current_ver = 1
        _set_table_version(engine, table_name, current_ver)

    if current_ver < NETWORK_ATTRIBUTES_VERSION:
        # Phase 7: drop the cached child-NI list. The
        # ``Network.networkinterfaces`` property now queries
        # network_interfaces live via an indexed
        # ``WHERE network_uuid = ?``. ``DROP COLUMN IF EXISTS`` is
        # idempotent so a re-run on a fresh deployment (where
        # ``create_all`` never created the columns) is a no-op.
        LOG.info(
            f'Upgrading {table_name} table to version '
            f'{NETWORK_ATTRIBUTES_VERSION} '
            '(drop cached networkinterfaces columns)')
        with engine.connect() as conn:
            for col in (
                    'networkinterfaces',
                    'networkinterfaces_initialized'):
                try:
                    conn.execute(sa.text(
                        f'ALTER TABLE {table_name} '
                        f'DROP COLUMN IF EXISTS {col}'))
                    conn.commit()
                except (IntegrityError, OperationalError) as e:
                    LOG.debug(
                        f'Column {col} drop skipped: {e}')
        current_ver = NETWORK_ATTRIBUTES_VERSION
        _set_table_version(engine, table_name, current_ver)

    return {
        'table': table_name,
        'start_version': start_ver,
        'end_version': current_ver,
        'target_version': NETWORK_ATTRIBUTES_VERSION,
        'migrated': start_ver != current_ver
    }


# =============================================================================
# Network Direct Access Functions
# These are used by the database daemon for Network object storage.
# =============================================================================

def _direct_create_network(data: NetworkData) -> bool:
    """Create a Network record in MariaDB.

    Args:
        data: The NetworkData to insert.

    Returns:
        True if created successfully, False if duplicate or error.
    """
    engine = _get_engine()
    table = _get_networks_table()

    try:
        with engine.connect() as conn:
            stmt = sa.insert(table).values(
                uuid=data.uuid,
                name=data.name,
                namespace=data.namespace,
                netblock=data.netblock,
                provide_dhcp=data.provide_dhcp,
                provide_nat=data.provide_nat,
                provide_dns=data.provide_dns,
                vxid=data.vxid,
                egress_nic=data.egress_nic,
                mesh_nic=data.mesh_nic,
                version=data.version
            )
            conn.execute(stmt)
            conn.commit()
            return True
    except IntegrityError:
        return False
    except OperationalError as e:
        LOG.warning(
            f'MariaDB create failed for network {data.uuid}: {e}')
        return False


def _direct_get_network(
        net_uuid: UUID) -> Optional[NetworkData]:
    """Get Network static values from MariaDB.

    Args:
        net_uuid: The UUID of the Network.

    Returns:
        A NetworkData object, or None if not found.
    """
    engine = _get_engine()
    table = _get_networks_table()

    try:
        with engine.connect() as conn:
            stmt = sa.select(table).where(
                table.c.uuid == net_uuid)
            result = conn.execute(stmt).fetchone()

            if result is None:
                return None

            return NetworkData(
                uuid=result.uuid,
                name=result.name,
                namespace=result.namespace,
                netblock=result.netblock,
                provide_dhcp=result.provide_dhcp,
                provide_nat=result.provide_nat,
                provide_dns=result.provide_dns,
                vxid=result.vxid,
                egress_nic=result.egress_nic,
                mesh_nic=result.mesh_nic,
                version=result.version
            )
    except OperationalError as e:
        LOG.warning(
            f'MariaDB get failed for network {net_uuid}: {e}')
        return None


def _direct_get_all_networks() -> list[NetworkData]:
    """Get all Network records from MariaDB.

    Returns:
        List of NetworkData objects.
    """
    engine = _get_engine()
    table = _get_networks_table()

    try:
        with engine.connect() as conn:
            stmt = sa.select(table)
            result = conn.execute(stmt).fetchall()

            return [
                NetworkData(
                    uuid=row.uuid,
                    name=row.name,
                    namespace=row.namespace,
                    netblock=row.netblock,
                    provide_dhcp=row.provide_dhcp,
                    provide_nat=row.provide_nat,
                    provide_dns=row.provide_dns,
                    vxid=row.vxid,
                    egress_nic=row.egress_nic,
                    mesh_nic=row.mesh_nic,
                    version=row.version
                )
                for row in result
            ]
    except OperationalError as e:
        LOG.warning(f'MariaDB query failed for all networks: {e}')
        return []


def _direct_find_network_vxids(vxids: list[int]) -> dict[int, str]:
    """Return the vxids which a network row claims, mapped to that network.

    An exact-match lookup against the UNIQUE index on networks.vxid,
    returning the vxid and uuid columns rather than hydrating
    NetworkData objects. Callers which only need to know whether a
    vxid is claimed should use this rather than scanning every
    network. The uuid is returned as well because the caller routes
    cleanup of a still-existing network through a cluster operation
    targeting it, and can only do so if it knows which network it is.

    Note that unlike most getters here this deliberately does not
    swallow OperationalError. The only caller (the stray vxlan reaper
    in the network maintainer) treats "no network claims this vxid" as
    permission to delete a host network device, so a database failure
    must not be reported as an empty result. Letting the error
    propagate aborts the maintain pass instead, which is the safe
    outcome.
    """
    if not vxids:
        return {}

    engine = _get_engine()
    table = _get_networks_table()

    with engine.connect() as conn:
        stmt = sa.select(table.c.vxid, table.c.uuid).where(
            table.c.vxid.in_(vxids))
        return {
            row.vxid: str(row.uuid)
            for row in conn.execute(stmt).fetchall()
        }


# The vxids an instance on a given node is attached to, in one indexed
# query. The alternative -- hydrating every instance placed on the node
# and then one network per distinct network uuid -- is paid on every 30
# second maintain pass for as long as a protected stray vxlan survives,
# which by design is forever.
#
# The driving table is the node's INSTANCE_LOCATION reference rows,
# which the object_references primary key (and its source index) leads
# with, so the scan is bounded by this node's placements rather than by
# the cluster's instance count.
#
# Format note (pitfall 6): object_references uuid columns store the
# dashed 36 character form while network_interfaces.instance_uuid is
# sa.Uuid (undashed CHAR(32) on MariaDB), so the join transforms the
# reference side value with REPLACE to land on the indexed column.
# object_states.object_uuid is dashed like object_references, so that
# join compares directly.
#
# The enum-typed predicates span two storage conventions and the bound
# parameters must match each column exactly: object_states.object_type
# is a native sa.Enum(ObjectType) which SQLAlchemy persists as the
# member *name* ('INSTANCE'), while the object_references type and
# relationship columns are plain String(64) written by
# _direct_record_relationship() as str(member), i.e. the enum *value*
# ('instance', 'instance_location'). See the comment above
# _RECONCILE_USAGE_SQL for why a case-insensitive collation must not be
# relied on to bridge the two.
#
# Interfaces are filtered on ``active IS NOT NULL`` rather than on their
# state, which is the same test the macaddr UNIQUE constraint uses:
# ``active`` is NULLed only when an interface enters the deleted state.
# That is a superset of NetworkInterface.ACTIVE_STATES (it also keeps
# delete-wait-error interfaces), and erring towards protecting a device
# is the right direction here. Networks are deliberately not filtered by
# state at all: a soft deleted network still protects its device, which
# matches Network.from_db() in the code this replaced.
_NODE_INSTANCE_VXIDS_SQL = sa.text('''
    SELECT DISTINCT n.vxid AS vxid
      FROM object_references r
      JOIN object_states s
        ON s.object_uuid = r.target_uuid
       AND s.object_type = :instance_object_type
      JOIN network_interfaces ni
        ON ni.instance_uuid = REPLACE(r.target_uuid, '-', '')
      JOIN networks n
        ON n.uuid = ni.network_uuid
     WHERE r.source_object_type = :node_object_type
       AND r.source_uuid = :node_uuid
       AND r.relationship = :instance_location
       AND r.target_object_type = :instance_ref_type
       AND ni.active IS NOT NULL
       AND s.state_value IN :states
''').bindparams(sa.bindparam('states', expanding=True))


def _direct_get_node_instance_vxids(
        node_uuid: str, states: list[str]) -> set[int]:
    """The vxids of networks used by instances on a node, in one query.

    Returns the set of vxids of every network an instance placed on
    ``node_uuid``, and in one of ``states``, has an undeleted interface
    on.

    Like ``_direct_find_network_vxids`` this deliberately does not
    swallow OperationalError. The caller treats "no instance here uses
    this network" as permission to tear down a host network device, so
    a database failure must not be reported as an empty result --
    letting it propagate aborts the maintain pass instead.
    """
    if not states:
        return set()

    engine = _get_engine()
    with engine.connect() as conn:
        rows = conn.execute(_NODE_INSTANCE_VXIDS_SQL, {
            'node_uuid': node_uuid,
            # object_states.object_type is a native sa.Enum, which
            # persists member names. The object_references columns are
            # plain strings holding enum values.
            'instance_object_type': ObjectType.INSTANCE.name,
            'instance_ref_type': ObjectType.INSTANCE.value,
            'node_object_type': ObjectType.NODE.value,
            'instance_location': RelationshipType.INSTANCE_LOCATION.value,
            'states': list(states),
        }).fetchall()
        return {int(row.vxid) for row in rows}


def _direct_find_networks(
        criteria: ObjectFilterCriteria) -> list[NetworkData]:
    """Find networks matching the given filter criteria.

    Joins ``networks`` to ``object_states`` and applies the optional
    state/namespace/name filters from ``criteria``. On
    ``OperationalError`` logs the full criteria at WARNING level and
    returns an empty list.
    """
    engine = _get_engine()
    table = _get_networks_table()
    stmt = _build_object_filter_query(
        table, ObjectType.NETWORK, criteria)

    try:
        with engine.connect() as conn:
            result = conn.execute(stmt).fetchall()
            return [
                NetworkData(
                    uuid=row.uuid,
                    name=row.name,
                    namespace=row.namespace,
                    netblock=row.netblock,
                    provide_dhcp=row.provide_dhcp,
                    provide_nat=row.provide_nat,
                    provide_dns=row.provide_dns,
                    vxid=row.vxid,
                    egress_nic=row.egress_nic,
                    mesh_nic=row.mesh_nic,
                    version=row.version
                )
                for row in result
            ]
    except OperationalError as e:
        LOG.warning(
            f'MariaDB find failed for networks '
            f'(states={criteria.states!r}, '
            f'namespace={criteria.namespace!r}, '
            f'name={criteria.name!r}): {e}')
        return []


def _direct_delete_network(net_uuid: UUID) -> bool:
    """Delete a Network record from MariaDB.

    Args:
        net_uuid: The UUID of the Network to delete.

    Returns:
        True if deleted, False if not found or error.
    """
    engine = _get_engine()
    table = _get_networks_table()

    try:
        with engine.connect() as conn:
            stmt = sa.delete(table).where(
                table.c.uuid == net_uuid)
            result = conn.execute(stmt)
            conn.commit()
            return result.rowcount > 0
    except OperationalError as e:
        LOG.warning(
            f'MariaDB delete failed for network {net_uuid}: {e}')
        return False


def _direct_create_network_attributes(
        data: NetworkAttributesData) -> bool:
    """Create a network_attributes record in MariaDB."""
    engine = _get_engine()
    table = _get_network_attributes_table()

    try:
        with engine.connect() as conn:
            stmt = sa.insert(table).values(
                uuid=data.uuid,
                floating_gateway=data.floating_gateway,
                hosteddns=_json_dumps(data.hosteddns))
            conn.execute(stmt)
            conn.commit()
            return True
    except IntegrityError:
        return False
    except OperationalError as e:
        LOG.warning(
            f'MariaDB create failed for '
            f'network_attributes {data.uuid}: {e}')
        return False


def _direct_get_network_attributes(
        net_uuid: UUID) -> Optional[NetworkAttributesData]:
    """Get Network attributes from MariaDB."""
    engine = _get_engine()
    table = _get_network_attributes_table()

    try:
        with engine.connect() as conn:
            stmt = sa.select(table).where(
                table.c.uuid == net_uuid)
            result = conn.execute(stmt).fetchone()

            if result is None:
                return None

            dns = result.hosteddns
            if isinstance(dns, str):
                dns = json.loads(dns)

            return NetworkAttributesData(
                uuid=result.uuid,
                floating_gateway=result.floating_gateway,
                hosteddns=dns if dns else {},
            )
    except OperationalError as e:
        LOG.warning(
            f'MariaDB get failed for '
            f'network_attributes {net_uuid}: {e}')
        return None


def _network_attributes_column_values(
        data: NetworkAttributesData,
        fields: Optional[List[str]] = None) -> Dict[str, Any]:
    """Map NetworkAttributesData fields to their column values.

    fields limits the result to the named model fields; None or an
    empty list means every column. See
    _instance_attributes_column_values for why single-attribute
    writers must name their field.
    """
    all_values: Dict[str, Any] = {
        'floating_gateway': data.floating_gateway,
        'hosteddns': _json_dumps(data.hosteddns),
    }
    if not fields:
        return all_values

    unknown = set(fields) - set(all_values)
    if unknown:
        raise ValueError(
            f'unknown network attribute fields: {sorted(unknown)}')
    return {field: all_values[field] for field in fields}


def _direct_update_network_attributes(
        data: NetworkAttributesData,
        fields: Optional[List[str]] = None) -> bool:
    """Update Network attributes in MariaDB.

    fields is the list of model field names to write; None or empty
    writes every column.
    """
    engine = _get_engine()
    table = _get_network_attributes_table()

    try:
        with engine.connect() as conn:
            stmt = sa.update(table).where(
                table.c.uuid == data.uuid
            ).values(
                **_network_attributes_column_values(data, fields))
            result = conn.execute(stmt)
            conn.commit()
            return result.rowcount > 0
    except OperationalError as e:
        LOG.warning(
            f'MariaDB update failed for '
            f'network_attributes {data.uuid}: {e}')
        return False


def _direct_delete_network_attributes(
        net_uuid: UUID) -> bool:
    """Delete Network attributes from MariaDB."""
    engine = _get_engine()
    table = _get_network_attributes_table()

    try:
        with engine.connect() as conn:
            stmt = sa.delete(table).where(
                table.c.uuid == net_uuid)
            result = conn.execute(stmt)
            conn.commit()
            return result.rowcount > 0
    except OperationalError as e:
        LOG.warning(
            f'MariaDB delete failed for '
            f'network_attributes {net_uuid}: {e}')
        return False


# =============================================================================
# Network gRPC Client Functions
# These call the database microservice for Network operations.
# =============================================================================

def _grpc_create_network(data: NetworkData) -> bool:
    """Create a Network record via the database microservice."""
    try:
        stub = _get_database_stub()
        request = database_pb2.CreateNetworkRequest(
            network=database_pb2.NetworkStaticData(
                uuid=str(data.uuid),
                name=data.name,
                namespace=data.namespace or '',
                netblock=data.netblock,
                provide_dhcp=data.provide_dhcp,
                provide_nat=data.provide_nat,
                provide_dns=data.provide_dns,
                vxid=data.vxid,
                egress_nic=data.egress_nic or '',
                mesh_nic=data.mesh_nic or '',
                version=data.version
            )
        )
        reply = _grpc_call(stub.CreateNetwork, request)
        return bool(reply.success)
    except grpc.RpcError as e:
        LOG.error(
            f'gRPC CreateNetwork failed for {data.uuid}: {e}')
        return False


def _grpc_get_network(
        net_uuid: UUID) -> Optional[NetworkData]:
    """Get Network static values via the database microservice."""
    try:
        stub = _get_database_stub()
        request = database_pb2.GetNetworkRequest(
            uuid=str(net_uuid))
        reply = _grpc_call(stub.GetNetwork, request)
        if not reply.found:
            return None
        d = reply.network
        return NetworkData(
            uuid=d.uuid,
            name=d.name,
            namespace=d.namespace or None,
            netblock=d.netblock,
            provide_dhcp=d.provide_dhcp,
            provide_nat=d.provide_nat,
            provide_dns=d.provide_dns,
            vxid=d.vxid,
            egress_nic=d.egress_nic or None,
            mesh_nic=d.mesh_nic or None,
            version=d.version
        )
    except grpc.RpcError as e:
        LOG.error(
            f'gRPC GetNetwork failed for {net_uuid}: {e}')
        return None


def _grpc_get_all_networks() -> list[NetworkData]:
    """Get all Network records via the database microservice."""
    try:
        stub = _get_database_stub()
        request = database_pb2.GetAllNetworksRequest()
        reply = _grpc_call(stub.GetAllNetworks, request)
        return [
            NetworkData(
                uuid=d.uuid,
                name=d.name,
                namespace=d.namespace or None,
                netblock=d.netblock,
                provide_dhcp=d.provide_dhcp,
                provide_nat=d.provide_nat,
                provide_dns=d.provide_dns,
                vxid=d.vxid,
                egress_nic=d.egress_nic or None,
                mesh_nic=d.mesh_nic or None,
                version=d.version
            )
            for d in reply.networks
        ]
    except grpc.RpcError as e:
        LOG.error(f'gRPC GetAllNetworks failed: {e}')
        return []


def _grpc_find_network_vxids(vxids: list[int]) -> dict[int, str]:
    """Return the claimed vxids and their networks, via the database
    microservice.

    As with ``_direct_find_network_vxids``, errors are deliberately not
    swallowed: an empty result here means "these vxids are unclaimed"
    and the caller deletes host network devices on the strength of it.
    """
    if not vxids:
        return {}

    stub = _get_database_stub()
    request = database_pb2.FindNetworkVxidsRequest(vxids=vxids)
    reply = _grpc_call(stub.FindNetworkVxids, request)
    return {claim.vxid: claim.uuid for claim in reply.claims}


def _grpc_get_node_instance_vxids(
        node_uuid: str, states: list[str]) -> set[int]:
    """The vxids used by instances on a node, via the database
    microservice.

    As with ``_direct_get_node_instance_vxids``, errors are deliberately
    not swallowed: an empty result here means "no instance on this node
    uses that network" and the caller tears down host network devices on
    the strength of it.
    """
    if not states:
        return set()

    stub = _get_database_stub()
    request = database_pb2.GetNodeInstanceVxidsRequest(
        node_uuid=node_uuid, states=list(states))
    reply = _grpc_call(stub.GetNodeInstanceVxids, request)
    return set(reply.vxids)


def _grpc_find_networks(
        criteria: ObjectFilterCriteria) -> list[NetworkData]:
    """Find networks matching criteria via the database microservice."""
    try:
        stub = _get_database_stub()
        proto_criteria = database_pb2.ObjectFilterCriteria(
            states=criteria.states if criteria.states is not None else []
        )
        if criteria.namespace is not None:
            proto_criteria.namespace = criteria.namespace
        if criteria.name is not None:
            proto_criteria.name = criteria.name
        request = database_pb2.FindNetworksRequest(
            criteria=proto_criteria)
        reply = _grpc_call(stub.FindNetworks, request)
        return [
            NetworkData(
                uuid=d.uuid,
                name=d.name,
                namespace=d.namespace or None,
                netblock=d.netblock,
                provide_dhcp=d.provide_dhcp,
                provide_nat=d.provide_nat,
                provide_dns=d.provide_dns,
                vxid=d.vxid,
                egress_nic=d.egress_nic or None,
                mesh_nic=d.mesh_nic or None,
                version=d.version
            )
            for d in reply.networks
        ]
    except grpc.RpcError as e:
        LOG.error(f'gRPC FindNetworks failed: {e}')
        return []


def _grpc_delete_network(net_uuid: UUID) -> bool:
    """Delete a Network record via the database microservice."""
    try:
        stub = _get_database_stub()
        request = database_pb2.DeleteNetworkRequest(
            uuid=str(net_uuid))
        reply = _grpc_call(stub.DeleteNetwork, request)
        return bool(reply.success)
    except grpc.RpcError as e:
        LOG.error(
            f'gRPC DeleteNetwork failed for {net_uuid}: {e}')
        return False


