# =============================================================================
# Network Public API Functions
# These route to either direct or gRPC access based on configuration.
# =============================================================================

def create_network(data: NetworkData) -> bool:
    """Create a Network record.

    Args:
        data: The NetworkData to insert.

    Returns:
        True if created, False if already exists or error.
    """
    if _use_database_service():
        return _grpc_create_network(data)
    return _direct_create_network(data)


def get_network(net_uuid: UUID) -> Optional[NetworkData]:
    """Get Network static values.

    Args:
        net_uuid: The UUID of the Network.

    Returns:
        A NetworkData object, or None if not found.
    """
    cached: Optional[NetworkData] = _object_cache_get('network', net_uuid)
    if cached is not None:
        return cached
    if _use_database_service():
        row = _grpc_get_network(net_uuid)
    else:
        row = _direct_get_network(net_uuid)
    _object_cache_put('network', net_uuid, row, config.OBJECT_CACHE_TTL_IMMUTABLE)
    return row


def get_all_networks() -> list[NetworkData]:
    """Get all Network records.

    Returns:
        List of NetworkData objects.
    """
    if _use_database_service():
        return _grpc_get_all_networks()
    return _direct_get_all_networks()


def find_network_vxids(vxids: list[int]) -> dict[int, str]:
    """Return the supplied vxids which a network claims, and its uuid.

    Args:
        vxids: Candidate VXLAN ids.

    Returns:
        A mapping of vxid to network uuid for every supplied vxid which
        has a networks row, regardless of the network's state. Errors
        propagate rather than presenting as an empty result -- see
        ``_direct_find_network_vxids``.
    """
    if not vxids:
        return {}
    if _use_database_service():
        return _grpc_find_network_vxids(vxids)
    return _direct_find_network_vxids(vxids)


def get_node_instance_vxids(node_uuid: str, states: list[str]) -> set[int]:
    """The vxids of networks used by instances placed on a node.

    Args:
        node_uuid: The UUID of the node.
        states: The instance states to consider.

    Returns:
        The set of vxids of every network an instance on that node, in
        one of those states, has an undeleted interface on. Errors
        propagate rather than presenting as an empty result -- see
        ``_direct_get_node_instance_vxids``.
    """
    if not states:
        return set()
    if _use_database_service():
        return _grpc_get_node_instance_vxids(node_uuid, states)
    return _direct_get_node_instance_vxids(node_uuid, states)


def find_networks(
        criteria: ObjectFilterCriteria) -> list[NetworkData]:
    """Find networks matching the given filter criteria.

    Args:
        criteria: Filter criteria (states, namespace, name).

    Returns:
        List of matching NetworkData objects.
    """
    if _use_database_service():
        return _grpc_find_networks(criteria)
    return _direct_find_networks(criteria)


def delete_network(net_uuid: UUID) -> bool:
    """Delete a Network record.

    Args:
        net_uuid: The UUID of the Network.

    Returns:
        True if deleted, False if not found or error.
    """
    if _use_database_service():
        result = _grpc_delete_network(net_uuid)
    else:
        result = _direct_delete_network(net_uuid)
    _object_cache_evict('network', net_uuid)
    return result


def create_network_attributes(
        data: NetworkAttributesData) -> bool:
    """Create Network attributes record.

    Args:
        data: The NetworkAttributesData to create.

    Returns:
        True if created, False if already exists or error.
    """
    if _use_database_service():
        return _grpc_create_network_attributes(data)
    return _direct_create_network_attributes(data)


def get_network_attributes(
        net_uuid: UUID) -> Optional[NetworkAttributesData]:
    """Get Network attributes.

    Args:
        net_uuid: The UUID of the Network.

    Returns:
        A NetworkAttributesData object, or None if not found.
    """
    if _use_database_service():
        return _grpc_get_network_attributes(net_uuid)
    return _direct_get_network_attributes(net_uuid)


def update_network_attributes(
        data: NetworkAttributesData,
        fields: Optional[List[str]]) -> bool:
    """Update Network attributes.

    Args:
        data: The NetworkAttributesData with updated values.
        fields: The model field names to write. None or empty writes
            every column. Callers changing one attribute should name
            it so concurrent writers of the other attribute on the
            same row cannot lose their update to this writer's
            read-modify-write (the Network object also caches its
            attributes in memory, so its row snapshot can be
            arbitrarily stale).

    Returns:
        True if updated, False if not found or error.
    """
    # Validate the mask before dispatch so a bad field name raises
    # ValueError on the gRPC path too, rather than becoming a silent
    # StatusReply failure the caller discards.
    _network_attributes_column_values(data, fields)
    if _use_database_service():
        return _grpc_update_network_attributes(data, fields=fields)
    return _direct_update_network_attributes(data, fields=fields)


def delete_network_attributes(net_uuid: UUID) -> bool:
    """Delete Network attributes.

    Args:
        net_uuid: The UUID of the Network.

    Returns:
        True if deleted, False if not found or error.
    """
    if _use_database_service():
        return _grpc_delete_network_attributes(net_uuid)
    return _direct_delete_network_attributes(net_uuid)


# =============================================================================
# AgentOperation Table Definitions
# =============================================================================

def _get_agent_operations_table() -> sa.Table:
    """Get or create the agent_operations table definition.

    This table stores static values for AgentOperation objects.
    AgentOperations represent in-guest agent tasks queued against
    an Instance.

    The table schema is generated from the AgentOperationData
    Pydantic model. The uuid is the primary key, with an index on
    instance_uuid.
    """
    global _agent_operations_table
    if _agent_operations_table is None:
        with TABLE_CREATION_LOCK:
            if _agent_operations_table is not None:
                return _agent_operations_table
            metadata = _get_metadata()
            _agent_operations_table = pydantic_to_sqlalchemy_table(
                AgentOperationData,
                'agent_operations',
                metadata,
                primary_key_fields=['uuid'],
                include_id_column=False
            )
    return _agent_operations_table


def _get_agent_operation_attributes_table() -> sa.Table:
    """Get or create the agent_operation_attributes table definition."""
    global _agent_operation_attributes_table
    if _agent_operation_attributes_table is None:
        with TABLE_CREATION_LOCK:
            if _agent_operation_attributes_table is not None:
                return _agent_operation_attributes_table
            metadata = _get_metadata()
            _agent_operation_attributes_table = pydantic_to_sqlalchemy_table(
                AgentOperationAttributesData,
                'agent_operation_attributes',
                metadata,
                primary_key_fields=['uuid'],
                include_id_column=False
            )
    return _agent_operation_attributes_table


def _ensure_agent_operations_schema(
        engine: sa.Engine) -> dict[str, Any]:
    """Ensure the agent_operations table schema is up to date."""
    table_name = 'agent_operations'
    current_ver = _get_table_version(engine, table_name)
    start_ver = current_ver
    table = _get_agent_operations_table()

    # Version 0 or -1 means table doesn't exist yet - create it at the
    # current schema version. The historical v1->v2 step was the etcd
    # data-import marker; with etcd purged, fresh installs are at the
    # target version by construction.
    if current_ver <= 0:
        LOG.info(f'Creating {table_name} table (version {AGENT_OPERATIONS_VERSION})')
        table.metadata.create_all(
            engine, tables=[table], checkfirst=True)

        with engine.connect() as conn:
            for idx in table.indexes:
                try:
                    idx.create(conn, checkfirst=True)
                except Exception as e:
                    LOG.debug(
                        f'Index {idx.name} creation skipped: {e}')

        current_ver = AGENT_OPERATIONS_VERSION
        _set_table_version(engine, table_name, current_ver)

    if current_ver < AGENT_OPERATIONS_VERSION:
        # Add the agent operation deadline columns. Both are nullable
        # with no backfill, because NULL is a meaningful value here
        # rather than a gap: it means no client intent was recorded,
        # so the server default applies. An explicit 0.0 is what
        # "the client asked for none" looks like. Safe to run
        # repeatedly -- ADD COLUMN IF NOT EXISTS is a no-op when the
        # column already exists, which is the case on a new deployment
        # where create_all() included it.
        LOG.info(
            f'Upgrading {table_name} table to version '
            f'{AGENT_OPERATIONS_VERSION} (add deadline columns)')
        #
        # A failure here is deliberately not caught. IF NOT EXISTS
        # already makes "the column is there" a no-op, so anything
        # this could swallow is a genuine failure -- a metadata lock
        # timeout against a busy table, a privilege problem, disk
        # full. Swallowing it and bumping the version anyway would
        # leave a schema which reports itself healthy to
        # verify_schema_versions() (it compares versions, not
        # columns) while every insert fails on an unknown column,
        # and which ensure-mariadb-schema can no longer repair
        # because the `current_ver < VERSION` guard would now be
        # false. Failing loudly keeps the migration re-runnable.
        with engine.connect() as conn:
            for column in ('deadline DOUBLE NULL',
                           'progress_timeout DOUBLE NULL'):
                conn.execute(sa.text(
                    f'ALTER TABLE {table_name} '
                    f'ADD COLUMN IF NOT EXISTS {column}'))
                conn.commit()

        current_ver = AGENT_OPERATIONS_VERSION
        _set_table_version(engine, table_name, current_ver)

    return {
        'table': table_name,
        'start_version': start_ver,
        'end_version': current_ver,
        'target_version': AGENT_OPERATIONS_VERSION,
        'migrated': start_ver != current_ver
    }


def _ensure_agent_operation_attributes_schema(
        engine: sa.Engine) -> dict[str, Any]:
    """Ensure the agent_operation_attributes table schema is up to date."""
    table_name = 'agent_operation_attributes'
    current_ver = _get_table_version(engine, table_name)
    start_ver = current_ver
    table = _get_agent_operation_attributes_table()

    # Version 0 or -1 means table doesn't exist yet - create it at the
    # current schema version. The historical v1->v2 step was the etcd
    # data-import marker; with etcd purged, fresh installs are at the
    # target version by construction.
    if current_ver <= 0:
        LOG.info(f'Creating {table_name} table (version {AGENT_OPERATION_ATTRIBUTES_VERSION})')
        table.metadata.create_all(
            engine, tables=[table], checkfirst=True)

        with engine.connect() as conn:
            for idx in table.indexes:
                try:
                    idx.create(conn, checkfirst=True)
                except Exception as e:
                    LOG.debug(
                        f'Index {idx.name} creation skipped: {e}')

        current_ver = AGENT_OPERATION_ATTRIBUTES_VERSION
        _set_table_version(engine, table_name, current_ver)

    if current_ver < AGENT_OPERATION_ATTRIBUTES_VERSION:
        # Add the progress and retry bookkeeping columns.
        # last_progress is nullable (NULL means no progress observed
        # yet); attempts is not, and carries an explicit DEFAULT 0.
        # MariaDB would fill existing rows with the implicit type
        # default anyway, so the DEFAULT is not rescuing a failing
        # ALTER -- it is there so the value backfilled into existing
        # rows is deterministic rather than a function of sql_mode.
        # It is a deliberate divergence from what create_all()
        # produces on a fresh database, since
        # pydantic_to_sqlalchemy_table has no server-default support,
        # and it is harmless because every insert supplies the value.
        # Safe to run repeatedly.
        LOG.info(
            f'Upgrading {table_name} table to version '
            f'{AGENT_OPERATION_ATTRIBUTES_VERSION} '
            '(add progress and attempt columns)')
        #
        # As in _ensure_agent_operations_schema, a failing ALTER is
        # allowed to propagate rather than being logged and stepped
        # over: bumping the version past a column which was never
        # added produces a schema that passes verify_schema_versions()
        # and can never be repaired by re-running the migration.
        with engine.connect() as conn:
            for column in ('last_progress DOUBLE NULL',
                           'attempts BIGINT NOT NULL DEFAULT 0'):
                conn.execute(sa.text(
                    f'ALTER TABLE {table_name} '
                    f'ADD COLUMN IF NOT EXISTS {column}'))
                conn.commit()

        current_ver = AGENT_OPERATION_ATTRIBUTES_VERSION
        _set_table_version(engine, table_name, current_ver)

    return {
        'table': table_name,
        'start_version': start_ver,
        'end_version': current_ver,
        'target_version': AGENT_OPERATION_ATTRIBUTES_VERSION,
        'migrated': start_ver != current_ver
    }


# =============================================================================
# AgentOperation Direct Access Functions
# These are used by the database daemon for AgentOperation object storage.
# =============================================================================

def _direct_create_agent_operation(data: AgentOperationData) -> bool:
    """Create an AgentOperation record in MariaDB.

    Args:
        data: The AgentOperationData to insert.

    Returns:
        True if created successfully, False if duplicate or error.
    """
    engine = _get_engine()
    table = _get_agent_operations_table()

    try:
        with engine.connect() as conn:
            stmt = sa.insert(table).values(
                uuid=data.uuid,
                namespace=data.namespace,
                instance_uuid=data.instance_uuid,
                commands=_json_dumps(data.commands),
                deadline=data.deadline,
                progress_timeout=data.progress_timeout,
                version=data.version
            )
            conn.execute(stmt)
            conn.commit()
            return True
    except IntegrityError:
        return False
    except OperationalError as e:
        LOG.warning(
            f'MariaDB create failed for '
            f'agent_operation {data.uuid}: {e}')
        return False


def _direct_get_agent_operation(
        aop_uuid: UUID) -> Optional[AgentOperationData]:
    """Get AgentOperation static values from MariaDB.

    Args:
        aop_uuid: The UUID of the AgentOperation.

    Returns:
        An AgentOperationData object, or None if not found.
    """
    engine = _get_engine()
    table = _get_agent_operations_table()

    try:
        with engine.connect() as conn:
            stmt = sa.select(table).where(
                table.c.uuid == aop_uuid)
            result = conn.execute(stmt).fetchone()

            if result is None:
                return None

            # Parse JSON commands field
            commands = result.commands
            if isinstance(commands, str):
                commands = json.loads(commands)

            return AgentOperationData(
                uuid=result.uuid,
                namespace=result.namespace,
                instance_uuid=result.instance_uuid,
                commands=commands if commands else [],
                deadline=result.deadline,
                progress_timeout=result.progress_timeout,
                version=result.version
            )
    except OperationalError as e:
        LOG.warning(
            f'MariaDB get failed for '
            f'agent_operation {aop_uuid}: {e}')
        return None


def _direct_delete_agent_operation(aop_uuid: UUID) -> bool:
    """Delete an AgentOperation record from MariaDB.

    Args:
        aop_uuid: The UUID of the AgentOperation to delete.

    Returns:
        True if deleted, False if not found or error.
    """
    engine = _get_engine()
    table = _get_agent_operations_table()

    try:
        with engine.connect() as conn:
            stmt = sa.delete(table).where(
                table.c.uuid == aop_uuid)
            result = conn.execute(stmt)
            conn.commit()
            return result.rowcount > 0
    except OperationalError as e:
        LOG.warning(
            f'MariaDB delete failed for '
            f'agent_operation {aop_uuid}: {e}')
        return False


def _direct_create_agent_operation_attributes(
        data: AgentOperationAttributesData) -> bool:
    """Create an agent_operation_attributes record in MariaDB."""
    engine = _get_engine()
