    try:
        stub = _get_database_stub()
        target_msgs = [
            database_pb2.CreateAndEnqueueClusterOperationTarget(
                target_object_type=cast(
                    shakenfist_enums_pb2.ObjectType.ValueType,
                    target_object_type.proto_id),
                target_uuid=target_uuid,
            )
            for target_object_type, target_uuid in (targets or [])
        ]
        request = (
            database_pb2
            .CreateAndEnqueueClusterOperationRequest(
                uuid=str(op_uuid),
                operation_type=operation_type,
                created_at=created_at,
                queue_name=queue_name,
                delay=delay,
                metadata_json=_json_dumps(metadata),
                targets=target_msgs,
            )
        )
        reply = _grpc_call(
            stub.CreateAndEnqueueClusterOperation, request)
        return bool(reply.success), reply.error
    except grpc.RpcError as e:
        LOG.warning(
            f'gRPC CreateAndEnqueueClusterOperation failed for '
            f'{op_uuid}: {e}')
        return False, f'gRPC error: {e}'


