# =============================================================================
# Work Queue Public API Functions
# =============================================================================

def enqueue_work_item(
        queue_name: str, work_item: dict[str, Any],
        delay: float = 0.0) -> None:
    """Insert a work item on a queue.

    Routes to the database microservice or direct MariaDB depending
    on _use_database_service(). Raises
    shakenfist.exceptions.CannotEnqueueWork on unrecoverable failure
    in the direct path; the gRPC path logs and returns.
    """
    if _use_database_service():
        _grpc_work_queue_enqueue(queue_name, work_item, delay)
        return
    _direct_work_queue_enqueue(queue_name, work_item, delay)


def dequeue_work_items(
        queue_names: list[str],
        limit: int = 10,
) -> list[tuple[str, str, dict[str, Any]]]:
    """Claim up to ``limit`` eligible jobs across ``queue_names``.

    Returns a list of ``(queue_name, job_name, payload)`` tuples,
    possibly empty. Items are returned in caller-supplied priority
    order: the first queue_name in the list is highest priority. The
    direct path uses ``config.NODE_NAME`` as worker_id; the gRPC
    path relies on the database daemon's NODE_NAME (the proto does
    not carry a caller-supplied worker_id).

    This single query replaces the previous per-queue dequeue loop;
    a sf-net or sf-queues worker that used to issue 10 sequential
    gRPC calls per idle iteration now issues one. The trade-off is
    that a worker which doesn't immediately execute every returned
    item holds the others claimed until it does -- crashes between
    receive and execute are recovered by the stuck-row reaper
    (``list_stuck_work_queue_rows``).
    """
    if _use_database_service():
        return _grpc_work_queue_dequeue_batch(queue_names, limit)
    return _direct_work_queue_dequeue_batch(
        queue_names, config.NODE_NAME, limit)


def resolve_work_item(queue_name: str, job_name: str) -> None:
    """Mark a claimed job complete."""
    if _use_database_service():
        _grpc_work_queue_resolve(queue_name, job_name)
        return
    _direct_work_queue_resolve(queue_name, job_name)


def get_work_queue_length(
        queue_name: str) -> tuple[int, int, int]:
    """Return (processing, queued, deferred) counts for a queue."""
    if _use_database_service():
        return _grpc_work_queue_length(queue_name)
    return _direct_work_queue_length(queue_name)


def restart_work_queue(queue_name: str) -> None:
    """Clear claims on a queue so workers re-pick up the jobs.

    Called at queue daemon startup to recover in-flight work after
    a crash.
    """
    if _use_database_service():
        _grpc_work_queue_restart(queue_name)
        return
    _direct_work_queue_restart(queue_name)


def list_stuck_work_queue_rows(
        threshold_seconds: float) -> list[dict[str, Any]]:
    """Return rows whose claim is older than threshold_seconds.

    Used by the cluster daemon reaper to find work items stuck
    in flight. Each dict carries id, queue_name, claimed_at,
    claimed_by, attempts and payload. Rows are ordered oldest
    claim first.
    """
    if _use_database_service():
        return _grpc_work_queue_list_stuck(threshold_seconds)
    return _direct_work_queue_list_stuck(threshold_seconds)


def clear_work_queue_claim(row_id: int) -> bool:
    """Clear claimed_at/claimed_by on one work_queue row.

    Returns True if the row existed and was still claimed.
    attempts is not reset, so a persistently-failing job
    eventually trips CLUSTER_OP_MAX_ATTEMPTS.
    """
    if _use_database_service():
        return _grpc_work_queue_clear_claim(row_id)
    return _direct_work_queue_clear_claim(row_id)


def delete_work_queue_row(row_id: int) -> bool:
    """Delete a single work_queue row by id.

    Returns True if the row existed and was deleted. Used by
    the reaper's reject branch; the caller flips the
    corresponding cluster operation to error afterwards.
    """
    if _use_database_service():
        return _grpc_work_queue_delete_row(row_id)
    return _direct_work_queue_delete_row(row_id)


def find_existing_coalescible_op(
        operation_type: str,
        target_column: str,
        target_uuid: str,
        task_name: str) -> Optional[str]:
    """Look up an existing pending coalescible op on the same target.

    Returns its uuid if found, otherwise ``None``. Used by
    ``create_and_enqueue`` for ops whose entire task list is a
    single coalescible task: if a sibling is already in the queue,
    skip the insert and return the existing op's uuid so all
    waiters block on the same op.
    """
    if _use_database_service():
        return _grpc_find_existing_coalescible_op(
            operation_type, target_column, target_uuid, task_name)
    return _direct_find_existing_coalescible_op(
        operation_type, target_column, target_uuid, task_name)


def claim_coalescible_siblings(
        operation_type: str,
        target_column: str,
        target_uuid: str,
        task_names: list[str],
        exclude_op_uuid: str) -> list[str]:
    """Atomically fold sibling pending coalescible ops.

    Used by ``BaseClusterOperation.execute`` before running a
    coalescible task. The server transitions every matching
    sibling's ``object_states`` row to ``complete`` in one
    statement, then returns the affected uuids. See
    ``_direct_claim_coalescible_siblings`` for the safety guards
    (matched only single-task siblings in state ``queued``, never
    folds the survivor).

    Callers pre-filter ``task_names`` to the op class's
    ``coalescible_tasks`` set and pre-supply
    ``coalescible_target_column`` so this helper stays generic
    across op types.
    """
    if _use_database_service():
        return _grpc_claim_coalescible_siblings(
            operation_type, target_column, target_uuid,
            task_names, exclude_op_uuid)
    return _direct_claim_coalescible_siblings(
        operation_type, target_column, target_uuid,
        task_names, exclude_op_uuid)


# =============================================================================
# Orphan reconciliation (issue 3534)
#
# MariaDB can end up with two kinds of orphaned object rows, both invisible
# to every state-driven iterator:
#
# - Phantoms: an object_states row whose static-values row is gone. All
#   iterators hydrate via from_db(), which fails, so the object is silently
#   skipped forever while its state row is re-read every sweep.
# - Zombies: a static-values row with no object_states row, produced by a
#   crash between static-row creation and the first state write (or a
#   partially failed hard delete). State-based listing never returns the
#   object, so nothing ever cleans it up.
#
# Format note: object_states.object_uuid stores the dashed 36 character
# uuid form, while the static tables use sa.Uuid columns storing undashed
# CHAR(32). The queries below transform the *outer* row's value so the
# inner (per-row) lookup always lands on a primary key index.
# =============================================================================

# Static-values table getter (and primary key column) for each object type
# that has one. Types absent here are not reconciled. All cluster operation
# types share the cluster_operations table, distinguished by its
# operation_type column (handled below by inspecting table columns).
_STATIC_TABLE_GETTERS: dict[str, tuple[Callable[[], sa.Table], str]] = {
    ObjectType.AGENTOPERATION.value: (_get_agent_operations_table, 'uuid'),
    ObjectType.ARTIFACT.value: (_get_artifacts_table, 'uuid'),
    ObjectType.BLOB.value: (_get_blobs_table, 'uuid'),
    ObjectType.DHCP.value: (_get_dnsmasq_table, 'uuid'),
    ObjectType.INSTANCE.value: (_get_instances_table, 'uuid'),
    ObjectType.INTERFACE.value: (_get_network_interfaces_table, 'uuid'),
    ObjectType.IPAM.value: (_get_ipams_table, 'uuid'),
    # mapping_rule and trusted_issuer were missing from this map from the
    # day federated identity landed, the same omission as namespace_key
    # (issue 3588) in two more object types (issue 3788). The parity test
    # against constants.OBJECT_NAMES_TO_CLASSES now pins the invariant.
    ObjectType.MAPPING_RULE.value: (_get_mapping_rules_table, 'uuid'),
    ObjectType.NAMESPACE.value: (_get_namespaces_table, 'name'),
    # namespace_key was missing from this map from the day the object
    # landed, so the reconciler never repaired zombie keys: 4,151
    # stateless keys from the cutover deploy's mixed-version window sat
    # unrepairable while the expiry sweep re-evented every one of them
    # every pass, ~380k junk audit events/day (issue 3588).
    ObjectType.NAMESPACE_KEY.value: (_get_namespace_keys_table, 'uuid'),
    ObjectType.NAMESPACE_CLAIM.value: (_get_namespace_claims_table, 'uuid'),
    ObjectType.NETWORK.value: (_get_networks_table, 'uuid'),
    ObjectType.NODE.value: (_get_nodes_table, 'uuid'),
    ObjectType.TRUSTED_ISSUER.value: (_get_trusted_issuers_table, 'uuid'),
    ObjectType.UPLOAD.value: (_get_uploads_table, 'uuid'),
    ObjectType.ARTIFACT_FETCH_OP.value: (_get_cluster_operations_table, 'uuid'),
    ObjectType.IMGCACHE_OP.value: (_get_cluster_operations_table, 'uuid'),
    ObjectType.NET_IFACE_OP.value: (_get_cluster_operations_table, 'uuid'),
    ObjectType.NET_IFACE_IP_OP.value: (_get_cluster_operations_table, 'uuid'),
    ObjectType.NET_IP_OP.value: (_get_cluster_operations_table, 'uuid'),
    ObjectType.NET_MACADDR_IP_OP.value: (_get_cluster_operations_table, 'uuid'),
    ObjectType.NET_OP.value: (_get_cluster_operations_table, 'uuid'),
    ObjectType.NODE_AOP_OP.value: (_get_cluster_operations_table, 'uuid'),
    ObjectType.NODE_BLOB_OP.value: (_get_cluster_operations_table, 'uuid'),
    ObjectType.NODE_INST_NET_IFACE_OP.value: (
        _get_cluster_operations_table, 'uuid'),
    ObjectType.NODE_INST_NETDESC_OP.value: (
        _get_cluster_operations_table, 'uuid'),
    ObjectType.NODE_INST_OP.value: (_get_cluster_operations_table, 'uuid'),
    ObjectType.NODE_INST_SNAP_OP.value: (
        _get_cluster_operations_table, 'uuid'),
    ObjectType.NODE_NET_OP.value: (_get_cluster_operations_table, 'uuid'),
}

# The object types the reconciliation sweep iterates.
ORPHAN_RECONCILABLE_OBJECT_TYPES: list[str] = sorted(_STATIC_TABLE_GETTERS)


def _dashed_uuid_expr(col: Any) -> Any:
    """Render an undashed CHAR(32) uuid column in the dashed 36 character
    form used by object_states.object_uuid, so a comparison against
    object_states can use its primary key index.

    Built with the string concatenation operator rather than the CONCAT
    function so SQLAlchemy renders it per-dialect: sqlite (used by the
    unit tests) only grew a CONCAT function in 3.44, but has always
    supported ``||``."""
    c = sa.cast(col, sa.String(36))

    def part(start: int, length: int) -> Any:
        return sa.func.substr(c, start, length, type_=sa.String())

    return (part(1, 8) + '-' + part(9, 4) + '-' + part(13, 4) + '-' +
            part(17, 4) + '-' + part(21, 12))


def _static_table_for_object_type(
        object_type: ObjectType) -> Optional[tuple[sa.Table, str]]:
    entry = _STATIC_TABLE_GETTERS.get(object_type.value)
    if not entry:
        return None
    getter, pk = entry
    return getter(), pk


def _direct_delete_orphaned_object_states(
        object_type: ObjectType,
        updated_before: float) -> Optional[int]:
    """Delete phantom object_states rows for one object type.

    A row is a phantom when no static-values row exists for its uuid.
    ``updated_before`` guards against racing object creation, where the
    static and state rows are written moments apart.

    Returns the number of rows deleted, or None on error.
    """
    entry = _static_table_for_object_type(object_type)
    if entry is None:
        return 0
    static, pk = entry

    engine = _get_engine()
    states = _get_object_states_table()

    # The static tables store undashed uuids; strip the dashes from the
    # outer object_states value so the correlated lookup uses the static
    # table's primary key index. Namespaces key on name, compared as-is.
    if pk == 'name':
        match = static.c[pk] == states.c.object_uuid
    else:
        match = static.c[pk] == sa.func.replace(
            states.c.object_uuid, '-', '')

    exists_clauses = [match]
    if 'operation_type' in static.c:
        exists_clauses.append(static.c.operation_type == object_type.value)

    try:
        with engine.begin() as conn:
            stmt = sa.delete(states).where(sa.and_(
                states.c.object_type == object_type,
                states.c.update_time < updated_before,
                ~sa.exists(
                    sa.select(sa.literal(1)).where(sa.and_(*exists_clauses)))
            ))
            result = conn.execute(stmt)
            return int(result.rowcount)
    except OperationalError as e:
        LOG.warning(
            f'MariaDB delete of orphaned {object_type} states failed: {e}')
        return None


def _grpc_delete_orphaned_object_states(
        object_type: ObjectType,
        updated_before: float) -> Optional[int]:
    try:
        stub = _get_database_stub()
        request = database_pb2.DeleteOrphanedObjectStatesRequest(
            object_type=cast(
                shakenfist_enums_pb2.ObjectType.ValueType,
                object_type.proto_id),
            updated_before=updated_before
        )
        reply = _grpc_call(stub.DeleteOrphanedObjectStates, request)
        if not reply.success:
            return None
        return int(reply.deleted)
    except grpc.RpcError as e:
        LOG.error(
            f'gRPC DeleteOrphanedObjectStates failed for {object_type}: {e}')
        return None


def delete_orphaned_object_states(
        object_type: ObjectType,
        updated_before: float) -> Optional[int]:
    """Delete object_states rows for this type with no static-values row.

    Args:
        object_type: The type of object.
        updated_before: Only rows whose update_time is older than this
            unix timestamp are considered, so freshly-created objects
            whose static row landed moments before their state row are
            never affected.

    Returns:
        The number of rows deleted, or None on error.
    """
    if _use_database_service():
        return _grpc_delete_orphaned_object_states(
            object_type, updated_before)
    return _direct_delete_orphaned_object_states(object_type, updated_before)


def _direct_get_stateless_object_uuids(
        object_type: ObjectType) -> Optional[list[str]]:
    """List zombie static rows for one object type.

    A static-values row is a zombie when no object_states row exists for
    its uuid. Returns dashed uuid strings (or names for namespaces), or
    None on error.
    """
    entry = _static_table_for_object_type(object_type)
    if entry is None:
        return []
    static, pk = entry

    engine = _get_engine()
    states = _get_object_states_table()

    # Render the outer static uuid in the dashed form object_states uses,
    # so the correlated lookup lands on the object_states primary key.
    # Namespaces key on name, compared as-is.
    if pk == 'name':
        match = states.c.object_uuid == static.c[pk]
    else:
        match = states.c.object_uuid == _dashed_uuid_expr(static.c[pk])

    where = [~sa.exists(sa.select(sa.literal(1)).where(sa.and_(
        match, states.c.object_type == object_type)))]
    if 'operation_type' in static.c:
        where.append(static.c.operation_type == object_type.value)

    try:
        with engine.connect() as conn:
            stmt = sa.select(static.c[pk]).where(sa.and_(*where))
            result = conn.execute(stmt).fetchall()
            return [str(row[0]) for row in result]
    except OperationalError as e:
        LOG.warning(
            f'MariaDB stateless uuid query failed for {object_type}: {e}')
        return None


def _grpc_get_stateless_object_uuids(
        object_type: ObjectType) -> Optional[list[str]]:
    try:
        stub = _get_database_stub()
        request = database_pb2.GetStatelessObjectUuidsRequest(
            object_type=cast(
                shakenfist_enums_pb2.ObjectType.ValueType,
                object_type.proto_id)
        )
        reply = _grpc_call(stub.GetStatelessObjectUuids, request)
        return list(reply.object_uuids)
    except grpc.RpcError as e:
        _log_failed_read('GetStatelessObjectUuids', e, target=str(object_type))
        return None


def get_stateless_object_uuids(
        object_type: ObjectType) -> Optional[list[str]]:
    """List static-values rows for this type with no object_states row.

    Returns:
        A list of dashed uuid strings (or names for namespaces), or None
        on error.
    """
    if _use_database_service():
        return _grpc_get_stateless_object_uuids(object_type)
    return _direct_get_stateless_object_uuids(object_type)


def _direct_delete_orphaned_artifact_attributes() -> Optional[int]:
    """Delete artifact_attributes rows whose artifact row is gone.

    Both tables store undashed uuids, so no format transform is needed.
    Creation writes the artifacts row before the attributes row, so a
    row without a parent can only be post-deletion garbage.

    Returns the number of rows deleted, or None on error.
    """
    engine = _get_engine()
    attrs = _get_artifact_attributes_table()
    artifacts = _get_artifacts_table()

    try:
        with engine.begin() as conn:
            stmt = sa.delete(attrs).where(~sa.exists(
                sa.select(sa.literal(1)).where(
                    artifacts.c.uuid == attrs.c.uuid)))
            result = conn.execute(stmt)
            return int(result.rowcount)
    except OperationalError as e:
        LOG.warning(
            f'MariaDB delete of orphaned artifact attributes failed: {e}')
        return None


def _grpc_delete_orphaned_artifact_attributes() -> Optional[int]:
    try:
        stub = _get_database_stub()
        request = database_pb2.DeleteOrphanedArtifactAttributesRequest()
        reply = _grpc_call(stub.DeleteOrphanedArtifactAttributes, request)
        if not reply.success:
            return None
        return int(reply.deleted)
    except grpc.RpcError as e:
        LOG.error(f'gRPC DeleteOrphanedArtifactAttributes failed: {e}')
        return None


def delete_orphaned_artifact_attributes() -> Optional[int]:
    """Delete artifact_attributes rows whose artifact row is gone.

    Returns:
        The number of rows deleted, or None on error.
    """
    if _use_database_service():
        return _grpc_delete_orphaned_artifact_attributes()
    return _direct_delete_orphaned_artifact_attributes()


# =============================================================================
# Scheduler capacity reconcile (scheduler-reservations phase 2)
#
# The reconciler (D5) recomputes every counter in the three capacity
# tables from ground truth in a single RPC: it expires stale namespace
# claims, refreshes per-node limits from the typed node_metrics columns,
# recomputes usage from placed instances (instance_location rows in
# object_references), recomputes the D13 expected-demand decay, and
# rebuilds the cluster_capacity singleton. In this phase the reconciler
# is the only writer of these tables; phase 3's guarded-UPDATE admission
# path turns the recompute into a drift correction.
#
# The limit formulas below deliberately mirror scheduler.py
# (_has_sufficient_cpu/_ram/_disk) so that the phase 3 guard
# ``used + x <= limit`` admits exactly what today's Python filter admits.
# See docs/plans/PLAN-scheduler-reservations-phase-02-capacity-tables.md.
# =============================================================================


def _derive_cpu_memory_limits(
        cpu_schedulable: Optional[int],
        memory_max: Optional[int],
        memory_reserved_mb: Optional[int],
        cpu_overcommit_ratio: float,
        ram_overcommit_ratio: float) -> tuple[Optional[int], Optional[int]]:
    """Derive (limit_cpus, limit_memory_mb) from typed node_metrics values.

    ``limit_cpus`` mirrors one scheduler check exactly: the
    _has_sufficient_cpu bound ``floor(cpu_schedulable ×
    CPU_OVERCOMMIT_RATIO)``.

    ``limit_memory_mb`` does not mirror a single check. It is a
    deliberately conservative blend of two independent ones: the
    overcommit ceiling from _has_sufficient_ram (``memory_max ×
    RAM_OVERCOMMIT_RATIO``, which has no reservation term), reduced by
    the node's published reservation, which comes from the separate
    free-memory check (that one tests ``memory_available -
    memory_reserved_mb``, a measurement of what is free right now rather
    than a ceiling on what may be allocated). Neither scheduler test has
    this shape. It is an allocation ledger, not the KSM-aware
    actual-usage check; the actual-free and actual-usage checks remain
    phase 3 candidate *filters* over the typed node_metrics columns per
    D7, with this as the allocation backstop underneath them.

    A dimension whose inputs are NULL (a metrics row written by an old
    resources daemon mid-upgrade) derives as None so the caller keeps
    the previous limit rather than zeroing it. Note that the mirroring
    of scheduler.py covers the arithmetic but deliberately not the
    inputs: Scheduler._schedulable_threads() and
    Scheduler._memory_reserved_mb() substitute per-node fallbacks for a
    pre-phase-1 metrics row, where this returns None and the caller
    prefers no capacity row to a guessed one. So mid-upgrade the
    scheduler may place on a node that has no capacity row yet. That is
    the conservative direction, but it means the two are not
    interchangeable while an upgrade is in flight.

    ``limit_memory_mb`` is clamped at zero, matching the headroom clamp
    in _derive_disk_limit_gb: a reservation exceeding the overcommit
    ceiling (RAM_OVERCOMMIT_RATIO at or below 1.0 with a large
    NODE_MEMORY_RESERVATION_MB) means the node admits nothing, and zero
    says that without silently dragging the cluster total below the sum
    of the other nodes the way a negative limit would.
    """
    limit_cpus = None
    if cpu_schedulable is not None:
        limit_cpus = math.floor(cpu_schedulable * cpu_overcommit_ratio)

    limit_memory_mb = None
    if memory_max is not None and memory_reserved_mb is not None:
        limit_memory_mb = max(
            0,
            math.floor(memory_max * ram_overcommit_ratio) -
            memory_reserved_mb)

    return limit_cpus, limit_memory_mb


def _derive_disk_limit_gb(
        used_disk_gb: int,
        disk_free_instances: Optional[int],
        disk_reservation_gb: Optional[int],
        disk_overcommit: float) -> Optional[int]:
    """Derive limit_disk_gb from recomputed usage and node_metrics values.

    ``disk_free_instances`` is in bytes (as published by the resources
    daemon); the conversion to GiB matches scheduler.py's
    _has_sufficient_disk. There is no total-disk metric and free space
    is the only ground truth that survives qcow2 growth, so the limit is
    "current virtual drawdown plus what the filesystem says still fits":
    ``used_disk_gb + max(0, floor(disk_free_instances/GiB) -
    disk_reservation_gb) x disk_overcommit``. The phase 3 guard
    ``used + x <= limit`` is then today's free-space check scaled by
    ``disk_overcommit`` on the headroom term only, while accounting
    virtual size (decision P3,
    docs/plans/PLAN-scheduler-reservations-phase-03-primitive.md).
    ``disk_overcommit`` of 1.0 reproduces the pre-ratio arithmetic
    exactly.

    Returns None when the metrics inputs are NULL, so the caller keeps
    the previous limit rather than zeroing it.
    """
    if disk_free_instances is None or disk_reservation_gb is None:
        return None
    if disk_overcommit <= 0:
        # A caller mid-upgrade (an unset proto3 double field reads as
        # 0.0) must not silently zero every node's headroom; 1.0 is the
        # pre-ratio behaviour.
        disk_overcommit = 1.0
    headroom = math.floor(max(
        0, math.floor(disk_free_instances / GiB) - disk_reservation_gb) *
        disk_overcommit)
    return used_disk_gb + headroom


def _decayed_demand_contribution(
        cpus: int,
        age_seconds: float,
        demand_per_vcpu: float,
        demand_decay_seconds: int) -> float:
    """One placement's contribution to a node's expected_demand (D13).

    A placement starts at ``cpus × demand_per_vcpu`` of anticipated load
    and decays linearly to zero over ``demand_decay_seconds`` of
    instance age. Ages outside the window (including negative ages from
    clock skew between the placement writer and the database) clamp to
    the window edges; a non-positive decay window disables the term
    entirely rather than dividing by zero.
    """
    if demand_decay_seconds <= 0:
        return 0.0
    age = max(0.0, age_seconds)
    if age >= demand_decay_seconds:
        return 0.0
    return cpus * demand_per_vcpu * (1.0 - age / demand_decay_seconds)


def disk_spec_virtual_gb(disk_spec: Any) -> int:
    """Sum the virtual sizes (in GB) of a disk_spec JSON list.

    Public because it is the one implementation of "how big is this
    instance's disk claim": instance.py's capacity claim and the queues
    daemon's startup repair must not reimplement the sum, or acquire
    and release drift from the counters the reconciler recomputes.

    This is the executable specification of the JSON_TABLE aggregation in
    _RECONCILE_USAGE_SQL: elements without a numeric ``size`` (missing,
    null, or garbage) contribute 0, and a disk_spec that is not a list
    contributes 0 with a warning. Production reads the SQL, not this --
    validation settled that question in JSON_TABLE's favour -- but the
    live-MariaDB CI job asserts the two agree on the same payloads
    against a real server, so this stays an oracle rather than becoming
    stale prose.

    Fractional sizes follow MariaDB's JSON-number-to-BIGINT cast, which
    rounds half away from zero (10.5 -> 11, -2.5 -> -3, and a numeric
    string "8.7" -> 9) -- probed against a real server rather than
    assumed, because Python's round() would give banker's rounding and
    int() would truncate, and either divergence is exactly the silent
    wrong number this oracle exists to expose. Booleans cast to 0/1 as
    they do in SQL. No current write path produces fractional sizes, so
    this is soundness of the oracle rather than a live behaviour.
    """
    if not isinstance(disk_spec, list):
        LOG.warning(f'Malformed disk_spec (not a list): {disk_spec!r}')
        return 0
    total = 0
    for disk in disk_spec:
        if not isinstance(disk, dict):
            LOG.warning(f'Malformed disk_spec element: {disk!r}')
            continue
        size = disk.get('size')
        if size is None:
            # JSON null casts to SQL NULL, which SUM() ignores.
            continue
        if isinstance(size, bool):
            total += int(size)
            continue
        try:
            total += int(decimal.Decimal(str(size)).quantize(
                decimal.Decimal('1'), rounding=decimal.ROUND_HALF_UP))
        except (decimal.InvalidOperation, TypeError, ValueError):
            LOG.warning(f'Malformed disk_spec size: {size!r}')
    return total


# Usage recompute, grouped by (node, namespace) so one query feeds the
# per-node counters, the per-claim counters and the cluster singleton's
# unclaimed sums. Ground truth is the instance_location rows in
# object_references (source: node uuid, target: instance uuid), joined
# to instances for the allocated resources and to object_states for the
# instance state. Only state 'deleted' is excluded: errored instances
# keep their placement and their resources until hard-delete, so they
# count; a stateless (zombie) instance also counts until the orphan
# reconciler removes it.
#
# Format note (pitfall 6): object_references uuid columns store the
# dashed 36-character form while instances.uuid is sa.Uuid (undashed
# CHAR(32) on MariaDB), so the join transforms the reference-side value
# with REPLACE so the lookup lands on the instances primary key.
# object_states.object_uuid is dashed like object_references, so that
# join compares directly.
#
# These are allocation ledgers, not measurements. used_cpus and
# used_memory_mb sum what every placed, non-deleted instance was
# allocated, which is deliberately not what the resources daemon
# publishes as cpu_total_instance_vcpus and memory_total_instance_actual
# -- those count only *active* libvirt domains. A powered-off instance,
# or one placed but not yet defined in libvirt, still holds its
# reservation here and does not appear there, so used_cpus reads higher
# than today's scheduler filter sees whenever a node has powered-off
# instances. That is the right semantics for a reservation ledger, but
# it means phase 3 must decide explicitly which number its guard uses
# rather than assuming the two agree.
#
# The ledger reads only these INSTANCE_LOCATION rows. The legacy
# node_attributes.instances JSON column, its dual-write and the union
# in Node.instances were removed in scheduler-reservations phase 3
# (this change), so a placement is always visible here once written --
# the precondition for enabling the counter guard is met.
#
# Duplicated placements are the other way this ledger is inexact: a
# lost node's INSTANCE_LOCATION row can survive place_instance()'s
# best-effort removal, so one instance appears on two nodes. This
# node-scoped query counts such an instance once per node, which is
# what a per-node ledger should say, and the cluster row is protected
# because the unclaimed fold is restricted to nodes holding a capacity
# row. The namespace-wide per-claim recompute is the case that can not
# tolerate a duplicate, and it no longer folds this result: it has its
# own statement, _RECONCILE_CLAIM_USAGE_SQL, which de-duplicates by
# instance uuid before summing.
#
# Disk sums virtual sizes from the disk_spec JSON list via JSON_TABLE
# (available since MariaDB 10.6, below the MIN_MARIADB_VERSION floor).
# The derived table aggregates per instance first so the JSON_TABLE only
# ever sees one document at a time. It reads as though it expands every
# instance row -- including the deleted-but-not-hard-deleted backlog,
# which on a long-lived cluster dwarfs the live set -- and then throws
# most of them away in the outer join, so do not "fix" that by
# restricting it to the placement set: MariaDB already resolves it as a
# LATERAL DERIVED correlated on i.uuid, and only expands the instances
# the outer query joins to. Measured at 73,640 instance rows of which
# 1,205 were placed, adding an
# ``i2.uuid IN (SELECT ... FROM object_references)`` restriction turned
# the plan from LATERAL DERIVED into a materialised DERIVED with a
# semi-join and made the query slower (10ms to 13ms), for identical
# results.
#
# The JSON_TYPE guard skips a disk_spec that is somehow not an array, and
# the DEFAULT ... ON EMPTY / ON ERROR clauses make elements without a
# numeric size contribute 0 -- one malformed disk_spec can not abort the
# pass (see disk_spec_virtual_gb for the reference semantics).
#
# The enum-typed predicates span two storage conventions, and the bound
# parameters must match each column's convention exactly.
# object_states.object_type is a native sa.Enum(ObjectType), which
# SQLAlchemy persists as the member *name* ('INSTANCE'); the
# object_references type and relationship columns are plain String(64)
# written by _direct_record_relationship() as str(member), which for
# these str-subclass enums is the *value* ('instance',
# 'instance_location'). The two spellings differ only in case, so a
# mismatched binding still matches under MariaDB's default
# case-insensitive utf8mb4 collations -- and silently returns zero rows
# under utf8mb4_bin or any _cs collation, all of which
# verify_mariadb_compat() accepts. The live test suite runs against
# utf8mb4_bin precisely so a wrong binding here fails loudly.
#
# The reference row's endpoint types are constrained as well as its
# relationship. Nothing writes an INSTANCE_LOCATION row with other
# endpoint types today, so that is defensive rather than load-bearing --
# but the table's primary key and its source index both lead with the
# type columns, so it costs nothing and says out loud what shape of row
# the query expects.
_RECONCILE_USAGE_SQL = sa.text('''
    SELECT r.source_uuid AS node_uuid,
           i.namespace AS namespace,
           COALESCE(SUM(i.cpus), 0) AS used_cpus,
           COALESCE(SUM(i.memory), 0) AS used_memory_mb,
           COALESCE(SUM(d.disk_gb), 0) AS used_disk_gb
      FROM object_references r
      JOIN instances i
        ON i.uuid = REPLACE(r.target_uuid, '-', '')
      LEFT JOIN (
               SELECT i2.uuid AS instance_uuid,
                      COALESCE(SUM(jt.size_gb), 0) AS disk_gb
                 FROM instances i2,
                      JSON_TABLE(i2.disk_spec, '$[*]'
                          COLUMNS (size_gb BIGINT PATH '$.size'
                                   DEFAULT '0' ON EMPTY
                                   DEFAULT '0' ON ERROR)) jt
                WHERE JSON_TYPE(i2.disk_spec) = 'ARRAY'
                GROUP BY i2.uuid) d
        ON d.instance_uuid = i.uuid
      LEFT JOIN object_states s
        ON s.object_uuid = r.target_uuid
       AND s.object_type = :instance_object_type
     WHERE r.relationship = :instance_location
       AND r.source_object_type = :node_object_type
       AND r.target_object_type = :instance_ref_type
       AND (s.state_value IS NULL OR s.state_value != 'deleted')
     GROUP BY r.source_uuid, i.namespace
''')


# The per-claim usage recompute: one set-based statement that rewrites
# used_* on every active claim from the same ground truth
# _RECONCILE_USAGE_SQL reads. It replaces a loop of one UPDATE per
# active claim over a Python fold of that query's rows, which would
# have cost N round trips holding write locks inside the pass's
# transaction once claims became real.
#
# Every convention documented above _RECONCILE_USAGE_SQL applies here
# unchanged, and for the same reasons: the two uuid storage conventions
# (pitfall 6 -- the REPLACE() transform on the dashed reference-side
# uuid so the lookup lands on the undashed instances primary key, and
# the direct comparison against the equally dashed
# object_states.object_uuid), the two enum storage conventions
# (object_states.object_type is a native sa.Enum holding member names,
# the object_references type and relationship columns are String(64)
# holding member values, and the two spellings differ only in case so a
# mismatch is silent under a case-insensitive collation), and the
# JSON_TABLE derived table's handling of a malformed disk_spec.
#
# Two things differ from the node-scoped query, both deliberate.
#
# The placement set is de-duplicated by instance uuid before anything
# is summed. place_instance()'s removal of an old INSTANCE_LOCATION row
# is best-effort, so a lost node can leave a stale row behind and one
# instance then appears on two nodes. A per-node ledger should count
# that instance on both, and does; a namespace-wide quota must count it
# once, because the namespace is holding one instance's worth of
# resources however many placement rows point at it. The SELECT
# DISTINCT is the whole of that fix and is load bearing exactly when a
# placement row is stale -- which is the condition nobody reproduces
# while reading the query. Do not simplify it into a plain join.
#
# The join to namespace_claims is a LEFT JOIN with COALESCE(..., 0)
# rather than an inner one, so a claim whose namespace holds no
# instances is zeroed rather than skipped. An inner join would leave
# such a claim's counters at whatever they last were, forever, which is
# the state a namespace reaches by deleting its last instance.
#
# The statement is namespace-wide by design: unlike the cluster
# singleton's unclaimed fold it is not restricted to nodes holding a
# capacity row, because a namespace quota covers the namespace's
# instances wherever they are stranded.
#
# The aggregation itself is a module-level *fragment* rather than a
# statement, because two callers have to agree on it exactly and one of
# them is not the reconciler. Scheduler-reservations phase 4 seeds a new
# claim's used_* with its namespace's existing drawdown (D3), and if that
# seeding query and this recompute could disagree by so much as a join
# condition, every freshly created claim's counters would flap on every
# reconcile pass -- five minutes apart, forever, and only on the clusters
# whose data happens to expose the difference. Sharing the text is what
# makes "the seed is what the reconciler would have computed" a property
# of the code rather than a claim in a comment.
_NAMESPACE_USAGE_AGGREGATION = '''
               SELECT i.namespace AS namespace,
                      COALESCE(SUM(i.cpus), 0) AS used_cpus,
                      COALESCE(SUM(i.memory), 0) AS used_memory_mb,
                      COALESCE(SUM(d.disk_gb), 0) AS used_disk_gb
                 FROM (SELECT DISTINCT r.target_uuid AS target_uuid
                         FROM object_references r
                        WHERE r.relationship = :instance_location
                          AND r.source_object_type = :node_object_type
                          AND r.target_object_type = :instance_ref_type) p
                 JOIN instances i
                   ON i.uuid = REPLACE(p.target_uuid, '-', '')
                 LEFT JOIN (
                          SELECT i2.uuid AS instance_uuid,
                                 COALESCE(SUM(jt.size_gb), 0) AS disk_gb
                            FROM instances i2,
                                 JSON_TABLE(i2.disk_spec, '$[*]'
                                     COLUMNS (size_gb BIGINT PATH '$.size'
                                              DEFAULT '0' ON EMPTY
                                              DEFAULT '0' ON ERROR)) jt
                           WHERE JSON_TYPE(i2.disk_spec) = 'ARRAY'
                           GROUP BY i2.uuid) d
                   ON d.instance_uuid = i.uuid
                 LEFT JOIN object_states s
                   ON s.object_uuid = p.target_uuid
                  AND s.object_type = :instance_object_type
                WHERE (s.state_value IS NULL OR s.state_value != 'deleted')
                GROUP BY i.namespace'''


_RECONCILE_CLAIM_USAGE_SQL = sa.text(f'''
    UPDATE namespace_claims c
      LEFT JOIN ({_NAMESPACE_USAGE_AGGREGATION}) u
        ON u.namespace = c.namespace
       SET c.used_cpus = COALESCE(u.used_cpus, 0),
           c.used_memory_mb = COALESCE(u.used_memory_mb, 0),
           c.used_disk_gb = COALESCE(u.used_disk_gb, 0),
           c.updated_at = NOW()
     WHERE c.state = 'active'
''')


# One namespace's drawdown, from the identical aggregation the per-claim
# recompute rewrites its counters from. Phase 4's claim creation reads
# this before it opens its transaction and seeds the new row with it
# (D3), so that a claim created for a namespace which already holds
# instances starts life at the figure the next reconcile pass will
# compute, and that pass then moves nothing.
#
# The namespace restriction is deliberately applied *outside* the shared
# fragment rather than inside it, so the two callers execute the same
# text with the same bind parameters and cannot drift apart. It is still
# pushed down to the index: ``namespace`` is the derived table's grouping
# column, which is exactly the shape MariaDB's condition pushdown for
# derived tables handles (on by default since 10.2, well below
# MIN_MARIADB_VERSION), so the predicate lands inside the aggregation
# rather than filtering a cluster-wide fold in the outer query.
#
# A namespace with no placed instances produces no row at all rather than
# a row of zeroes -- the caller reads that as a zero drawdown, which is
# what it is.
_NAMESPACE_DRAWDOWN_SQL = sa.text(f'''
    SELECT u.used_cpus AS used_cpus,
           u.used_memory_mb AS used_memory_mb,
           u.used_disk_gb AS used_disk_gb
      FROM ({_NAMESPACE_USAGE_AGGREGATION}) u
     WHERE u.namespace = :namespace
''')


def _reconcile_reference_params() -> dict[str, str]:
    """The bound parameters both reconcile aggregations need.

    Each is spelt in its own column's storage convention, and the two
    conventions differ. object_states.object_type is a native
    sa.Enum(ObjectType), which SQLAlchemy persists as the member *name*;
    the object_references type and relationship columns are plain
    String(64) written by _direct_record_relationship() as str(member),
    which for these str-subclass enums is the member *value*. The two
    spellings differ only in case, so a mismatch is papered over by a
    case-insensitive collation and silently matches nothing under a
    _bin or _cs one -- see the comment block above _RECONCILE_USAGE_SQL,
    and the live suite, which runs under utf8mb4_bin for this reason.
    """
    return {
        'instance_object_type': ObjectType.INSTANCE.name,
        'instance_ref_type': ObjectType.INSTANCE.value,
        'node_object_type': ObjectType.NODE.value,
        'instance_location': RelationshipType.INSTANCE_LOCATION.value,
    }


def _namespace_drawdown_params(namespace: str) -> dict[str, str]:
    """The bound parameters _NAMESPACE_DRAWDOWN_SQL needs.

    The reconcile reference parameters unchanged -- and for exactly the
    reasons _reconcile_reference_params() documents -- plus the namespace
    being asked about. Sharing that helper is half the point of sharing
    the SQL: two callers spelling the same aggregation but binding it
    differently would silently return different numbers under a
    case-sensitive collation, which is the failure this whole convention
    exists to make loud.
    """
    params = _reconcile_reference_params()
    params['namespace'] = namespace
    return params


def _reconcile_fetch_usage(
        conn: sa.Connection) -> dict[tuple[UUID, str], tuple[int, int, int]]:
    """Recompute usage from ground truth, grouped by (node, namespace).

    Returns {(node_uuid, namespace): (cpus, memory_mb, disk_gb)}. Rows
    whose node uuid does not parse are skipped with a warning (they can
    not be attributed to a capacity row anyway).
    """
    usage: dict[tuple[UUID, str], tuple[int, int, int]] = {}
    rows = conn.execute(
        _RECONCILE_USAGE_SQL, _reconcile_reference_params()).fetchall()
    for row in rows:
        try:
            node_uuid = UUID(str(row.node_uuid))
        except ValueError:
            LOG.warning(
                f'Skipping usage row with malformed node uuid '
                f'{row.node_uuid!r}')
            continue
        usage[(node_uuid, str(row.namespace))] = (
            int(row.used_cpus), int(row.used_memory_mb),
            int(row.used_disk_gb))
    return usage


def _reconcile_fetch_demand(
        conn: sa.Connection,
        now: float,
        demand_per_vcpu: float,
        demand_decay_seconds: int) -> dict[UUID, float]:
    """Recompute expected_demand per node (D13).

    Fetches the placements younger than the decay window (the
    instance_location reference row's ``created`` timestamp is the
    placement time) and folds each one's decayed contribution via
    _decayed_demand_contribution. The set-based query bounds the fetch
    to the recent window, so the Python fold is over a handful of rows
    and the arithmetic is exactly the unit-tested helper.

    Like the metrics freshness check (see the note on
    RECONCILE_METRICS_MAX_AGE_SECONDS), the window comparison spans
    hosts: ``refs.created`` is a client-written float from the placing
    node's clock, compared against this daemon's ``now``. A node
    running fast under-contributes demand and one running slow
    over-contributes; _decayed_demand_contribution's negative-age clamp
    is the mitigation for the slow side.
    """
    demand: dict[UUID, float] = {}
    if demand_decay_seconds <= 0:
        return demand

    refs = _get_object_references_table()
    instances = _get_instances_table()
    states = _get_object_states_table()

    joined = refs.join(
        instances,
        instances.c.uuid == sa.func.replace(refs.c.target_uuid, '-', '')
    ).outerjoin(
        states,
        sa.and_(
            states.c.object_uuid == refs.c.target_uuid,
            states.c.object_type == ObjectType.INSTANCE))
    stmt = sa.select(
        refs.c.source_uuid, refs.c.created, instances.c.cpus
    ).select_from(joined).where(sa.and_(
        refs.c.relationship == RelationshipType.INSTANCE_LOCATION,
        refs.c.source_object_type == ObjectType.NODE,
        refs.c.target_object_type == ObjectType.INSTANCE,
        sa.or_(
            states.c.state_value.is_(None),
            states.c.state_value != 'deleted'),
        refs.c.created > now - demand_decay_seconds))

    for row in conn.execute(stmt).fetchall():
        try:
            node_uuid = UUID(str(row.source_uuid))
        except ValueError:
            LOG.warning(
                f'Skipping demand row with malformed node uuid '
                f'{row.source_uuid!r}')
            continue
        contribution = _decayed_demand_contribution(
            int(row.cpus), now - float(row.created), demand_per_vcpu,
            demand_decay_seconds)
        demand[node_uuid] = demand.get(node_uuid, 0.0) + contribution
    return demand


def _direct_reconcile_scheduler_capacity(
        demand_per_vcpu: float,
        demand_decay_seconds: int,
        disk_overcommit: float) -> Optional[dict[str, Any]]:
    """Run one full capacity reconcile pass directly against MariaDB.

    One pass, in order (D5): expire stale namespace claims; refresh node
    limit rows from node_metrics; recompute usage from placement ground
    truth; recompute expected_demand; rebuild the cluster_capacity
    singleton. Usage is computed before limits are written because
    limit_disk_gb depends on the recomputed used_disk_gb.

    CPU_OVERCOMMIT_RATIO and RAM_OVERCOMMIT_RATIO come from this
    process's config: they are cluster-wide settings the database daemon
    shares, unlike the demand parameters and ``disk_overcommit`` which
    ride in from the caller.

    Since phase 3 this pass is not the only writer of these tables: the
    placement admission and release transactions update
    cluster_capacity, namespace_claims and scheduler_node_capacity on
    the instance hot path, concurrently with a pass. The reconciler is
    still the authority on every counter it writes, because it
    recomputes each one from ground truth -- the placement rows and the
    instances they point at -- rather than adjusting it incrementally.
    An admission that commits while a pass is running may fall outside
    the snapshot the pass computed from, in which case its increment is
    overwritten here and reinstated by the next pass, which sees its
    placement row. So the single commit at the end bounds a *failed*
    pass -- an error part way through leaves no partial rewrite behind
    -- rather than isolating the pass from those other writers.

    Returns the summary dict the reply is built from (counts, per-node
    rows with previous-vs-new used deltas, the cluster row), or None on
    error.
    """
    engine = _get_engine()
    capacity = _get_scheduler_node_capacity_table()
    claims = _get_namespace_claims_table()
    cluster = _get_cluster_capacity_table()
    metrics = _get_node_metrics_table()
    states = _get_object_states_table()
    nodes = _get_nodes_table()

    now = time.time()

    try:
        with engine.connect() as conn:
            # (1) Expire claims: the D4 crash backstop. Server-side
            # NOW() comparison, matching the cluster_locks idiom.
            claims_expired = int(conn.execute(
                sa.update(claims).where(sa.and_(
                    claims.c.state == 'active',
                    claims.c.expires_at < sa.func.now()
                )).values(state='expired', updated_at=sa.func.now())
            ).rowcount)

            # Snapshot the previous capacity rows for delta reporting,
            # NULL-metrics limit retention and node add/remove counting.
            previous = {}
            for row in conn.execute(sa.select(capacity)).fetchall():
                previous[row.node_uuid] = row

            # The typed capacity columns from node_metrics (phase 1),
            # restricted to hypervisors with fresh metrics.
            #
            # sf-resources publishes metrics from every node whatever its
            # roles, but only a hypervisor can host an instance -- the
            # scheduler drops non-hypervisor candidates before any
            # capacity arithmetic, so capacity rows exist per hypervisor,
            # not per node, and the cluster totals only sum capacity that
            # can actually be scheduled onto.
            #
            # Freshness matters because node_metrics rows are only
            # deleted when the node is, so a node whose resources daemon
            # has died would otherwise keep contributing its last-known
            # limits forever. The node-state filter below catches a node
            # that has gone missing outright; this catches the narrower
            # case of a live node that has stopped publishing. Like the
            # state filter, it is expressed positively -- membership in
            # a fresh set, with absence removing the row -- because a
            # node can also have *no* metrics row at all: sf-resources
            # deletes its own node's rows at daemon startup before the
            # first upsert, so a resources daemon that dies in that
            # window leaves a live, active node with no row, which a
            # stale-set subtraction would retain forever.
            #
            # A NULL is_hypervisor (a metrics row written by a
            # pre-upgrade resources daemon, before the first upsert
            # repopulates the column) is neither a hypervisor nor a
            # confirmed non-hypervisor: it is left out of the refresh
            # below and out of non_hypervisors, so an existing row keeps
            # its limits and no row is created or destroyed on the
            # strength of a missing value.
            fresh_after = now - RECONCILE_METRICS_MAX_AGE_SECONDS
            metrics_rows = {}
            for row in conn.execute(sa.select(
                    metrics.c.node_uuid,
                    metrics.c.cpu_schedulable,
                    metrics.c.memory_max,
                    metrics.c.memory_reserved_mb,
                    metrics.c.disk_free_instances,
                    metrics.c.disk_reservation_gb).where(sa.and_(
                        metrics.c.is_hypervisor.is_(True),
                        metrics.c.timestamp > fresh_after))).fetchall():
                metrics_rows[row.node_uuid] = row

            non_hypervisors = {
                row.node_uuid for row in conn.execute(
                    sa.select(metrics.c.node_uuid).where(
                        metrics.c.is_hypervisor.is_(False))).fetchall()}

            # Derived without the is_hypervisor predicate, so a fresh
            # row whose is_hypervisor is still NULL (mid-upgrade) keeps
            # qualifying and the no-evidence retention below still
            # applies to it.
            fresh_metrics_nodes = {
                row.node_uuid for row in conn.execute(
                    sa.select(metrics.c.node_uuid).where(
                        metrics.c.timestamp > fresh_after)).fetchall()}

            # Node existence and schedulability ground truth. The
            # scheduler builds its candidate set from
            # Nodes([], prefilter='active'), which resolves through
            # get_objects_by_state and so only ever sees nodes that have
            # an object_states row in NODE_ACTIVE_STATES. The query here
            # is expressed the same way round -- IN the active set, with
            # candidates intersected against it -- so that everything
            # outside that set is excluded by default: an errored,
            # missing, stopping, stopped or deleted node, a state added
            # to the state machine later, and a node with no state row
            # at all (stateless zombies are a real condition here, which
            # is why the orphan reconciler exists). None of those is
            # evidence that a node can be scheduled onto. An earlier
            # draft subtracted a NOT IN inactive set instead, and a
            # stateless node appeared in neither set and slipped
            # through.
            known_nodes = {
                row.uuid for row in
                conn.execute(sa.select(nodes.c.uuid)).fetchall()}
            active_nodes = set()
            for row in conn.execute(sa.select(states.c.object_uuid).where(
                    sa.and_(
                        states.c.object_type == ObjectType.NODE,
                        states.c.state_value.in_(
                            sorted(NODE_ACTIVE_STATES))))).fetchall():
                try:
                    active_nodes.add(UUID(str(row.object_uuid)))
                except ValueError:
                    pass

            # (3) Recompute usage from ground truth, and (4) expected
            # demand. Usage comes before the limit writes because
            # limit_disk_gb depends on used_disk_gb.
            usage = _reconcile_fetch_usage(conn)
            demand = _reconcile_fetch_demand(
                conn, now, demand_per_vcpu, demand_decay_seconds)

            # The per-node counters fold the (node, namespace) rows back
            # up by node. There is deliberately no by-namespace fold
            # here: summing these rows across nodes would count an
            # instance with a stale duplicate placement row twice, so
            # the per-claim recompute below does its own aggregation in
            # SQL, de-duplicated by instance uuid.
            usage_by_node: dict[UUID, list[int]] = {}
            for (node_uuid, _namespace), used_row in usage.items():
                totals = usage_by_node.setdefault(node_uuid, [0, 0, 0])
                totals[0] += used_row[0]
                totals[1] += used_row[1]
                totals[2] += used_row[2]

            # (2) Refresh node rows. A node has a capacity row while it
            # is an active hypervisor with fresh metrics and a row in the
            # nodes table; NULL metrics columns keep the previous limits
            # rather than zeroing them. A node that stops qualifying on
            # any of those loses its row -- which is also how rows
            # written before these filters existed get cleaned up on
            # upgrade.
            #
            # Existence in the nodes table gates creation as well as
            # removal. Gating only removal leaves a permanent phantom: a
            # node_metrics row that outlived its node's static and state
            # rows has nothing to mark it inactive, so it reads as a
            # fresh hypervisor, gets a row created, and then appears in
            # both previous and metrics_rows on every later pass, so no
            # removal condition ever fires and its limits sit in the
            # cluster totals forever.
            removals = [
                node_uuid for node_uuid in previous
                if node_uuid not in active_nodes
                or node_uuid in non_hypervisors
                or node_uuid not in fresh_metrics_nodes
                or node_uuid not in known_nodes]
            candidates = (
                (set(previous) | set(metrics_rows))
                & known_nodes & active_nodes) - set(removals)

            nodes_added = 0
            reply_nodes = []
            total_limits = [0, 0, 0]
            capacity_nodes = set()
            for node_uuid in sorted(candidates, key=lambda u: u.hex):
                prev_row = previous.get(node_uuid)
                metrics_row = metrics_rows.get(node_uuid)
                used = usage_by_node.get(node_uuid, [0, 0, 0])

                limit_cpus: Optional[int] = None
                limit_memory_mb: Optional[int] = None
                limit_disk_gb: Optional[int] = None
                if metrics_row is not None:
                    limit_cpus, limit_memory_mb = _derive_cpu_memory_limits(
                        metrics_row.cpu_schedulable,
                        metrics_row.memory_max,
                        metrics_row.memory_reserved_mb,
                        config.CPU_OVERCOMMIT_RATIO,
                        config.RAM_OVERCOMMIT_RATIO)
                    limit_disk_gb = _derive_disk_limit_gb(
                        used[2],
                        metrics_row.disk_free_instances,
                        metrics_row.disk_reservation_gb,
                        disk_overcommit)
                if prev_row is not None:
                    if limit_cpus is None:
                        limit_cpus = prev_row.limit_cpus
                    if limit_memory_mb is None:
                        limit_memory_mb = prev_row.limit_memory_mb
                    if limit_disk_gb is None:
                        limit_disk_gb = prev_row.limit_disk_gb
                if (limit_cpus is None or limit_memory_mb is None or
                        limit_disk_gb is None):
                    # A new node whose metrics row lacks the needed
                    # columns: there is nothing defensible to write yet,
                    # so wait for the next resources-daemon upsert.
                    LOG.info(
                        f'Skipping capacity row for node {node_uuid}: '
                        f'metrics row lacks capacity columns')
                    continue

                expected_demand = demand.get(node_uuid, 0.0)
                values = {
                    'limit_cpus': limit_cpus,
                    'limit_memory_mb': limit_memory_mb,
                    'limit_disk_gb': limit_disk_gb,
                    'used_cpus': used[0],
                    'used_memory_mb': used[1],
                    'used_disk_gb': used[2],
                    'expected_demand': expected_demand,
                    'updated_at': sa.func.now(),
                }
                stmt = sa.dialects.mysql.insert(capacity).values(
                    node_uuid=node_uuid, **values)
                conn.execute(stmt.on_duplicate_key_update(**values))
                if prev_row is None:
                    nodes_added += 1

                total_limits[0] += limit_cpus
                total_limits[1] += limit_memory_mb
                total_limits[2] += limit_disk_gb
                capacity_nodes.add(node_uuid)
                reply_nodes.append({
                    'node_uuid': str(node_uuid),
                    'limit_cpus': limit_cpus,
                    'limit_memory_mb': limit_memory_mb,
                    'limit_disk_gb': limit_disk_gb,
                    'used_cpus': used[0],
                    'used_memory_mb': used[1],
                    'used_disk_gb': used[2],
                    'expected_demand': expected_demand,
                    'delta_used_cpus': used[0] - (
                        prev_row.used_cpus if prev_row is not None else 0),
                    'delta_used_memory_mb': used[1] - (
                        prev_row.used_memory_mb
                        if prev_row is not None else 0),
                    'delta_used_disk_gb': used[2] - (
                        prev_row.used_disk_gb
                        if prev_row is not None else 0),
                })

            nodes_removed = 0
            if removals:
                nodes_removed = int(conn.execute(
                    sa.delete(capacity).where(
                        capacity.c.node_uuid.in_(removals))).rowcount)

            # Read the active claims. Their limits and namespaces feed
            # the cluster rebuild below, which is the only reason this
            # read exists: the usage recompute that follows needs no
            # per-claim data, because it does the whole job in one
            # set-based statement.
            claimed_limits = [0, 0, 0]
            claimed_namespaces = set()
            for row in conn.execute(sa.select(claims).where(
                    claims.c.state == 'active')).fetchall():
                claimed_limits[0] += row.limit_cpus
                claimed_limits[1] += row.limit_memory_mb
                claimed_limits[2] += row.limit_disk_gb
                claimed_namespaces.add(row.namespace)

            # Per-claim usage recompute: one statement rewrites used_*
            # on every active claim, including zeroing a claim whose
            # namespace no longer holds an instance. It aggregates a
            # placement set de-duplicated by instance uuid, so a stale
            # duplicate placement row can not charge one instance to a
            # namespace quota twice -- see the comment block above
            # _RECONCILE_CLAIM_USAGE_SQL, which is also where the two
            # uuid and two enum storage conventions the bound parameters
            # have to satisfy are recorded.
            conn.execute(_RECONCILE_CLAIM_USAGE_SQL,
                         _reconcile_reference_params())

            # (5) Rebuild the cluster_capacity singleton: node limit
            # sums, active claim limit sums, and usage by instances in
            # namespaces without an active claim.
            #
            # The unclaimed fold is restricted to nodes that hold a
            # capacity row after this pass, so the singleton is a closed
            # accounting over the schedulable cluster: an instance
            # stranded on an errored, demoted, stale-metrics or deleted
            # node contributes to neither side, rather than inflating
            # the used side of a total its node contributes nothing to.
            # Without the restriction a drained hypervisor makes the
            # soak dashboards show unclaimed usage exceeding total
            # capacity, which reads as a bug rather than as accounting.
            # Per-claim used_* above is deliberately different: it stays
            # namespace-wide, because a namespace quota covers the
            # namespace's instances wherever they are stranded.
            unclaimed_used = [0, 0, 0]
            for (node_uuid, namespace), used_row in usage.items():
                if namespace in claimed_namespaces:
                    continue
                if node_uuid not in capacity_nodes:
                    continue
                unclaimed_used[0] += used_row[0]
                unclaimed_used[1] += used_row[1]
                unclaimed_used[2] += used_row[2]

            cluster_values = {
                'total_cpus': total_limits[0],
                'total_memory_mb': total_limits[1],
                'total_disk_gb': total_limits[2],
                'claimed_cpus': claimed_limits[0],
                'claimed_memory_mb': claimed_limits[1],
                'claimed_disk_gb': claimed_limits[2],
                'unclaimed_used_cpus': unclaimed_used[0],
                'unclaimed_used_memory_mb': unclaimed_used[1],
                'unclaimed_used_disk_gb': unclaimed_used[2],
                'updated_at': sa.func.now(),
            }
            cluster_stmt = sa.dialects.mysql.insert(cluster).values(
                id=1, **cluster_values)
            conn.execute(
                cluster_stmt.on_duplicate_key_update(**cluster_values))

            conn.commit()

            del cluster_values['updated_at']
            return {
                'success': True,
                'nodes_added': nodes_added,
                'nodes_removed': nodes_removed,
                'claims_expired': claims_expired,
                'nodes': reply_nodes,
                'cluster': cluster_values,
            }
    except (OperationalError, IntegrityError) as e:
        LOG.warning(f'MariaDB reconcile_scheduler_capacity failed: {e}')
        return None


def _grpc_reconcile_scheduler_capacity(
        demand_per_vcpu: float,
        demand_decay_seconds: int,
        disk_overcommit: float) -> Optional[dict[str, Any]]:
    """Run a capacity reconcile pass via the database microservice.

    The only caller is the cluster daemon's elected loop, which pets the
    systemd watchdog itself between maintenance passes, so this uses the
    bounded budget rather than the default GRPC_RETRIES * GRPC_TIMEOUT
    worst case that exceeds WatchdogSec (issue 3586). The server side is
    deliberately one analytical query rather than a point lookup, which
    makes DEADLINE_EXCEEDED on a loaded database realistic rather than
    pathological -- and harmless, because the next pass recomputes every
    counter from ground truth. A skipped pass costs five minutes of gauge
    freshness, not correctness.
    """
    try:
        stub = _get_database_stub()
        request = database_pb2.ReconcileSchedulerCapacityRequest(
            demand_per_vcpu=demand_per_vcpu,
            demand_decay_seconds=demand_decay_seconds,
            disk_overcommit=disk_overcommit)
        reply = _grpc_call(
            stub.ReconcileSchedulerCapacity, request,
            timeout=BOUNDED_QUERY_TIMEOUT, max_slow_failures=1)
        if not reply.success:
            return None
        return {
            'success': True,
            'nodes_added': int(reply.nodes_added),
            'nodes_removed': int(reply.nodes_removed),
            'claims_expired': int(reply.claims_expired),
            'nodes': [
                {
                    'node_uuid': n.node_uuid,
                    'limit_cpus': int(n.limit_cpus),
                    'limit_memory_mb': int(n.limit_memory_mb),
                    'limit_disk_gb': int(n.limit_disk_gb),
                    'used_cpus': int(n.used_cpus),
                    'used_memory_mb': int(n.used_memory_mb),
                    'used_disk_gb': int(n.used_disk_gb),
                    'expected_demand': float(n.expected_demand),
                    'delta_used_cpus': int(n.delta_used_cpus),
                    'delta_used_memory_mb': int(n.delta_used_memory_mb),
                    'delta_used_disk_gb': int(n.delta_used_disk_gb),
                } for n in reply.nodes],
            'cluster': {
                'total_cpus': int(reply.cluster.total_cpus),
                'total_memory_mb': int(reply.cluster.total_memory_mb),
                'total_disk_gb': int(reply.cluster.total_disk_gb),
                'claimed_cpus': int(reply.cluster.claimed_cpus),
                'claimed_memory_mb': int(reply.cluster.claimed_memory_mb),
                'claimed_disk_gb': int(reply.cluster.claimed_disk_gb),
                'unclaimed_used_cpus': int(
                    reply.cluster.unclaimed_used_cpus),
                'unclaimed_used_memory_mb': int(
                    reply.cluster.unclaimed_used_memory_mb),
                'unclaimed_used_disk_gb': int(
                    reply.cluster.unclaimed_used_disk_gb),
            },
        }
    except exceptions.DatabaseUnavailable as e:
        # The bounded budget above makes this the *expected* outcome of a
        # loaded or restarting database tier, not an anomaly, so it must
        # not reach the caller's ignore_exception() path -- that logs at
        # ERROR with a traceback and writes a recorded-exception file
        # every five minutes for a condition this design calls harmless,
        # and cluster CI's log-error checks are the functional gate for
        # this phase. The failure counter and the un-advanced
        # last-success timestamp are the signal operators need.
        LOG.warning(
            f'Scheduler capacity reconcile skipped, database unavailable: {e}')
        return None
    except grpc.RpcError as e:
        LOG.error(f'gRPC ReconcileSchedulerCapacity failed: {e}')
        return None


def reconcile_scheduler_capacity() -> Optional[dict[str, Any]]:
    """Run one scheduler capacity reconcile pass.

    Called from the cluster daemon's elected-leader loop. The demand
    parameters and SCHEDULER_DISK_OVERCOMMIT come from this process's
    config so the database daemon needs no copy of the scheduler
    configuration.

    Returns a summary dict:

        {'success': True,
         'nodes_added': int, 'nodes_removed': int, 'claims_expired': int,
         'nodes': [{'node_uuid': str, 'limit_cpus': int,
                    'limit_memory_mb': int, 'limit_disk_gb': int,
                    'used_cpus': int, 'used_memory_mb': int,
                    'used_disk_gb': int, 'expected_demand': float,
                    'delta_used_cpus': int, 'delta_used_memory_mb': int,
                    'delta_used_disk_gb': int}, ...],
         'cluster': {'total_cpus': int, 'total_memory_mb': int,
                     'total_disk_gb': int, 'claimed_cpus': int,
                     'claimed_memory_mb': int, 'claimed_disk_gb': int,
                     'unclaimed_used_cpus': int,
                     'unclaimed_used_memory_mb': int,
                     'unclaimed_used_disk_gb': int}}

    or None on error.
    """
    if _use_database_service():
        return _grpc_reconcile_scheduler_capacity(
            config.SCHEDULER_DEMAND_PER_VCPU,
            config.SCHEDULER_DEMAND_DECAY_SECONDS,
            config.SCHEDULER_DISK_OVERCOMMIT)
    return _direct_reconcile_scheduler_capacity(
        config.SCHEDULER_DEMAND_PER_VCPU,
        config.SCHEDULER_DEMAND_DECAY_SECONDS,
        config.SCHEDULER_DISK_OVERCOMMIT)


# =============================================================================
# Scheduler Placement Admission (MariaDB)
#
# Scheduler-reservations phase 3: the atomicity primitive the plan exists
# for (D1, D3). AdmitInstancePlacement performs the guarded capacity
# drawdown, the placement attribute write and the placement reference
# rewrite in one transaction, so two concurrent creates racing one
# remaining slot admit exactly once and a stale duplicate placement row
# cannot be produced. ReleaseInstancePlacement is its floored-decrement
# mirror. See
# docs/plans/PLAN-scheduler-reservations-phase-03-primitive.md.
#
# There is deliberately no fallback Python composition of the existing
# single-table RPCs: the whole point is that these are one transaction.
# =============================================================================

# MariaDB errnos on which the entire admission transaction is retried
# (D1). 1213 ER_LOCK_DEADLOCK is the InnoDB deadlock victim, 1205
# ER_LOCK_WAIT_TIMEOUT is the same contention resolved by the timeout
# rather than the detector, and 1020 ER_CHECKREAD is "record has changed
# since last read". All three mean "your transaction lost a race, run it
# again"; anything else is a real error.
#
# _retry_on_deadlock() above is deliberately not reused or widened. It
# guards the cluster-lock paths, where a 1205 means a lease genuinely
# could not be taken within the caller's budget and retrying inside the
# database daemon would eat the caller's acquire timeout. Here the whole
# transaction rolled back and re-running it is both cheap and correct.
#
# 1020 is belt and braces rather than a working part. Both transactions
# open with a guarded UPDATE (see the block comment above
# _probe_admission_rows()), which is the shape phase 0 benchmarked as
# never raising it, and the live concurrency suite confirms it does not
# fire against a server with innodb_snapshot_isolation ON. It stays in
# the set because MDEV-39263 reports the error firing "most of the time,
# but not every time", so it is not something to rely on the absence of.
_TRANSIENT_TRANSACTION_ERRNOS = frozenset((1213, 1205, 1020))
_TRANSACTION_MAX_ATTEMPTS = 4
_TRANSACTION_BASE_DELAY = 0.005

# The three allocation dimensions, in the order they appear in denial
# detail. 'demand' (D13) is reported alongside them when the node's
# demand clause is what refused.
CAPACITY_DIMENSIONS = ('cpus', 'memory_mb', 'disk_gb')

# Is a namespace claim's ceiling enforced, or merely recorded? D16 makes
# claim ceilings advisory for one release: an admission that pushes a
# claim's used_* past its limit_* is admitted and reported
# (claim_over_limit plus the offending dimensions) rather than refused.
# Phase 5 flips this to True together with the HTTP 403 refusal path.
#
# Deliberately a module constant and not a config option (D4): a `hard`
# setting whose refusal path does not exist yet is a trap for the
# operator who sets it. It is *not* folded into the node and cluster
# fail-open either -- see the three guard flags in
# _direct_admit_instance_placement().
CLAIM_ENFORCEMENT_HARD = False


class CapacityDimensionDetailDict(TypedDict):
    """One dimension's numbers at the moment a guard refused."""

    dimension: str
    limit: float
    used: float
    requested: float
    exceeded: bool


class AdmitPlacementResult(TypedDict):
    """The reply _direct_admit_instance_placement builds."""

    success: bool
    error: str
    admitted: bool
    unguarded: bool
    clamped: bool
    failing_stage: str
    dimensions: list[CapacityDimensionDetailDict]
    node_used_cpus: int
    node_used_memory_mb: int
    node_used_disk_gb: int
    node_expected_demand: float
    # Advisory claim accounting (D5/D16), kept apart from failing_stage
    # and dimensions because those two mean "this placement was refused"
    # and an over-claim placement is admitted.
    claim_over_limit: bool
    claim_dimensions: list[CapacityDimensionDetailDict]


class ReleasePlacementResult(TypedDict):
    """The reply _direct_release_instance_placement builds."""

    success: bool
    error: str
    released: bool
    clamped: bool


class SchedulerNodeCapacityRow(TypedDict):
    """One scheduler_node_capacity row, as readers of the counters see it."""

    node_uuid: str
    limit_cpus: int
    limit_memory_mb: int
    limit_disk_gb: int
    used_cpus: int
    used_memory_mb: int
    used_disk_gb: int
    expected_demand: float


class _AdmissionDenied(Exception):
    """A guarded UPDATE matched no row, so the transaction must abort.

    Carries the stage that refused ('cluster', 'claim' or 'node') so the
    caller's walk to the next candidate and the D9 diagnostics both know
    why. Raised inside the ``engine.begin()`` block, which rolls the
    transaction back on the way out; the per-dimension detail is then
    assembled from a fresh read.
    """

    def __init__(self, stage: str) -> None:
        super().__init__(stage)
        self.stage = stage


class _PlacementRowMissing(Exception):
    """The instance has no instance_attributes row to place.

    Callers create an instance before placing it, so this is a bug in
    the caller rather than a case to paper over by inserting a row: an
    attributes row conjured here would be missing every other attribute
    the create path sets.
    """


def _is_retryable_transaction_error(exc: OperationalError) -> bool:
    """Is this an OperationalError worth re-running the transaction for?

    SQLAlchemy wraps the underlying DB-API exception in ``exc.orig``; the
    mysqldb driver puts the MariaDB errno in ``orig.args[0]``.
    """
    orig = getattr(exc, 'orig', None)
    if orig is None:
        return False
    args: tuple[Any, ...] = getattr(orig, 'args', ())
    if len(args) == 0:
        return False
    return args[0] in _TRANSIENT_TRANSACTION_ERRNOS


def _retry_transaction(fn: Callable[[], _T], op_name: str) -> _T:
    """Run a whole transaction, retrying it on transient contention.

    Bounded attempts with jittered exponential backoff, so a burst of
    concurrent admissions against one node does not synchronise on the
    next round. Re-raises the last error if every attempt fails, so the
    caller's OperationalError handling still runs.
    """
    last_error: Optional[OperationalError] = None
    for attempt in range(_TRANSACTION_MAX_ATTEMPTS):
        try:
            return fn()
        except OperationalError as e:
            if not _is_retryable_transaction_error(e):
                raise
            last_error = e
            if attempt < _TRANSACTION_MAX_ATTEMPTS - 1:
                delay = (_TRANSACTION_BASE_DELAY * (2 ** attempt)
                         * random.uniform(0.5, 1.5))
                time.sleep(delay)
    LOG.warning(
        f'{op_name}: {_TRANSACTION_MAX_ATTEMPTS} consecutive transient '
        f'transaction failures, giving up: {last_error}')
    assert last_error is not None
    raise last_error


def _capacity_dimension(
        dimension: str, limit: float, used: float, requested: float, *,
        charged: bool = True) -> CapacityDimensionDetailDict:
    """Build one denial-detail entry, recomputing the guard comparison.

    ``exceeded`` is the same test the SQL guard made, evaluated here
    against the values read back after the rollback. It names the
    dimensions that actually failed rather than reporting every
    dimension of the failing stage as suspect.

    ``charged`` says whether this request is part of the comparison, and
    exists for exactly one caller: the D13 demand dimension. It is
    keyword-only because it cannot be got wrong quietly -- the value
    decides which dimensions report ``exceeded``, and a wrong one there
    changes whether the P9 waiver fires (below), so it must never be
    supplied by landing in the right argument position by accident. The three
    allocation dimensions are guarded as ``used + requested <= limit``,
    but since phase 4a the demand clause compares only the node's
    existing state (``cpu_load_1 + expected_demand <= target_load x
    cpu_schedulable``) and does not charge the incoming placement --
    that is what makes it satisfiable at every node size. Reporting
    demand as ``used + requested > limit`` anyway would mark a denial
    the clause did not make, and because
    ``CapacityAdmissionDenied.demand_only`` is derived from the
    ``exceeded`` set, that would in turn change whether the P9 waiver
    fires. ``requested`` is still reported, because an operator reading
    the event wants to know what the placement would have added.
    """
    return {
        'dimension': dimension,
        'limit': float(limit),
        'used': float(used),
        'requested': float(requested),
        'exceeded': bool(
            used + requested > limit if charged else used > limit),
    }


def _empty_admit_result() -> AdmitPlacementResult:
    """A successful, not-yet-decided admission reply."""
    return {
        'success': True,
        'error': '',
        'admitted': False,
        'unguarded': False,
        'clamped': False,
        'failing_stage': '',
        'dimensions': [],
        'node_used_cpus': 0,
        'node_used_memory_mb': 0,
        'node_used_disk_gb': 0,
        'node_expected_demand': 0.0,
        'claim_over_limit': False,
        'claim_dimensions': [],
    }


def _demand_guard_clause(
        node_key: UUID,
        target_load: float) -> Optional[sa.ColumnElement[bool]]:
    """The D13 feedforward clause of the node guard, or None to skip it.

    ``measured cpu_load_1 + expected_demand <= target_load x
    cpu_schedulable``, with both measured inputs read from the typed
    node_metrics columns inside the admission transaction (P2). The
    scheduler's own measurement-denominated filters remain cheap
    pre-filters in find_candidates(); this is the clause that makes the
    decision atomic with the drawdown.

    The placement's own charge is deliberately not a parameter here,
    though the same UPDATE still adds it to ``expected_demand`` so it is
    charged for the next decision. The clause asks whether the node is
    already at or above its target load, not whether it would be after
    this placement (phase 4a decision E2). Both sides are then node
    state in units of runnable threads, where the old form compared a
    per-request charge against a per-node budget: at the original seed
    constants that made a 1-vCPU instance need 3.34 schedulable threads
    before any node could admit it at zero load, so nodes below four
    threads admitted nothing, ever (issue #3813). Check-then-charge is
    safe here because this comparison and that increment are the same
    guarded UPDATE in the same transaction, so two admissions against
    one node serialise and the second sees the first's charge.

    This is a spreader and never a capacity bound: the three allocation
    dimensions in the same WHERE clause are what stop a node accepting
    work it has no room for.

    NULL metrics inputs pass rather than deny. A node whose resources
    daemon has not yet published typed columns (mid-upgrade) has no
    schedulable-thread count to compute a bound from, and refusing every
    placement on it would be a worse failure than one reconcile period
    of yesterday's behaviour -- the same reasoning as P7's fail-open for
    a missing capacity row. A NULL cpu_load_1 with a known thread count
    is different: there the bound is computable, so the load term simply
    coalesces to zero.

    A non-positive ``target_load`` disables the clause entirely. An
    unset proto3 double reads as 0.0, so a caller mid-upgrade that does
    not send the field must not silently have every placement denied.
    """
    if target_load <= 0:
        return None

    capacity = _get_scheduler_node_capacity_table()
    metrics = _get_node_metrics_table()
    load = sa.select(metrics.c.cpu_load_1).where(
        metrics.c.node_uuid == node_key).scalar_subquery()
    schedulable = sa.select(metrics.c.cpu_schedulable).where(
        metrics.c.node_uuid == node_key).scalar_subquery()
    return sa.or_(
        schedulable.is_(None),
        sa.func.coalesce(load, 0.0) + capacity.c.expected_demand
        <= target_load * schedulable)


def _floored_node_decrement(
        conn: sa.Connection, node_key: UUID, cpus: int, memory_mb: int,
        disk_gb: int) -> tuple[bool, bool]:
    """Decrement a node's used_* counters, floored at zero (P6).

    First the guarded form (``used >= x`` per dimension), which is the
    ordinary case and leaves the counters exactly right. On a miss --
    the counters are already lower than this release believes, because a
    reconcile pass has recomputed them from ground truth in between --
    the unguarded ``GREATEST(0, used - x)`` form runs instead, so a
    release racing the reconciler can never drive a counter negative.

    ``expected_demand`` is deliberately not decremented: the D13 term
    decays with instance age and the reconciler recomputes it every
    pass, so subtracting a placement's original contribution here would
    over-credit a node whose contribution had already decayed.

    Returns ``(touched, clamped)``. ``touched`` is False when there is no
    capacity row for the node at all, which is P7's fail-open case
    rather than a clamp.
    """
    capacity = _get_scheduler_node_capacity_table()

    guarded = sa.update(capacity).where(sa.and_(
        capacity.c.node_uuid == node_key,
        capacity.c.used_cpus >= cpus,
        capacity.c.used_memory_mb >= memory_mb,
        capacity.c.used_disk_gb >= disk_gb,
    )).values(
        used_cpus=capacity.c.used_cpus - cpus,
        used_memory_mb=capacity.c.used_memory_mb - memory_mb,
        used_disk_gb=capacity.c.used_disk_gb - disk_gb,
        updated_at=sa.func.now())
    if conn.execute(guarded).rowcount > 0:
        return True, False

    clamp = sa.update(capacity).where(
        capacity.c.node_uuid == node_key
    ).values(
        used_cpus=sa.func.greatest(0, capacity.c.used_cpus - cpus),
        used_memory_mb=sa.func.greatest(
            0, capacity.c.used_memory_mb - memory_mb),
        used_disk_gb=sa.func.greatest(0, capacity.c.used_disk_gb - disk_gb),
        updated_at=sa.func.now())
    if conn.execute(clamp).rowcount > 0:
        LOG.warning(
            f'Clamped capacity decrement on node {node_key}: counters were '
            f'below the released allocation ({cpus} cpus, {memory_mb} MB, '
            f'{disk_gb} GB)')
        return True, True
    return False, False


def _floored_namespace_decrement(
        conn: sa.Connection, claim_uuid: Optional[UUID], cpus: int,
        memory_mb: int, disk_gb: int) -> bool:
    """Floored decrement of the claim row, or the cluster unclaimed sums.

    The namespace-side mirror of _floored_node_decrement: guarded first,
    ``GREATEST(0, ...)`` on a miss. Returns True if it had to clamp.
    """
    if claim_uuid is not None:
        table: sa.Table = _get_namespace_claims_table()
        key = table.c.uuid == claim_uuid
        columns = ('used_cpus', 'used_memory_mb', 'used_disk_gb')
    else:
        table = _get_cluster_capacity_table()
        key = table.c.id == 1
        columns = ('unclaimed_used_cpus', 'unclaimed_used_memory_mb',
                   'unclaimed_used_disk_gb')

    amounts = (cpus, memory_mb, disk_gb)
    guarded = sa.update(table).where(sa.and_(key, *[
        table.c[column] >= amount
        for column, amount in zip(columns, amounts)
    ])).values(updated_at=sa.func.now(), **{
        column: table.c[column] - amount
        for column, amount in zip(columns, amounts)
    })
    if conn.execute(guarded).rowcount > 0:
        return False

    clamp = sa.update(table).where(key).values(
        updated_at=sa.func.now(), **{
            column: sa.func.greatest(0, table.c[column] - amount)
            for column, amount in zip(columns, amounts)
        })
    if conn.execute(clamp).rowcount > 0:
        LOG.warning(
            f'Clamped capacity decrement on {table.name}: counters were '
            f'below the released allocation ({cpus} cpus, {memory_mb} MB, '
            f'{disk_gb} GB)')
        return True
    # No row at all: nothing was ever charged here, so nothing to clamp.
    return False


def _active_claim_for_namespace(
        conn: sa.Connection, namespace: str) -> Optional[sa.Row[Any]]:
    """The namespace's active, unexpired claim row, or None.

    This is a plain non-locking read, so it does not participate in D1's
    canonical write order (cluster_capacity, then namespace_claims, then
    scheduler_node_capacity) -- only the guarded UPDATEs take row locks
    and those still run in order. Ordered by uuid so a namespace that
    somehow holds two claims resolves the same way on every node.

    It must **not** be run inside an admission or release transaction:
    a plain SELECT there establishes the transaction's read view and
    re-introduces ER_CHECKREAD under ``innodb_snapshot_isolation``. See
    the block comment above _probe_admission_rows(). The one caller that
    runs it on its own connection outside any write transaction --
    _admission_denial_dimensions() -- is fine.

    Returns None for a namespace with no claim, which is most of them:
    claims are opt in, and a namespace without one is accounted against
    the cluster singleton's unclaimed sums instead.
    """
    claims = _get_namespace_claims_table()
    return conn.execute(sa.select(claims).where(sa.and_(
        claims.c.namespace == namespace,
        claims.c.state == 'active',
        claims.c.expires_at > sa.func.now(),
    )).order_by(claims.c.uuid).limit(1)).first()


def _instance_location_nodes(
        conn: sa.Connection, instance_uuid: str) -> list[UUID]:
    """The nodes holding an instance_location reference for an instance.

    object_references stores the dashed uuid form in both endpoint
    columns while scheduler_node_capacity keys on sa.Uuid (undashed
    CHAR(32) on MariaDB), so the source uuids are parsed here rather
    than compared across the two forms (CLAUDE.md pitfall 6).
    """
    refs = _get_object_references_table()
    rows = conn.execute(sa.select(refs.c.source_uuid).where(sa.and_(
        refs.c.relationship == str(RelationshipType.INSTANCE_LOCATION),
        refs.c.target_object_type == str(ObjectType.INSTANCE),
        refs.c.target_uuid == instance_uuid,
    ))).fetchall()

    nodes = []
    for row in rows:
        try:
            nodes.append(UUID(str(row.source_uuid)))
        except ValueError:
            LOG.warning(
                f'Skipping instance_location row for {instance_uuid} with '
                f'malformed node uuid {row.source_uuid!r}')
    return nodes


# ---------------------------------------------------------------------------
# THE FIRST STATEMENT INSIDE AN ADMISSION OR RELEASE TRANSACTION MUST BE A
# GUARDED (OR FLOORED) UPDATE. A plain SELECT before it re-introduces
# ER_CHECKREAD under innodb_snapshot_isolation.
#
# innodb_snapshot_isolation defaults ON from MariaDB 11.6.2, which is what
# Debian 13, Ubuntu 24.04 and every recent container tag ship. Under it a
# REPEATABLE READ transaction whose read view was established by a plain
# SELECT does not block and re-evaluate a later UPDATE whose target row has
# moved since -- it aborts the whole transaction with ER_CHECKREAD (1020),
# "Record has changed since last read". When the guarded UPDATE is instead
# the transaction's first statement, the read view is established by the DML
# itself, there is no stale-snapshot window, and a contending writer blocks
# on the row lock and then re-evaluates the WHERE, which is the behaviour
# the whole guarded-UPDATE design depends on.
#
# This is not a hypothesis. Phase 0's step 2 benchmark (see
# docs/plans/PLAN-scheduler-reservations-phase-00-findings.md, "Step 2
# benchmark results") ran 96 cells across both regimes and recorded
# ER_CHECKREAD never firing for the guarded-UPDATE idioms, explicitly
# because the guarded UPDATE was the transaction's first statement, with
# the warning that "the risk returns if a plain SELECT precedes the guarded
# UPDATE inside the same RR transaction". Phase 3's step 6 validation then
# demonstrated exactly that: with the branch and presence probes opening
# the transaction, 46 of a 50-way admission burst exhausted the retry
# budget on 1020 and surfaced as HTTP 500s on instance create.
#
# So the probes run here, on their own connection, before the transaction
# opens. Reads that happen *after* our own writes inside the transaction
# are fine -- those rows are already locked by our UPDATEs -- which is why
# the post-admit counter SELECT may stay where it is. Subqueries carried
# inside a guarded UPDATE (the D13 demand clause against node_metrics) are
# likewise fine: they are part of the DML that establishes the read view.
# ---------------------------------------------------------------------------

class _AdmissionProbe(NamedTuple):
    """What an admission must know before it opens its transaction."""

    claim_uuid: Optional[UUID]
    node_present: bool
    cluster_present: bool


def _probe_admission_rows(namespace: str, node_key: UUID) -> _AdmissionProbe:
    """Read an admission's branch select and presence probes (P4, P7).

    Runs on its own connection, outside the write transaction, for the
    reason in the block comment above. Re-run on every retry attempt, so
    a transaction that lost a race re-reads the world rather than
    re-deciding on the losing attempt's view.

    The reads are time-of-check-to-time-of-use racy by construction, and
    deliberately so. Each of the three has a bounded, acceptable
    resolution:

    * The claim branch. A claim created or expired between the probe and
      the transaction sends this one admission down the other branch.
      Both branches are namespace-denominated ledgers the reconciler
      recomputes from ground truth every pass, so the worst case is one
      instance charged to the cluster's unclaimed sums instead of the
      claim (or the reverse) for up to one reconcile period.
    * The node-row presence probe. Present-then-deleted makes the node
      guard match no row, which reads as a denial: the caller walks to
      its next candidate, and a node whose capacity row just vanished is
      not a node this placement wanted anyway. Absent-then-created
      admits unguarded and says so in the reply, which is exactly what
      P7 already does for a node the reconciler has not sized.
    * The cluster singleton probe, identically: a spurious
      single-candidate denial, or one unguarded admission the reconciler
      trues up within a pass.

    None of the three can over-admit past a guard that was actually
    evaluated, and none can leave a counter the reconciler will not
    repair. That is the trade the invariant is worth.
    """
    engine = _get_engine()
    capacity = _get_scheduler_node_capacity_table()
    cluster = _get_cluster_capacity_table()

    with engine.connect() as conn:
        claim = _active_claim_for_namespace(conn, namespace)
        node_present = conn.execute(sa.select(capacity.c.node_uuid).where(
            capacity.c.node_uuid == node_key)).first() is not None
        cluster_present = conn.execute(sa.select(cluster.c.id).where(
            cluster.c.id == 1)).first() is not None

    return _AdmissionProbe(
        claim_uuid=claim.uuid if claim is not None else None,
        node_present=node_present, cluster_present=cluster_present)


class _ReleaseProbe(NamedTuple):
    """What a release must know before it opens its transaction."""

    nodes: list[UUID]
    claim_uuid: Optional[UUID]


def _probe_release_rows(
        namespace: str, instance_uuid: str,
        named_node: Optional[UUID]) -> _ReleaseProbe:
    """Read a release's held nodes and claim branch, outside the transaction.

    Same invariant and the same reasoning as _probe_admission_rows(): a
    release opens with a floored decrement, so its reference lookup and
    branch select cannot run inside the transaction.

    **The instance_location rows are the sole authority for what is
    charged, whether or not the caller names a node.** Since phase 3 the
    placement attribute and the reference rows are written by one
    transaction, so a node with no reference row for this instance is a
    node holding nothing on its behalf. ``named_node`` is therefore a
    *filter* over the located rows, never an override: named and located
    releases that node's row; named and not located releases nothing at
    all, returning ``released=False`` with no counter touched.

    That distinction is what makes a repeat release harmless for a
    *named-node* caller too. ``Instance._delete_globally()`` names the
    node from the ``placement`` attribute, which is never cleared (P8),
    and the delete path's re-entrancy guard only catches state
    ``deleted`` -- an instance that ended in ``error`` reaches the
    release on every delete attempt. Taking the named node on trust
    decremented the node and namespace counters again each time (the
    floors cannot catch it: other instances' usage keeps the counters
    above the amount being released), silently handing that capacity out
    twice until the next reconcile pass.

    The claim branch races exactly as it does for an admission. The
    reference lookup was already racy before it moved: it was a plain
    non-locking read, so two concurrent releases of the same instance
    both saw the rows and both decremented, and the floored decrements
    plus the next reconcile pass are what has always made that safe.
    Moving it out widens that window by one round trip and changes
    nothing else; in production the instance's attribute lock serialises
    the callers anyway.
    """
    engine = _get_engine()
    with engine.connect() as conn:
        nodes = _instance_location_nodes(conn, instance_uuid)
        if named_node is not None:
            nodes = [n for n in nodes if n == named_node]
        if not nodes:
            # Nothing is held, so there is no transaction to open and no
            # branch to select.
            return _ReleaseProbe(nodes=[], claim_uuid=None)
        claim = _active_claim_for_namespace(conn, namespace)

    return _ReleaseProbe(
        nodes=nodes, claim_uuid=claim.uuid if claim is not None else None)


def _delete_instance_location_rows(
        conn: sa.Connection, instance_uuid: str,
        source_nodes: Optional[list[UUID]] = None) -> int:
    """Delete instance_location rows targeting an instance.

    Called without ``source_nodes`` by the admission transaction, this
    deletes every source node's row, not just the one being moved off.
    That is what makes a duplicate placement row unproducible: the
    reconciler's usage query charges an instance to every node holding a
    reference for it (see the comment block above _RECONCILE_USAGE_SQL),
    so a survivor of the old best-effort per-node removal
    double-charged the ledger.

    A release instead passes the nodes its probe located (and its
    caller's node filter selected), so the rows deleted are exactly the
    nodes credited back -- deleting a row without its decrement would
    strand that node's charge until the next reconcile pass, in the
    direction that refuses work.
    """
    refs = _get_object_references_table()
    clauses = [
        refs.c.relationship == str(RelationshipType.INSTANCE_LOCATION),
        refs.c.target_object_type == str(ObjectType.INSTANCE),
        refs.c.target_uuid == instance_uuid,
    ]
    if source_nodes is not None:
        # object_references stores the dashed uuid form (CLAUDE.md
        # pitfall 6), which is what str() of a UUID produces.
        clauses.append(refs.c.source_uuid.in_(
            [str(n) for n in source_nodes]))
    return int(conn.execute(
        sa.delete(refs).where(sa.and_(*clauses))).rowcount)


def _admission_denial_dimensions(
        stage: str, namespace: str, node_key: UUID, cpus: int,
        memory_mb: int, disk_gb: int, demand_add: float,
        target_load: float) -> list[CapacityDimensionDetailDict]:
    """Per-dimension detail for a denial, read fresh after the rollback.

    MariaDB has no way to report which of an UPDATE's WHERE clauses was
    the one that failed, and the transaction that could have told us has
    been rolled back, so the numbers come from a follow-up read. They can
    differ slightly from the values the guard saw (another admission may
    have committed in between), which is why ``exceeded`` is recomputed
    from what was read rather than asserted: the reply says what is true
    now, at the depth the scheduler's Python rejection reasons have
    always carried.
    """
    engine = _get_engine()
    dimensions: list[CapacityDimensionDetailDict] = []
    requested = {'cpus': cpus, 'memory_mb': memory_mb, 'disk_gb': disk_gb}

    try:
        with engine.connect() as conn:
            if stage == 'claim':
                claim = _active_claim_for_namespace(conn, namespace)
                if claim is not None:
                    for dimension in CAPACITY_DIMENSIONS:
                        dimensions.append(_capacity_dimension(
                            dimension,
                            getattr(claim, f'limit_{dimension}'),
                            getattr(claim, f'used_{dimension}'),
                            requested[dimension]))

            elif stage == 'cluster':
                cluster = _get_cluster_capacity_table()
                row = conn.execute(sa.select(cluster).where(
                    cluster.c.id == 1)).first()
                if row is not None:
                    for dimension in CAPACITY_DIMENSIONS:
                        # D14's unclaimed guard is
                        # unclaimed_used + x <= total - claimed, so the
                        # effective limit is what active claims have not
                        # already spoken for.
                        dimensions.append(_capacity_dimension(
                            dimension,
                            (getattr(row, f'total_{dimension}')
                             - getattr(row, f'claimed_{dimension}')),
                            getattr(row, f'unclaimed_used_{dimension}'),
                            requested[dimension]))

            elif stage == 'node':
                capacity = _get_scheduler_node_capacity_table()
                row = conn.execute(sa.select(capacity).where(
                    capacity.c.node_uuid == node_key)).first()
                if row is not None:
                    for dimension in CAPACITY_DIMENSIONS:
                        dimensions.append(_capacity_dimension(
                            dimension,
                            getattr(row, f'limit_{dimension}'),
                            getattr(row, f'used_{dimension}'),
                            requested[dimension]))

                    # The D13 demand clause is the other way the node
                    # guard can refuse, and a denial with no exceeded
                    # allocation dimension is exactly the case an
                    # operator needs told about. charged=False because
                    # the clause does not charge demand_add -- see
                    # _capacity_dimension() and _demand_guard_clause().
                    metrics = _get_node_metrics_table()
                    measured = conn.execute(sa.select(
                        metrics.c.cpu_load_1, metrics.c.cpu_schedulable
                    ).where(metrics.c.node_uuid == node_key)).first()
                    if (target_load > 0 and measured is not None
                            and measured.cpu_schedulable is not None):
                        dimensions.append(_capacity_dimension(
                            'demand',
                            target_load * measured.cpu_schedulable,
                            ((measured.cpu_load_1 or 0.0)
                             + row.expected_demand),
                            demand_add, charged=False))
    except OperationalError as e:
        # The detail is diagnostic, not load bearing: the denial itself
        # is already decided and the caller walks to the next candidate
        # either way.
        LOG.warning(f'Could not read denial detail for stage {stage}: {e}')

    return dimensions


def _direct_admit_instance_placement(
        instance_uuid: str, namespace: str, node_uuid: str,
        old_node_uuid: str, cpus: int, memory_mb: int, disk_gb: int,
        demand_add: float, target_load: float, enforce: bool,
        placement_json: str) -> AdmitPlacementResult:
    """Draw down capacity and write a placement, atomically (D1, D3).

    One transaction, statements in D1's canonical order --
    ``cluster_capacity``, then ``namespace_claims``, then
    ``scheduler_node_capacity`` -- retried as a whole on transient
    contention. The order matters because it is the order every writer
    of these tables uses, which is what keeps concurrent admissions from
    deadlocking against each other rather than merely recovering from it.

    The steps are:

    1. Branch select (P4) and presence probes (P7), **outside** the
       transaction: a namespace with an active, unexpired claim draws
       the claim down; every other namespace draws down the cluster
       singleton's unclaimed guard per D14. These are plain reads and
       must not run inside the transaction -- see the block comment
       above _probe_admission_rows() for why, and for what the resulting
       time-of-check-to-time-of-use races resolve as.
    2. The cluster or claim guarded UPDATE, which is therefore the first
       statement the transaction issues.
    3. The target node's guarded UPDATE, including the D13 demand clause.
    4. On a move, the old node's floored decrement (P6). A move never
       changes namespace, so there is no cluster-row wash to do.
    5. The placement attribute write, masked to that one column.
    6. The placement reference rewrite: delete every instance_location
       row for the instance, then insert the new one.
    7. Read-back of the rows this transaction wrote: the target node's
       counters, and (when a claim was charged) the claim's advisory
       over-limit detail. Both are reads *after* our own writes, which
       the ER_CHECKREAD invariant permits.

    A guarded UPDATE matching no row aborts the transaction and returns
    ``admitted=False`` with the failing stage and per-dimension detail.
    ``enforce=False`` (P5) keeps every counter update but reduces each
    WHERE to its key equality, for the ground-truth writers that record
    where a libvirt domain already is -- a guard cannot refuse reality.
    A node with no capacity row admits unguarded and says so (P7).

    The three guards are flagged independently (D6). The claim guard is
    off this release because D16 makes claim ceilings advisory for one
    release (CLAIM_ENFORCEMENT_HARD), so an admission which pushes a
    claim past its limits is admitted and *reported*: step 7 re-reads
    the claim row it just wrote and returns ``claim_over_limit`` with
    the offending dimensions in ``claim_dimensions``. That is a
    separate field from ``dimensions``, which means "why this placement
    was refused" and must keep meaning only that.

    Rowcount semantics: SQLAlchemy's mysqldb dialect sets the
    ``CLIENT_FOUND_ROWS`` flag, so ``rowcount`` is the number of rows
    *matched*, not changed. That is load bearing here -- a guarded UPDATE
    whose SET happens to be a no-op (a zero-sized dimension, or a
    re-placement writing the identical placement JSON within the same
    second) must read as "the guard passed", not as a denial. The live
    test suite asserts it against a real server.

    Emits no events: the caller emits them from the reply fields, so
    sf-database never has to know an instance's event history.
    """
    engine = _get_engine()
    capacity = _get_scheduler_node_capacity_table()
    claims = _get_namespace_claims_table()
    cluster = _get_cluster_capacity_table()
    attributes = _get_instance_attributes_table()
    refs = _get_object_references_table()

    result = _empty_admit_result()

    try:
        instance_key = UUID(instance_uuid)
        node_key = UUID(node_uuid)
        old_node_key = UUID(old_node_uuid) if old_node_uuid else None
    except ValueError as e:
        LOG.warning(f'admit_instance_placement given a malformed uuid: {e}')
        result['success'] = False
        result['error'] = f'malformed uuid: {e}'
        return result

    if not placement_json:
        result['success'] = False
        result['error'] = 'placement_json is required'
        return result
    try:
        json.loads(placement_json)
    except ValueError as e:
        # The column is JSON typed, so garbage here would surface as an
        # opaque MariaDB error deep inside the transaction.
        result['success'] = False
        result['error'] = f'placement_json is not valid JSON: {e}'
        return result

    if old_node_key == node_key:
        # Re-placing onto the same node is not a move: the counters
        # already hold this instance's allocation for this node and
        # decrementing then re-incrementing them is a no-op with a
        # spurious clamp risk in the middle.
        old_node_key = None

    now = time.time()

    def _admit() -> AdmitPlacementResult:
        outcome = _empty_admit_result()

        # (1) The branch select and the two presence probes, deliberately
        # on their own connection *outside* the transaction below. See the
        # block comment above _probe_admission_rows(): the first statement
        # inside the transaction must be a guarded UPDATE or every
        # admission that loses a race dies of ER_CHECKREAD instead of
        # blocking and re-evaluating its guard.
        probe = _probe_admission_rows(namespace, node_key)
        claim_uuid = probe.claim_uuid
        node_present = probe.node_present

        if not node_present:
            # P7: mid-upgrade, a node whose metrics row predates phase 1
            # has no capacity row, and the cluster totals do not include
            # its limits either -- so guarding the cluster row against a
            # total this node contributes nothing to would deny
            # placements for a reason that is not true. Fail open on
            # every guard, loudly, and let the reconciler create the row
            # on its next pass.
            outcome['unguarded'] = True

        # Three guards, three flags (D6). The node and cluster guards
        # share P7's fail-open above, because it is a statement about
        # *this node's* limits being absent from the totals they test.
        # The claim guard does not: a claim's limits are
        # namespace-denominated and node-independent, so a missing node
        # capacity row says nothing about whether the namespace has
        # exceeded what it claimed, and dropping the claim guard for
        # that reason would be dropping it for a reason that is not
        # true. What does drop it, this release only, is D16's advisory
        # period -- see CLAIM_ENFORCEMENT_HARD.
        node_guarded = enforce and node_present
        cluster_guarded = enforce and node_present
        claim_guarded = enforce and CLAIM_ENFORCEMENT_HARD

        # Set by the claim branch below, and the only thing that makes
        # the advisory read-back run: a move and an unclaimed namespace
        # both leave the claim row untouched, so there is nothing there
        # this admission could have pushed over a limit.
        claim_charged = False

        with engine.begin() as conn:
            # INVARIANT: the first statement executed on this connection
            # must be a guarded (or, for a move, floored) UPDATE. A plain
            # SELECT here establishes the transaction's read view early
            # and makes every later guarded UPDATE against a contended
            # row abort with ER_CHECKREAD (1020) under
            # innodb_snapshot_isolation, which is ON by default from
            # MariaDB 11.6.2. Phase 0's step 2 benchmark predicted this
            # and phase 3's step 6 validation reproduced it (46 of 50
            # concurrent admissions exhausting the retry budget). Reads
            # after our own writes are fine -- we hold those row locks.

            # (2) The cluster or claim guard, which a move skips
            # entirely rather than washing an increment against a
            # decrement. Both the cluster singleton's unclaimed sums and
            # a claim's used_* are namespace-denominated and
            # node-independent, and a placement move never changes
            # namespace, so a move consumes no new capacity on this side
            # -- the instance's allocation has been counted here since
            # its first placement. Incrementing again (with nothing to
            # decrement, because the old node's row is on the other side
            # of the ledger) inflates the namespace by one instance per
            # move until the next reconcile pass. A move is likewise not
            # refusable at this stage: there is nothing new to refuse.
            if old_node_key is not None:
                pass
            elif claim_uuid is not None:
                claim_charged = True
                where = [claims.c.uuid == claim_uuid]
                if claim_guarded:
                    where += [
                        claims.c.used_cpus + cpus <= claims.c.limit_cpus,
                        (claims.c.used_memory_mb + memory_mb
                         <= claims.c.limit_memory_mb),
                        (claims.c.used_disk_gb + disk_gb
                         <= claims.c.limit_disk_gb),
                    ]
                if conn.execute(sa.update(claims).where(
                        sa.and_(*where)).values(
                            used_cpus=claims.c.used_cpus + cpus,
                            used_memory_mb=(claims.c.used_memory_mb
                                            + memory_mb),
                            used_disk_gb=claims.c.used_disk_gb + disk_gb,
                            updated_at=sa.func.now())).rowcount == 0:
                    raise _AdmissionDenied('claim')
            elif probe.cluster_present:
                where = [cluster.c.id == 1]
                if cluster_guarded:
                    # D14's best-effort unclaimed guard: what active
                    # claims have not spoken for is what an unclaimed
                    # namespace may use.
                    where += [
                        (cluster.c.unclaimed_used_cpus + cpus
                         <= cluster.c.total_cpus - cluster.c.claimed_cpus),
                        (cluster.c.unclaimed_used_memory_mb + memory_mb
                         <= (cluster.c.total_memory_mb
                             - cluster.c.claimed_memory_mb)),
                        (cluster.c.unclaimed_used_disk_gb + disk_gb
                         <= (cluster.c.total_disk_gb
                             - cluster.c.claimed_disk_gb)),
                    ]
                if conn.execute(sa.update(cluster).where(
                        sa.and_(*where)).values(
                            unclaimed_used_cpus=(
                                cluster.c.unclaimed_used_cpus + cpus),
                            unclaimed_used_memory_mb=(
                                cluster.c.unclaimed_used_memory_mb
                                + memory_mb),
                            unclaimed_used_disk_gb=(
                                cluster.c.unclaimed_used_disk_gb + disk_gb),
                            updated_at=sa.func.now())).rowcount == 0:
                    raise _AdmissionDenied('cluster')
            else:
                # The reconciler has never run, so there is no singleton
                # to draw down. Same fail-open reasoning as P7.
                outcome['unguarded'] = True

            # (3) and (4): the two scheduler_node_capacity rows, in uuid
            # order. Both statements touch the same table, so a fixed
            # intra-table order is the same discipline the inter-table
            # canonical order buys: without it two moves crossing in
            # opposite directions between the same pair of nodes take
            # each other's rows in opposite orders and deadlock. The
            # guard still decides the whole transaction whichever order
            # the rows are touched in, because a denial rolls the old
            # node's decrement back with everything else.
            def _claim_node() -> None:
                if not node_present:
                    return
                where = [capacity.c.node_uuid == node_key]
                if node_guarded:
                    where += [
                        capacity.c.used_cpus + cpus <= capacity.c.limit_cpus,
                        (capacity.c.used_memory_mb + memory_mb
                         <= capacity.c.limit_memory_mb),
                        (capacity.c.used_disk_gb + disk_gb
                         <= capacity.c.limit_disk_gb),
                    ]
                    demand = _demand_guard_clause(node_key, target_load)
                    if demand is not None:
                        where.append(demand)
                if conn.execute(sa.update(capacity).where(
                        sa.and_(*where)).values(
                            used_cpus=capacity.c.used_cpus + cpus,
                            used_memory_mb=(capacity.c.used_memory_mb
                                            + memory_mb),
                            used_disk_gb=capacity.c.used_disk_gb + disk_gb,
                            expected_demand=(capacity.c.expected_demand
                                             + demand_add),
                            updated_at=sa.func.now())).rowcount == 0:
                    raise _AdmissionDenied('node')

            def _release_old_node() -> None:
                if old_node_key is None:
                    return
                _, clamped = _floored_node_decrement(
                    conn, old_node_key, cpus, memory_mb, disk_gb)
                outcome['clamped'] = outcome['clamped'] or clamped

            if old_node_key is not None and old_node_key.int < node_key.int:
                _release_old_node()
                _claim_node()
            else:
                _claim_node()
                _release_old_node()

            # (5) The placement attribute, masked to the one column
            # exactly as the generic attribute write path does.
            if conn.execute(sa.update(attributes).where(
                    attributes.c.uuid == instance_key).values(
                        placement=placement_json)).rowcount == 0:
                raise _PlacementRowMissing(
                    f'instance {instance_uuid} has no instance_attributes row')

            # (6) The placement references. This delete is deliberately
            # unfiltered: an admission owns the invariant that exactly
            # one row survives it, so a historical duplicate on a node
            # the caller never named is swept here *without* crediting
            # that node (only old_node_uuid is decremented above). The
            # residual over-charge is conservative -- it refuses work
            # rather than overcommitting -- and the reconciler's next
            # pass recomputes it away; the release path instead keeps
            # rows and charges together (see
            # _delete_instance_location_rows).
            _delete_instance_location_rows(conn, instance_uuid)
            conn.execute(sa.insert(refs).values(
                # The type and relationship columns are plain String(64)
                # storing the enum *value* via str(member), and the uuid
                # columns store the dashed 36 character form -- both
                # conventions matching _direct_record_relationship
                # exactly, because the reconciler's ground-truth query
                # reads these rows.
                source_object_type=str(ObjectType.NODE),
                source_uuid=node_uuid,
                relationship=str(RelationshipType.INSTANCE_LOCATION),
                relationship_value=None,
                target_object_type=str(ObjectType.INSTANCE),
                target_uuid=instance_uuid,
                created=now,
                last_active=now))

            # MariaDB has no UPDATE ... RETURNING, so the post-admit
            # counters are a follow-up PK SELECT inside the transaction.
            if node_present:
                row = conn.execute(sa.select(capacity).where(
                    capacity.c.node_uuid == node_key)).first()
                if row is not None:
                    outcome['node_used_cpus'] = int(row.used_cpus)
                    outcome['node_used_memory_mb'] = int(row.used_memory_mb)
                    outcome['node_used_disk_gb'] = int(row.used_disk_gb)
                    outcome['node_expected_demand'] = float(
                        row.expected_demand)

            # Advisory claim accounting (D5). With claim_guarded False
            # the increment above cannot refuse, so an over-claim
            # namespace has just pushed its used_* past its limit_*;
            # that has to be *recorded* rather than lost. Read the row
            # back by primary key -- for the same reason as the node
            # counters just above, and legally for the same reason: this
            # is a read after our own write, on a row this transaction
            # already holds the lock on, which is what the ER_CHECKREAD
            # invariant permits. A second RPC would instead make every
            # create in a claimed namespace pay a probe round trip
            # (D5 rejects probe-then-force for exactly that).
            if claim_charged:
                row = conn.execute(sa.select(claims).where(
                    claims.c.uuid == claim_uuid)).first()
                if row is not None:
                    requested = {'cpus': cpus, 'memory_mb': memory_mb,
                                 'disk_gb': disk_gb}
                    for dimension in CAPACITY_DIMENSIONS:
                        amount = requested[dimension]
                        # used is reported as what the claim held
                        # *before* this admission, so the triple reads
                        # exactly as a denial's does: limit, prior
                        # usage, this request. exceeded then recomputes
                        # to used_after > limit, which is the advisory
                        # test.
                        detail = _capacity_dimension(
                            dimension,
                            getattr(row, f'limit_{dimension}'),
                            getattr(row, f'used_{dimension}') - amount,
                            amount)
                        if detail['exceeded']:
                            outcome['claim_dimensions'].append(detail)
                    outcome['claim_over_limit'] = bool(
                        outcome['claim_dimensions'])

        outcome['admitted'] = True
        return outcome

    try:
        return _retry_transaction(
            _admit, f'admit_instance_placement({instance_uuid})')
    except _AdmissionDenied as denial:
        result['failing_stage'] = denial.stage
        result['dimensions'] = _admission_denial_dimensions(
            denial.stage, namespace, node_key, cpus, memory_mb, disk_gb,
            demand_add, target_load)
        return result
    except _PlacementRowMissing as e:
        LOG.warning(f'MariaDB admit_instance_placement refused: {e}')
        result['success'] = False
        result['error'] = str(e)
        return result
    except (OperationalError, IntegrityError) as e:
        LOG.warning(
            f'MariaDB admit_instance_placement failed for '
            f'{instance_uuid}: {e}')
        result['success'] = False
        result['error'] = f'MariaDB error: {e}'
        return result


def _direct_release_instance_placement(
        instance_uuid: str, namespace: str, node_uuid: str, cpus: int,
        memory_mb: int, disk_gb: int) -> ReleasePlacementResult:
    """Give an instance's capacity back and drop its placement rows (P6).

    One transaction in D1's canonical order (the namespace side, then
    the node side), so release cannot deadlock against admission. Every
    decrement is floored at zero, so a release racing a reconcile pass
    cannot drive a counter negative.

    The reference lookup and the claim branch select run before the
    transaction opens (_probe_release_rows), so the transaction's first
    statement is an UPDATE -- see the block comment above
    _probe_admission_rows() for the ER_CHECKREAD invariant that requires
    it, and for what the resulting races resolve as.

    Idempotent by construction, in both call forms: the
    instance_location rows are the only record of what is charged, and
    the rows deleted are exactly the rows credited back (the delete is
    filtered to the probe's nodes, matching the decrement loop), so a
    second call -- whether it names a node or not -- finds nothing left
    to release, touches no counter and returns ``released=False``. A
    named node is a filter over those rows rather than an assertion
    that they exist (see _probe_release_rows()), and a named release
    leaves any row on *another* node alone, charge and all: the row and
    its charge always travel together, so a historical duplicate stays
    consistently charged until ``hard_delete()``'s unnamed sweep or the
    reconciler collects it. That is what makes the sweep safe to run
    behind ``_delete_globally()``'s release, and what stops a repeated
    delete of an errored instance from handing its capacity out twice.

    The ``placement`` attribute is deliberately not cleared (P8):
    ``enqueue_delete()`` and the event history both read it after
    deletion, and the reconciler's ledger already excludes instances in
    state ``deleted``.
    """
    engine = _get_engine()
    result: ReleasePlacementResult = {
        'success': True, 'error': '', 'released': False, 'clamped': False}

    try:
        named_node = UUID(node_uuid) if node_uuid else None
    except ValueError as e:
        LOG.warning(f'release_instance_placement given a malformed uuid: {e}')
        result['success'] = False
        result['error'] = f'malformed uuid: {e}'
        return result

    def _release() -> ReleasePlacementResult:
        outcome: ReleasePlacementResult = {
            'success': True, 'error': '', 'released': False, 'clamped': False}

        # The reference lookup and the branch select, on their own
        # connection outside the transaction below, for the reason in the
        # block comment above _probe_admission_rows(): the transaction's
        # first statement must be an UPDATE.
        probe = _probe_release_rows(namespace, instance_uuid, named_node)

        if not probe.nodes:
            # Nothing was held: this instance has no instance_location
            # row (or none on the node the caller named). Decrementing
            # here would take capacity away from an instance that no
            # longer holds any -- a double release -- so the counters are
            # left alone, no transaction is opened at all, and the caller
            # is told this was a no-op.
            return outcome

        with engine.begin() as conn:
            # INVARIANT: the first statement on this connection is the
            # floored namespace decrement, an UPDATE. Do not read here --
            # see _probe_admission_rows()'s block comment.

            # The namespace side is charged once per instance however
            # many nodes hold a reference for it -- duplicate placement
            # rows are exactly what the admission RPC exists to stop
            # producing, and the reconciler recomputes both sides from
            # ground truth every pass, so a residual discrepancy from a
            # historical duplicate corrects itself within one period.
            if _floored_namespace_decrement(
                    conn, probe.claim_uuid, cpus, memory_mb, disk_gb):
                outcome['clamped'] = True

            for node_key in sorted(set(probe.nodes), key=lambda u: u.int):
                _, clamped = _floored_node_decrement(
                    conn, node_key, cpus, memory_mb, disk_gb)
                outcome['clamped'] = outcome['clamped'] or clamped

            _delete_instance_location_rows(
                conn, instance_uuid, source_nodes=probe.nodes)
            outcome['released'] = True

        return outcome

    try:
        return _retry_transaction(
            _release, f'release_instance_placement({instance_uuid})')
    except (OperationalError, IntegrityError) as e:
        LOG.warning(
            f'MariaDB release_instance_placement failed for '
            f'{instance_uuid}: {e}')
        result['success'] = False
        result['error'] = f'MariaDB error: {e}'
        return result


def _direct_get_scheduler_node_capacity() -> list[SchedulerNodeCapacityRow]:
    """Read every scheduler_node_capacity row.

    A plain unfiltered SELECT: the table has one row per schedulable
    hypervisor, so it is small by construction and every caller so far
    wants all of it. Read outside a transaction -- a caller summarising
    cluster capacity is describing a moving target whatever it does, and
    holding a snapshot would only serialise it against admission.
    """
    engine = _get_engine()
    capacity = _get_scheduler_node_capacity_table()

    try:
        with engine.connect() as conn:
            rows = conn.execute(sa.select(capacity)).fetchall()
        return [
            {
                'node_uuid': str(row.node_uuid),
                'limit_cpus': int(row.limit_cpus),
                'limit_memory_mb': int(row.limit_memory_mb),
                'limit_disk_gb': int(row.limit_disk_gb),
                'used_cpus': int(row.used_cpus),
                'used_memory_mb': int(row.used_memory_mb),
                'used_disk_gb': int(row.used_disk_gb),
                'expected_demand': float(row.expected_demand),
            }
            for row in rows
        ]
    except OperationalError as e:
        LOG.warning(f'MariaDB query failed for scheduler_node_capacity: {e}')
        return []


def _grpc_admit_instance_placement(
        instance_uuid: str, namespace: str, node_uuid: str,
        old_node_uuid: str, cpus: int, memory_mb: int, disk_gb: int,
        demand_add: float, target_load: float, enforce: bool,
        placement_json: str) -> AdmitPlacementResult:
    """Admit a placement via the database microservice.

    This sits on the instance-create hot path, upstream of an API
    request the user is waiting on, so it uses the bounded budget rather
    than the default GRPC_RETRIES * GRPC_TIMEOUT worst case. A timeout
    is not ambiguous the way a lost write would be: the transaction is
    atomic, so it either committed (and the reconciler will agree with
    the counters) or it did not, and the caller retries or walks to the
    next candidate.
    """
    result = _empty_admit_result()
    try:
        stub = _get_database_stub()
        request = database_pb2.AdmitInstancePlacementRequest(
            instance_uuid=instance_uuid,
            namespace=namespace,
            node_uuid=node_uuid,
            old_node_uuid=old_node_uuid,
            cpus=cpus,
            memory_mb=memory_mb,
            disk_gb=disk_gb,
            demand_add=demand_add,
            target_load=target_load,
            enforce=enforce,
            placement_json=placement_json)
        reply = _grpc_call(
            stub.AdmitInstancePlacement, request,
            timeout=BOUNDED_QUERY_TIMEOUT, max_slow_failures=1)
        result['success'] = bool(reply.success)
        result['error'] = reply.error
        result['admitted'] = bool(reply.admitted)
        result['unguarded'] = bool(reply.unguarded)
        result['clamped'] = bool(reply.clamped)
        result['failing_stage'] = reply.failing_stage
        result['dimensions'] = [
            {
                'dimension': d.dimension,
                'limit': float(d.limit),
                'used': float(d.used),
                'requested': float(d.requested),
                'exceeded': bool(d.exceeded),
            } for d in reply.dimensions]
        result['node_used_cpus'] = int(reply.node_used_cpus)
        result['node_used_memory_mb'] = int(reply.node_used_memory_mb)
        result['node_used_disk_gb'] = int(reply.node_used_disk_gb)
        result['node_expected_demand'] = float(reply.node_expected_demand)
        result['claim_over_limit'] = bool(reply.claim_over_limit)
        result['claim_dimensions'] = [
            {
                'dimension': d.dimension,
                'limit': float(d.limit),
                'used': float(d.used),
                'requested': float(d.requested),
                'exceeded': bool(d.exceeded),
            } for d in reply.claim_dimensions]
        return result
    except (exceptions.DatabaseUnavailable, grpc.RpcError) as e:
        LOG.error(f'gRPC AdmitInstancePlacement failed: {e}')
        result['success'] = False
        if (isinstance(e, grpc.RpcError) and
                e.code() == grpc.StatusCode.UNIMPLEMENTED):
            # A mixed-version window: this RPC has no Python fallback,
            # so an old sf-database fails every create until it is
            # upgraded. Name the cause so the resulting 500 does.
            result['error'] = (
                'database service predates AdmitInstancePlacement; '
                f'upgrade sf-database before sf-api: {e}')
        else:
            result['error'] = f'database unavailable: {e}'
        return result


def _grpc_release_instance_placement(
        instance_uuid: str, namespace: str, node_uuid: str, cpus: int,
        memory_mb: int, disk_gb: int) -> ReleasePlacementResult:
    """Release a placement via the database microservice.

    Bounded like the admission call: this runs on the delete path, and a
    release that could not be recorded is repaired by the next reconcile
    pass rather than by blocking the delete.
    """
    result: ReleasePlacementResult = {
        'success': True, 'error': '', 'released': False, 'clamped': False}
    try:
        stub = _get_database_stub()
        request = database_pb2.ReleaseInstancePlacementRequest(
            instance_uuid=instance_uuid,
            namespace=namespace,
            node_uuid=node_uuid,
            cpus=cpus,
            memory_mb=memory_mb,
            disk_gb=disk_gb)
        reply = _grpc_call(
            stub.ReleaseInstancePlacement, request,
            timeout=BOUNDED_QUERY_TIMEOUT, max_slow_failures=1)
        result['success'] = bool(reply.success)
        result['error'] = reply.error
        result['released'] = bool(reply.released)
        result['clamped'] = bool(reply.clamped)
        return result
    except (exceptions.DatabaseUnavailable, grpc.RpcError) as e:
        LOG.error(f'gRPC ReleaseInstancePlacement failed: {e}')
        result['success'] = False
        result['error'] = f'database unavailable: {e}'
        return result


def _grpc_get_scheduler_node_capacity() -> list[SchedulerNodeCapacityRow]:
    """Read the per-node capacity counters via the database microservice.

    Bounded like the admission call it runs in front of. This read is on
    the same hot paths -- find_candidates() for an instance create, and
    the queues daemon's preflight redirect -- so leaving it on the
    default GRPC_RETRIES * GRPC_TIMEOUT budget would reopen the watchdog
    window that bounding the admission closed (issue 3586). Nothing is
    lost by failing early: the caller degrades to measurement-only
    pre-filtering and the guard still refuses correctly.
    """
    try:
        stub = _get_database_stub()
        request = database_pb2.GetSchedulerNodeCapacityRequest()
        reply = _grpc_call(
            stub.GetSchedulerNodeCapacity, request,
            timeout=BOUNDED_QUERY_TIMEOUT, max_slow_failures=1)
        return [
            {
                'node_uuid': row.node_uuid,
                'limit_cpus': int(row.limit_cpus),
                'limit_memory_mb': int(row.limit_memory_mb),
                'limit_disk_gb': int(row.limit_disk_gb),
                'used_cpus': int(row.used_cpus),
                'used_memory_mb': int(row.used_memory_mb),
                'used_disk_gb': int(row.used_disk_gb),
                'expected_demand': float(row.expected_demand),
            }
            for row in reply.rows
        ]
    except (exceptions.DatabaseUnavailable, grpc.RpcError) as e:
        LOG.warning(f'gRPC GetSchedulerNodeCapacity failed: {e}')
        return []


def admit_instance_placement(
        instance_uuid: str, namespace: str, node_uuid: str, cpus: int,
        memory_mb: int, disk_gb: int, placement_json: str,
        old_node_uuid: str = '',
        enforce: bool = True,
        enforce_demand: bool = True) -> AdmitPlacementResult:
    """Atomically claim capacity for an instance and place it.

    The D13 demand parameters come from this process's config, like the
    reconciler's, so the database daemon needs no copy of the scheduler
    configuration.

    ``enforce_demand=False`` waives the D13 demand clause for this
    admission (by sending a zero target load, which the guard treats as
    "clause disabled") while leaving every real capacity dimension
    guarded and still accumulating the placement's demand contribution.
    It exists for the walkers' second pass: when no candidate admitted
    and at least one was refused on demand alone, there is no quieter
    node to spread the burst to, and refusing a cluster with free real
    capacity would turn a load-spreading heuristic into a user-visible
    rate limit.

    Returns:

        {'success': bool, 'error': str,
         'admitted': bool, 'unguarded': bool, 'clamped': bool,
         'failing_stage': '' | 'cluster' | 'claim' | 'node',
         'dimensions': [{'dimension': str, 'limit': float, 'used': float,
                         'requested': float, 'exceeded': bool}, ...],
         'node_used_cpus': int, 'node_used_memory_mb': int,
         'node_used_disk_gb': int, 'node_expected_demand': float,
         'claim_over_limit': bool, 'claim_dimensions': [...]}

    ``claim_over_limit`` and ``claim_dimensions`` are the advisory
    accounting of D16: the placement *was* admitted, and the namespace's
    claim is now over its limits in the named dimensions. They are
    separate from ``failing_stage``/``dimensions``, which describe a
    refusal.

    ``success`` says the RPC ran; ``admitted`` says what it decided.
    A caller that treats a failed RPC as a denial would walk to the next
    candidate on a database blip and eventually 507 a create that had
    plenty of capacity, so the two are deliberately separate fields.
    """
    demand_add = cpus * config.SCHEDULER_DEMAND_PER_VCPU
    target_load = config.SCHEDULER_TARGET_LOAD if enforce_demand else 0.0
    if _use_database_service():
        return _grpc_admit_instance_placement(
            instance_uuid, namespace, node_uuid, old_node_uuid, cpus,
            memory_mb, disk_gb, demand_add, target_load,
            enforce, placement_json)
    return _direct_admit_instance_placement(
        instance_uuid, namespace, node_uuid, old_node_uuid, cpus, memory_mb,
        disk_gb, demand_add, target_load, enforce,
        placement_json)


def release_instance_placement(
        instance_uuid: str, namespace: str, cpus: int, memory_mb: int,
        disk_gb: int, node_uuid: str = '') -> ReleasePlacementResult:
    """Give an instance's claimed capacity back and drop its placement.

    ``node_uuid`` is optional: an empty value releases wherever the
    instance's placement references point, which is what the delete
    paths want since they know the instance rather than its node. A
    non-empty value *filters* those references rather than replacing
    them -- naming a node the instance holds no reference on releases
    nothing, because the reference rows are the only record of what is
    charged.

    Returns:

        {'success': bool, 'error': str, 'released': bool,
         'clamped': bool}

    ``released`` is False when there was nothing to release, which is
    how a repeat call (``hard_delete()`` behind ``_delete_globally()``,
    or a second delete attempt on an errored instance) is told from a
    real one.
    """
    if _use_database_service():
        return _grpc_release_instance_placement(
            instance_uuid, namespace, node_uuid, cpus, memory_mb, disk_gb)
    return _direct_release_instance_placement(
        instance_uuid, namespace, node_uuid, cpus, memory_mb, disk_gb)


def get_scheduler_node_capacity() -> list[SchedulerNodeCapacityRow]:
    """The materialised per-node capacity counters, one dict per row.

    These are the numbers admission actually draws down, so a reader
    which wants to publish "what would this cluster admit?" must read
    them rather than recompute a second ledger of its own.

    Returns an empty list if the table is empty or unreadable. Only
    hypervisors the reconciler considers schedulable have a row, so an
    absent node is not an error: it is a node whose capacity the
    reconciler declined to guess (P7), which admits unguarded.
    """
    if _use_database_service():
        return _grpc_get_scheduler_node_capacity()
    return _direct_get_scheduler_node_capacity()


# =============================================================================
# Namespace Claim CRUD (MariaDB)
#
# Scheduler-reservations phase 4: the rows nothing could create until now,
# which is why phase 3's claim branch was unreachable in production. See
# docs/plans/PLAN-scheduler-reservations-phase-04-claims-api.md.
#
# A claim is a promise the cluster has to be able to keep, so creating one
# -- and growing one -- is an admission decision in its own right, against
# the same cluster_capacity singleton an instance create draws down. D14's
# mirror guard is _claim_capacity_guard(): claimed + requested +
# GREATEST(0, unclaimed_used - migrated) <= total, which tests the state
# the guarded statement's own SET produces rather than the one it started
# from. Everything the admission primitive above had to get right applies
# here unchanged:
#
# * the canonical write order, cluster_capacity then namespace_claims, so
#   these transactions contend with instance admission rather than
#   deadlocking against it (admission takes at most one of the two, and
#   always before scheduler_node_capacity, so every writer of the three
#   tables takes them in the same order),
# * the ER_CHECKREAD invariant -- every transaction here opens with a
#   guarded UPDATE and does its reads afterwards, on rows it holds locks
#   on. Read the block comment above _probe_admission_rows() before
#   changing any of them,
# * _retry_transaction() for 1213/1205/1020, whole-transaction retry.
#
# Two things are new. Creation migrates the namespace's existing drawdown
# into the claim (D3) rather than seeding zero, closing a window in which
# a namespace could place its entire claim a second time. And an update
# evaluates each dimension on its own terms in one transaction (D8): a
# grow is guarded, a shrink is floored at the claim's current used_*, and
# one request may do both. There is no auto-grow, ever (D15).
# =============================================================================

# Coverage states of a claim (D2). These are *not* the object's existence
# state -- that lives in object_states like every other object's -- and
# the two must never encode each other.
CLAIM_STATE_ACTIVE = 'active'

# The claim fields an update request may name in its field mask. The mask
# is what tells a deliberate zero from an unset proto3 int, exactly as
# the update_*_attributes field masks do (CLAUDE.md pitfall 3).
CLAIM_UPDATE_FIELDS = (
    'limit_cpus', 'limit_memory_mb', 'limit_disk_gb', 'expires_in_seconds')

# How many times an update or delete re-probes and re-runs when a
# concurrent writer moved the claim row between the probe and the
# transaction. This is not the transient-error retry above: nothing
# failed, the optimistic guard simply found the row was no longer what
# the deltas were computed from, so the only correct response is to
# recompute them from what is there now.
_CLAIM_STALE_MAX_ATTEMPTS = 4


class NamespaceClaimRow(TypedDict):
    """One namespace_claims row, as readers of the claims API see it."""

    uuid: str
    namespace: str
    limit_cpus: int
    limit_memory_mb: int
    limit_disk_gb: int
    used_cpus: int
    used_memory_mb: int
    used_disk_gb: int
    state: str
    expires_at: float
    updated_at: float


class CreateNamespaceClaimResult(TypedDict):
    """The reply _direct_create_namespace_claim builds."""

    success: bool
    error: str
    created: bool
    refused_reason: str
    dimensions: list[CapacityDimensionDetailDict]
    claim: Optional[NamespaceClaimRow]


class UpdateNamespaceClaimResult(TypedDict):
    """The reply _direct_update_namespace_claim builds."""

    success: bool
    error: str
    updated: bool
    refused_reason: str
    dimensions: list[CapacityDimensionDetailDict]
    claim: Optional[NamespaceClaimRow]


class DeleteNamespaceClaimResult(TypedDict):
    """The reply _direct_delete_namespace_claim builds."""

    success: bool
    error: str
    deleted: bool
    returned_cpus: int
    returned_memory_mb: int
    returned_disk_gb: int
    clamped: bool


class _ClaimRefused(Exception):
    """This operation cannot proceed, and the caller is told why.

    Carries the reason the reply reports ('capacity', 'exists',
    'not_found', 'not_active', 'no_cluster_capacity') and, for a
    capacity refusal, what was asked for in each dimension so the
    reply's detail is denominated in the amount the guard actually
    tested. Raised either from a probe before the transaction opens or
    from inside the ``engine.begin()`` block, which rolls the
    transaction back on the way out; the per-dimension detail is then
    assembled from a fresh read, exactly as _AdmissionDenied's is.
    """

    def __init__(self, reason: str,
                 requested: Optional[dict[str, int]] = None,
                 migrated: Optional[dict[str, int]] = None) -> None:
        super().__init__(reason)
        self.reason = reason
        self.requested = requested or {}
        # The drawdown the refused statement would have migrated, so the
        # detail describes the state the guard actually tested. Zero for
        # a grow, which migrates nothing.
        self.migrated = migrated or {}


class _ClaimRowStale(Exception):
    """The claim row moved between the probe and the transaction.

    Nothing failed and nothing was refused: the optimistic guard on the
    limits the deltas were computed from simply did not match, so the
    whole operation re-probes and runs again.
    """


def _empty_create_claim_result() -> CreateNamespaceClaimResult:
    """A successful, not-yet-decided claim creation reply."""
    return {
        'success': True,
        'error': '',
        'created': False,
        'refused_reason': '',
        'dimensions': [],
        'claim': None,
    }


def _empty_update_claim_result() -> UpdateNamespaceClaimResult:
    """A successful, not-yet-decided claim update reply."""
    return {
        'success': True,
        'error': '',
        'updated': False,
        'refused_reason': '',
        'dimensions': [],
        'claim': None,
    }


def _empty_delete_claim_result() -> DeleteNamespaceClaimResult:
    """A successful, not-yet-decided claim deletion reply."""
    return {
        'success': True,
        'error': '',
        'deleted': False,
        'returned_cpus': 0,
        'returned_memory_mb': 0,
        'returned_disk_gb': 0,
        'clamped': False,
    }


def _claim_capacity_guard(
        dimension: str, requested: int,
        migrated: int) -> sa.ColumnElement[bool]:
    """D14's mirror guard for one dimension, in its migration-aware form.

    ``claimed + requested + GREATEST(0, unclaimed_used - migrated) <=
    total``: what the singleton will hold *after* this statement commits
    has to fit in the cluster's totals.

    ``migrated`` is the drawdown this statement moves off the unclaimed
    side and onto the claim side in the same UPDATE. It is an explicit
    parameter precisely because it is **not** the same for every caller:

    * **Creation** passes the namespace's existing drawdown (D3).
      Without the term the guard tests a state the write cannot produce
      -- it counts the namespace's own usage on the unclaimed side,
      which this very statement is about to take off it -- and so
      refuses an operator claiming capacity their namespace is already
      holding. Concretely: 100 cpus total, 80 used by unclaimed
      namespaces of which 40 belong to ci-1, and a 40 cpu claim for ci-1
      lands at claimed 40 plus unclaimed_used 40, a consistent 80 of
      100. The term-less form computed ``0 + 40 <= 100 - 80`` and
      refused it.
    * **A grow** passes zero, and must keep passing zero. A grow
      migrates nothing: the namespace's usage is already on the claim
      side of the ledger, counted in the claim's own ``used_*`` rather
      than in ``unclaimed_used_*``, so subtracting a drawdown here would
      credit the same capacity twice and grant a claim the cluster
      cannot keep. Do not "simplify" this by handing a grow the
      namespace's drawdown; there is a test pinning the term at zero.

    The ``GREATEST(0, ...)`` is load bearing rather than decorative. The
    ``unclaimed_used_*`` decrement in the same statement is floored the
    same way, and a guard that floored differently from the write it
    guards would be testing a state the write cannot reach. It is also
    what keeps a drawdown larger than the singleton's unclaimed sums --
    an instance stranded on a node with no capacity row is
    namespace-wide usage the reconciler's unclaimed fold never counted
    -- clamping conservatively instead of crediting capacity that was
    never charged.
    """
    cluster = _get_cluster_capacity_table()
    return (cluster.c[f'claimed_{dimension}'] + requested
            + sa.func.greatest(
                0, cluster.c[f'unclaimed_used_{dimension}'] - migrated)
            <= cluster.c[f'total_{dimension}'])


def _claim_expiry_expression(expires_in_seconds: int) -> sa.ColumnElement[Any]:
    """An expiry ``expires_in_seconds`` from the *server's* now.

    Deliberately not a client-computed datetime. ``expires_at`` is only
    ever compared against the database's NOW() -- by the reconciler's
    expiry sweep and by _active_claim_for_namespace() -- so a value
    computed on a node whose clock or timezone differs expires the claim
    at the wrong moment, or instantly, with nothing to show for it. The
    reconciler's live suite records finding exactly that during phase 2.

    UNIX_TIMESTAMP()/FROM_UNIXTIME() rather than ``NOW() + INTERVAL n
    SECOND`` so the arithmetic is an ordinary bound integer instead of
    interval syntax around a parameter, and so it round-trips exactly
    with the UNIX_TIMESTAMP() read-back in _claim_select().
    """
    return sa.func.from_unixtime(
        sa.func.unix_timestamp() + expires_in_seconds)


def _claim_select() -> sa.Select[Any]:
    """The projection every claim read returns.

    The two timestamps are converted to epoch seconds server side. They
    are DATETIME columns written from the server's own clock, so a client
    that reinterpreted them in its own timezone would publish an expiry
    hours away from the one the expiry sweep will use.
    """
    claims = _get_namespace_claims_table()
    return sa.select(
        claims.c.uuid, claims.c.namespace, claims.c.limit_cpus,
        claims.c.limit_memory_mb, claims.c.limit_disk_gb,
        claims.c.used_cpus, claims.c.used_memory_mb, claims.c.used_disk_gb,
        claims.c.state,
        sa.func.unix_timestamp(claims.c.expires_at).label('expires_at'),
        sa.func.unix_timestamp(claims.c.updated_at).label('updated_at'))


def _claim_row_to_dict(row: sa.Row[Any]) -> NamespaceClaimRow:
    """Convert a _claim_select() row into the dict callers see."""
    return {
        'uuid': str(row.uuid),
        'namespace': str(row.namespace),
        'limit_cpus': int(row.limit_cpus),
        'limit_memory_mb': int(row.limit_memory_mb),
        'limit_disk_gb': int(row.limit_disk_gb),
        'used_cpus': int(row.used_cpus),
        'used_memory_mb': int(row.used_memory_mb),
        'used_disk_gb': int(row.used_disk_gb),
        'state': str(row.state),
        'expires_at': float(row.expires_at or 0),
        'updated_at': float(row.updated_at or 0),
    }


def _read_claim_row(claim_key: UUID) -> Optional[sa.Row[Any]]:
    """Read one claim row on its own connection, outside any transaction.

    Update and delete both need the claim's current limits and usage
    *before* they open their transaction, for the same reason
    _probe_admission_rows() does: the first statement inside the
    transaction has to be a guarded UPDATE.
    """
    engine = _get_engine()
    claims = _get_namespace_claims_table()
    with engine.connect() as conn:
        return conn.execute(_claim_select().where(
            claims.c.uuid == claim_key)).first()


class _ClaimCreateProbe(NamedTuple):
    """What a claim creation must know before it opens its transaction.

    ``drawdown`` is keyed by CAPACITY_DIMENSIONS, so the create's
    statements can be written as a comprehension over the dimensions
    rather than three near-identical copies.
    """

    drawdown: dict[str, int]
    cluster_present: bool
    claim_exists: bool


def _probe_claim_create(namespace: str) -> _ClaimCreateProbe:
    """Read a creation's drawdown and presence probes (D3).

    Runs on its own connection, outside the write transaction, for the
    reason in the block comment above _probe_admission_rows(): a plain
    SELECT as the transaction's first statement re-introduces
    ER_CHECKREAD under innodb_snapshot_isolation.

    All three reads are time-of-check-to-time-of-use racy by
    construction, and each resolves acceptably:

    * The drawdown. A create or delete in this namespace between the
      probe and the transaction moves the figure by at most one
      instance's allocation, in one direction, and the reconciler
      recomputes both the claim's used_* and the cluster's unclaimed
      sums from ground truth within a pass. This is the same bargain
      phase 3 struck for the branch probe, and D3 names it explicitly.
    * The cluster singleton probe. Absent-then-created refuses a create
      the operator can simply repeat; present-then-deleted makes the
      guarded UPDATE match no row, which reads as a capacity refusal.
      Neither writes anything.
    * The existing-claim probe. Two creates racing for one namespace can
      both pass it and both commit. That is not an accounting error --
      the reconciler rebuilds claimed_* from the sum of *every* active
      claim's limits, so both are counted -- but the namespace then has
      two claims and admission draws down the lowest-uuid one
      (_active_claim_for_namespace orders by uuid). An operator deletes
      the extra. Serialising this properly needs a uniqueness constraint
      the table does not have, which is a schema change and not this
      step's.

    None of the three can over-admit past a guard that was actually
    evaluated, and none leaves a counter the reconciler will not repair.
    """
    engine = _get_engine()
    cluster = _get_cluster_capacity_table()

    with engine.connect() as conn:
        row = conn.execute(
            _NAMESPACE_DRAWDOWN_SQL,
            _namespace_drawdown_params(namespace)).first()
        drawdown = {
            'cpus': int(row.used_cpus) if row is not None else 0,
            'memory_mb': int(row.used_memory_mb) if row is not None else 0,
            'disk_gb': int(row.used_disk_gb) if row is not None else 0,
        }
        cluster_present = conn.execute(sa.select(cluster.c.id).where(
            cluster.c.id == 1)).first() is not None
        claim_exists = _active_claim_for_namespace(
            conn, namespace) is not None

    return _ClaimCreateProbe(
        drawdown=drawdown, cluster_present=cluster_present,
        claim_exists=claim_exists)


def _cluster_capacity_dimensions(
        requested: dict[str, int],
        migrated: Optional[dict[str, int]] = None
) -> list[CapacityDimensionDetailDict]:
    """Per-dimension detail for a mirror-guard refusal, read after rollback.

    The same shape, and the same caveat, as _admission_denial_dimensions()
    for its cluster stage: MariaDB cannot say which WHERE clause failed
    and the transaction that knew has been rolled back, so the numbers
    come from a follow-up read and ``exceeded`` is recomputed from what
    was read rather than asserted.

    The triple is _claim_capacity_guard() rearranged into the
    limit/used/requested shape every other denial detail uses. D14's
    effective limit is what active claims have not already spoken for,
    so ``limit`` is ``total - claimed``; ``used`` is the unclaimed sums
    *after* the migration this operation would have performed, so a
    creation's detail describes the state it was actually refused
    against rather than one it was never testing. ``migrated`` is
    therefore the same figure the guard was given, and defaults to zero
    for a grow, which migrates nothing.
    """
    engine = _get_engine()
    cluster = _get_cluster_capacity_table()
    dimensions: list[CapacityDimensionDetailDict] = []
    migrated = migrated or {}

    try:
        with engine.connect() as conn:
            row = conn.execute(sa.select(cluster).where(
                cluster.c.id == 1)).first()
            if row is not None:
                for dimension in CAPACITY_DIMENSIONS:
                    dimensions.append(_capacity_dimension(
                        dimension,
                        (getattr(row, f'total_{dimension}')
                         - getattr(row, f'claimed_{dimension}')),
                        max(0, (getattr(row, f'unclaimed_used_{dimension}')
                                - migrated.get(dimension, 0))),
                        requested.get(dimension, 0)))
    except OperationalError as e:
        # Diagnostic, not load bearing: the refusal is already decided.
        LOG.warning(f'Could not read claim refusal detail: {e}')

    return dimensions


def _direct_create_namespace_claim(
        claim_uuid: str, namespace: str, limit_cpus: int,
        limit_memory_mb: int, limit_disk_gb: int,
        expires_in_seconds: int) -> CreateNamespaceClaimResult:
    """Create a namespace claim, guarded against the cluster (D3, D14).

    One transaction in D1's canonical order, retried as a whole on
    transient contention. The steps are:

    1. The drawdown and presence probes, **outside** the transaction
       (_probe_claim_create). The drawdown comes from
       _NAMESPACE_DRAWDOWN_SQL, which is the reconciler's own per-claim
       aggregation restricted to one namespace, so the row this creates
       starts at the figure the next reconcile pass will compute and
       that pass then moves nothing.
    2. The guarded ``cluster_capacity`` UPDATE, which is therefore the
       transaction's first statement: ``claimed_*`` up by the new
       limits, ``unclaimed_used_*`` down by the migrated drawdown,
       guarded by D14's mirror of the admission guard in its
       migration-aware form -- ``claimed + limit + GREATEST(0,
       unclaimed_used - migrated) <= total``, which is exactly the state
       this statement's own SET produces (see _claim_capacity_guard). A
       rowcount of zero is the refusal -- and note the CLIENT_FOUND_ROWS
       semantics recorded in _direct_admit_instance_placement()'s
       docstring: it counts rows *matched*, which is what makes a
       zero-sized claim read as "the guard passed" rather than as a
       denial.
    3. The ``INSERT``, with ``used_*`` seeded to the migrated drawdown
       and coverage state 'active'.
    4. A read-back of the row just inserted, for the reply. A read after
       our own write, on a row this transaction holds the lock on, which
       is what the ER_CHECKREAD invariant permits.

    **A missing cluster_capacity singleton refuses rather than failing
    open**, which is deliberately the opposite of P7's decision for an
    instance placement, because the two are not the same bet. Admitting
    an instance unguarded records where a machine already is, and the
    reconciler agrees with the counters within one pass. Creating a claim
    unguarded writes a *promise*, against totals nothing has computed
    yet, that the cluster may have no way to keep -- and the next pass
    will fold those limits into ``claimed_*`` whether or not they fit,
    starving every unclaimed namespace until an operator notices. The
    singleton exists from the first reconcile pass on any cluster with a
    hypervisor, and a claim, unlike an instance create, can simply be
    made again five minutes later.

    The ``unclaimed_used_*`` decrement is floored at zero for the same
    reason every decrement in this subsystem is: the drawdown is a probe,
    and a concurrent release must not be able to drive a counter
    negative. It is also namespace-wide where the reconciler's unclaimed
    fold is restricted to nodes holding a capacity row, so an instance
    stranded on an unsized node is subtracted here having never been
    added there. Bounded by that namespace's stranded instances and
    corrected by the next pass, and the alternative -- a second,
    differently-restricted aggregation -- would reintroduce exactly the
    drift that sharing one query exists to prevent.
    """
    result = _empty_create_claim_result()

    try:
        claim_key = UUID(claim_uuid)
    except ValueError as e:
        LOG.warning(f'create_namespace_claim given a malformed uuid: {e}')
        result['success'] = False
        result['error'] = f'malformed uuid: {e}'
        return result

    if not namespace:
        result['success'] = False
        result['error'] = 'namespace is required'
        return result
    if min(limit_cpus, limit_memory_mb, limit_disk_gb) < 0:
        result['success'] = False
        result['error'] = 'claim limits cannot be negative'
        return result
    if expires_in_seconds <= 0:
        result['success'] = False
        result['error'] = 'expires_in_seconds must be positive'
        return result

    engine = _get_engine()
    claims = _get_namespace_claims_table()
    cluster = _get_cluster_capacity_table()
    limits = {'cpus': limit_cpus, 'memory_mb': limit_memory_mb,
              'disk_gb': limit_disk_gb}

    def _create() -> CreateNamespaceClaimResult:
        outcome = _empty_create_claim_result()

        # (1) The probes, deliberately on their own connection outside
        # the transaction below -- see the block comment above
        # _probe_admission_rows(). Re-run on every attempt, so a
        # transaction that lost a race re-reads the world.
        probe = _probe_claim_create(namespace)
        if probe.claim_exists:
            raise _ClaimRefused('exists')
        if not probe.cluster_present:
            raise _ClaimRefused('no_cluster_capacity')
        migrated = probe.drawdown

        with engine.begin() as conn:
            # INVARIANT: the first statement executed on this connection
            # must be a guarded UPDATE. A plain SELECT here establishes
            # the transaction's read view early and makes every later
            # guarded UPDATE against a contended row abort with
            # ER_CHECKREAD (1020) under innodb_snapshot_isolation, which
            # is ON by default from MariaDB 11.6.2. Reads after our own
            # writes are fine -- we hold those row locks.

            # (2) cluster_capacity, first in the canonical order.
            # D14's mirror of the admission guard, per dimension, in the
            # migration-aware form: the guard tests the state this
            # statement's own SET produces, drawdown migration included
            # (see _claim_capacity_guard).
            guarded = sa.update(cluster).where(sa.and_(
                cluster.c.id == 1, *[
                    _claim_capacity_guard(d, limits[d], migrated[d])
                    for d in CAPACITY_DIMENSIONS])).values(
                updated_at=sa.func.now(), **{
                    f'claimed_{d}': cluster.c[f'claimed_{d}'] + limits[d]
                    for d in CAPACITY_DIMENSIONS
                }, **{
                    f'unclaimed_used_{d}': sa.func.greatest(
                        0, cluster.c[f'unclaimed_used_{d}'] - migrated[d])
                    for d in CAPACITY_DIMENSIONS
                })
            if conn.execute(guarded).rowcount == 0:
                raise _ClaimRefused(
                    'capacity', requested=limits, migrated=migrated)

            # (3) namespace_claims, second in the canonical order.
            conn.execute(sa.insert(claims).values(
                uuid=claim_key,
                namespace=namespace,
                limit_cpus=limit_cpus,
                limit_memory_mb=limit_memory_mb,
                limit_disk_gb=limit_disk_gb,
                used_cpus=migrated['cpus'],
                used_memory_mb=migrated['memory_mb'],
                used_disk_gb=migrated['disk_gb'],
                state=CLAIM_STATE_ACTIVE,
                expires_at=_claim_expiry_expression(expires_in_seconds),
                updated_at=sa.func.now()))

            # (4) Read back what we just wrote, for the reply.
            row = conn.execute(_claim_select().where(
                claims.c.uuid == claim_key)).first()
            if row is not None:
                outcome['claim'] = _claim_row_to_dict(row)

        outcome['created'] = True
        return outcome

    try:
        return _retry_transaction(
            _create, f'create_namespace_claim({claim_uuid})')
    except _ClaimRefused as refusal:
        result['refused_reason'] = refusal.reason
        if refusal.reason == 'capacity':
            result['dimensions'] = _cluster_capacity_dimensions(
                refusal.requested, refusal.migrated)
        return result
    except (OperationalError, IntegrityError) as e:
        LOG.warning(
            f'MariaDB create_namespace_claim failed for {claim_uuid}: {e}')
        result['success'] = False
        result['error'] = f'MariaDB error: {e}'
        return result


def _direct_update_namespace_claim(
        claim_uuid: str, fields: list[str], limit_cpus: int,
        limit_memory_mb: int, limit_disk_gb: int,
        expires_in_seconds: int) -> UpdateNamespaceClaimResult:
    """Grow, shrink or re-date a claim in one transaction (D8).

    ``fields`` is the mask naming which of CLAIM_UPDATE_FIELDS this
    request actually sets; anything unnamed is left exactly as it is,
    which is how a deliberate zero is told from an unset proto3 int. Per
    D15 there is no auto-grow: every change here is one an operator
    asked for.

    Each dimension is evaluated on its own terms, in one transaction, so
    a single request may grow one and shrink another:

    * **Grow** is an admission decision against D14's mirror guard,
      exactly as creation is, and increments ``claimed_*`` by the delta.
      Its migrated-drawdown term is zero and must stay zero: a grow
      moves nothing off the cluster's unclaimed side, because the
      namespace's usage is already counted in this claim's ``used_*``
      (see _claim_capacity_guard).
    * **Shrink** is always permitted down to the claim's current
      ``used_*`` and no further. The floor is a SQL guard (``used_* <=
      new limit``) rather than a Python comparison against the probe, so
      an instance create that commits between the probe and the
      transaction cannot slip the claim under its own usage.
    * **Expiry** may be extended or shortened, and is written from the
      server's clock (see _claim_expiry_expression).

    The deltas are computed from limits read outside the transaction, so
    the claim UPDATE also carries an optimistic guard on those limits.
    If a concurrent writer moved them the whole operation re-probes and
    runs again rather than applying a delta to the wrong base --
    _ClaimRowStale, bounded by _CLAIM_STALE_MAX_ATTEMPTS and reported as
    'conflict' if the row never stops moving.

    A claim which is not in coverage state 'active' is refused
    ('not_active'). Its limits are not in ``claimed_*`` -- the reconciler
    sums active claims only -- so adjusting that counter on its behalf
    would be adjusting it for capacity nobody is holding. Reviving an
    expired claim is a delete and a create.
    """
    result = _empty_update_claim_result()

    try:
        claim_key = UUID(claim_uuid)
    except ValueError as e:
        LOG.warning(f'update_namespace_claim given a malformed uuid: {e}')
        result['success'] = False
        result['error'] = f'malformed uuid: {e}'
        return result

    unknown = [f for f in fields if f not in CLAIM_UPDATE_FIELDS]
    if unknown:
        result['success'] = False
        result['error'] = f'unknown claim fields: {sorted(unknown)}'
        return result
    if not fields:
        result['success'] = False
        result['error'] = 'fields is required'
        return result

    requested = {'cpus': limit_cpus, 'memory_mb': limit_memory_mb,
                 'disk_gb': limit_disk_gb}
    changing = {d for d in CAPACITY_DIMENSIONS if f'limit_{d}' in fields}
    if any(requested[d] < 0 for d in changing):
        result['success'] = False
        result['error'] = 'claim limits cannot be negative'
        return result
    change_expiry = 'expires_in_seconds' in fields
    if change_expiry and expires_in_seconds <= 0:
        result['success'] = False
        result['error'] = 'expires_in_seconds must be positive'
        return result

    engine = _get_engine()
    claims = _get_namespace_claims_table()
    cluster = _get_cluster_capacity_table()

    def _attempt() -> UpdateNamespaceClaimResult:
        outcome = _empty_update_claim_result()

        # The probe, on its own connection outside the transaction --
        # see the block comment above _probe_admission_rows().
        current = _read_claim_row(claim_key)
        if current is None:
            raise _ClaimRefused('not_found')
        if current.state != CLAIM_STATE_ACTIVE:
            raise _ClaimRefused('not_active')

        old_limits = {d: int(getattr(current, f'limit_{d}'))
                      for d in CAPACITY_DIMENSIONS}
        new_limits = {d: (requested[d] if d in changing else old_limits[d])
                      for d in CAPACITY_DIMENSIONS}
        deltas = {d: new_limits[d] - old_limits[d]
                  for d in CAPACITY_DIMENSIONS}

        # A missing singleton refuses a grow for the reason
        # _direct_create_namespace_claim() records -- an unguarded
        # promise is worse than a refused one -- but must not stand in
        # the way of giving capacity back or shortening a claim, neither
        # of which can over-promise anything. Probed on its own
        # connection, outside the transaction, like every other read
        # here.
        with engine.connect() as conn:
            cluster_present = conn.execute(sa.select(cluster.c.id).where(
                cluster.c.id == 1)).first() is not None
        grows = {d: delta for d, delta in deltas.items() if delta > 0}
        if grows and not cluster_present:
            raise _ClaimRefused('no_cluster_capacity')

        with engine.begin() as conn:
            # INVARIANT: the first statement executed on this connection
            # must be a guarded UPDATE, per the block comment above
            # _probe_admission_rows(). When there is no singleton to
            # adjust that is the guarded claim UPDATE below instead,
            # which is equally DML and equally takes its row lock first.

            # cluster_capacity, first in the canonical order. Only the
            # dimensions that actually move are guarded: a pure expiry
            # change, or a shrink, must not be refused because some
            # *other* dimension of an already overcommitted cluster
            # would not fit a growth nobody asked for.
            if cluster_present and any(deltas.values()):
                cluster_where = [cluster.c.id == 1]
                cluster_values: dict[str, Any] = {
                    'updated_at': sa.func.now()}
                for dimension, delta in deltas.items():
                    claimed = cluster.c[f'claimed_{dimension}']
                    if delta > 0:
                        # migrated=0, and it must stay zero: a grow
                        # moves nothing off the unclaimed side, because
                        # the namespace's usage is already counted in
                        # this claim's used_*. See _claim_capacity_guard.
                        cluster_where.append(
                            _claim_capacity_guard(dimension, delta, 0))
                    elif delta < 0:
                        # Never below zero: the singleton and the claims
                        # can disagree after a reconcile pass, and a
                        # negative counter would hand out capacity that
                        # does not exist.
                        cluster_where.append(claimed >= -delta)
                    if delta:
                        cluster_values[f'claimed_{dimension}'] = (
                            claimed + delta)
                if conn.execute(sa.update(cluster).where(
                        sa.and_(*cluster_where)).values(
                            **cluster_values)).rowcount == 0:
                    raise _ClaimRefused('capacity', requested=grows)

            # namespace_claims, second in the canonical order. Three
            # kinds of clause: the key, the optimistic guard on the
            # limits the deltas were computed from, and D8's shrink
            # floor.
            claim_where = [claims.c.uuid == claim_key,
                           claims.c.state == CLAIM_STATE_ACTIVE]
            for dimension in CAPACITY_DIMENSIONS:
                claim_where.append(
                    claims.c[f'limit_{dimension}'] == old_limits[dimension])
                if deltas[dimension] < 0:
                    claim_where.append(claims.c[f'used_{dimension}']
                                       <= new_limits[dimension])
            claim_values: dict[str, Any] = {'updated_at': sa.func.now()}
            for dimension in changing:
                claim_values[f'limit_{dimension}'] = new_limits[dimension]
            if change_expiry:
                claim_values['expires_at'] = _claim_expiry_expression(
                    expires_in_seconds)
            if conn.execute(sa.update(claims).where(
                    sa.and_(*claim_where)).values(
                        **claim_values)).rowcount == 0:
                # Either the shrink floor bound or the row moved. Which
                # of the two is decided from a fresh read after the
                # rollback, below, because MariaDB cannot say which
                # clause failed and this transaction is about to vanish.
                raise _ClaimRowStale()

            # Read back what we just wrote, for the reply. After our own
            # write, on a row we hold the lock on.
            row = conn.execute(_claim_select().where(
                claims.c.uuid == claim_key)).first()
            if row is not None:
                outcome['claim'] = _claim_row_to_dict(row)

        outcome['updated'] = True
        return outcome

    def _blocked_by_shrink_floor() -> list[CapacityDimensionDetailDict]:
        """Which dimensions a shrink could not get under, read fresh.

        Empty means the claim UPDATE missed for some other reason -- a
        concurrent writer moved the limits -- and the operation retries.

        Only dimensions actually being shrunk are considered, because
        the SQL floor is only applied to those, and this has to diagnose
        the guard that ran rather than a guard it might have run. The
        difference is not theoretical while ceilings are advisory:
        used_* legitimately sits above limit_* then, so a claim at
        limit 4 and usage 10 being *grown* to 8 satisfies
        ``used > requested`` without a floor ever having been tested.
        Reporting that would hand the operator a durable 409 saying a
        claim cannot be shrunk below its usage, for a request that was a
        grow, and would swallow the retry that was about to succeed.

        The shrink test is against the row just read rather than the
        limits the caller started from, for the same reason the read is
        fresh at all: what matters is the claim as it now stands, after
        whatever concurrent writer moved it.
        """
        row = _read_claim_row(claim_key)
        if row is None:
            return []
        dimensions = []
        for dimension in changing:
            if requested[dimension] >= int(getattr(row, f'limit_{dimension}')):
                continue
            used = int(getattr(row, f'used_{dimension}'))
            if used > requested[dimension]:
                dimensions.append(_capacity_dimension(
                    dimension, requested[dimension], used, 0))
        return dimensions

    for _attempt_number in range(_CLAIM_STALE_MAX_ATTEMPTS):
        try:
            return _retry_transaction(
                _attempt, f'update_namespace_claim({claim_uuid})')
        except _ClaimRefused as refusal:
            result['refused_reason'] = refusal.reason
            if refusal.reason == 'capacity':
                # The detail is denominated in the *delta* the grow
                # asked for, not the new limit: what the guard tested
                # was whether the cluster had room for the increase.
                result['dimensions'] = _cluster_capacity_dimensions(
                    refusal.requested, refusal.migrated)
            return result
        except _ClaimRowStale:
            blocked = _blocked_by_shrink_floor()
            if blocked:
                result['refused_reason'] = 'below_usage'
                result['dimensions'] = blocked
                return result
            continue
        except (OperationalError, IntegrityError) as e:
            LOG.warning(
                f'MariaDB update_namespace_claim failed for '
                f'{claim_uuid}: {e}')
            result['success'] = False
            result['error'] = f'MariaDB error: {e}'
            return result

    LOG.warning(
        f'update_namespace_claim({claim_uuid}): the claim row kept moving '
        f'under {_CLAIM_STALE_MAX_ATTEMPTS} attempts, giving up')
    result['refused_reason'] = 'conflict'
    return result


def _direct_delete_namespace_claim(
        claim_uuid: str) -> DeleteNamespaceClaimResult:
    """Delete a claim and return its capacity to the cluster (D3).

    The mirror of creation, floored on the way back: whatever the claim
    still holds returns to ``cluster_capacity.unclaimed_used_*`` and its
    limits come off ``claimed_*``, then the row goes. Canonical order,
    and the transaction opens with that UPDATE.

    Double delete is harmless by construction: the probe finds no row,
    no transaction is opened, and the reply says ``deleted=False`` with
    no capacity returned. The DELETE also carries an optimistic guard on
    the counters the probe read, so a claim an instance create charged
    between the two re-probes and runs again rather than returning a
    stale figure to the unclaimed side.

    A claim which is not in coverage state 'active' is simply removed,
    touching no counter. The reconciler sums ``claimed_*`` over active
    claims only, and its unclaimed fold skips only namespaces holding an
    *active* claim -- so an expired claim's limits are already out of
    ``claimed_*`` and its namespace's usage is already counted in
    ``unclaimed_used_*``. Migrating either again would double it.
    """
    result = _empty_delete_claim_result()

    try:
        claim_key = UUID(claim_uuid)
    except ValueError as e:
        LOG.warning(f'delete_namespace_claim given a malformed uuid: {e}')
        result['success'] = False
        result['error'] = f'malformed uuid: {e}'
        return result

    engine = _get_engine()
    claims = _get_namespace_claims_table()
    cluster = _get_cluster_capacity_table()

    def _attempt() -> DeleteNamespaceClaimResult:
        outcome = _empty_delete_claim_result()

        # The probe, outside the transaction, per the block comment
        # above _probe_admission_rows().
        current = _read_claim_row(claim_key)
        if current is None:
            return outcome

        active = current.state == CLAIM_STATE_ACTIVE
        limits = {d: int(getattr(current, f'limit_{d}'))
                  for d in CAPACITY_DIMENSIONS}
        used = {d: int(getattr(current, f'used_{d}'))
                for d in CAPACITY_DIMENSIONS}

        with engine.begin() as conn:
            # INVARIANT: the first statement is DML -- the guarded
            # cluster UPDATE, or the guarded DELETE below when there is
            # no counter to adjust. Not a plain SELECT; see the block
            # comment above _probe_admission_rows().
            if active:
                # Guarded first, clamped on a miss: the same floored
                # idiom as _floored_namespace_decrement(), written out
                # here because this statement both decrements claimed_*
                # and increments unclaimed_used_* and that helper does
                # pure decrements.
                guarded = sa.update(cluster).where(sa.and_(
                    cluster.c.id == 1, *[
                        cluster.c[f'claimed_{d}'] >= limits[d]
                        for d in CAPACITY_DIMENSIONS])).values(
                    updated_at=sa.func.now(), **{
                        f'claimed_{d}': cluster.c[f'claimed_{d}'] - limits[d]
                        for d in CAPACITY_DIMENSIONS
                    }, **{
                        f'unclaimed_used_{d}': (
                            cluster.c[f'unclaimed_used_{d}'] + used[d])
                        for d in CAPACITY_DIMENSIONS
                    })
                if conn.execute(guarded).rowcount == 0:
                    clamp = sa.update(cluster).where(
                        cluster.c.id == 1).values(
                        updated_at=sa.func.now(), **{
                            f'claimed_{d}': sa.func.greatest(
                                0, cluster.c[f'claimed_{d}'] - limits[d])
                            for d in CAPACITY_DIMENSIONS
                        }, **{
                            f'unclaimed_used_{d}': (
                                cluster.c[f'unclaimed_used_{d}'] + used[d])
                            for d in CAPACITY_DIMENSIONS
                        })
                    if conn.execute(clamp).rowcount > 0:
                        LOG.warning(
                            f'Clamped claimed capacity on delete of claim '
                            f'{claim_uuid}: the cluster singleton held less '
                            f'than the claim it is releasing')
                        outcome['clamped'] = True
                    # A rowcount of zero here means there is no
                    # singleton at all, so nothing was ever charged and
                    # there is nothing to clamp -- the same reading
                    # _floored_namespace_decrement() gives it.

            # namespace_claims, second in the canonical order. The
            # optimistic guard is on exactly the counters the credit
            # above was computed from.
            delete = sa.delete(claims).where(sa.and_(
                claims.c.uuid == claim_key,
                claims.c.state == current.state,
                *[claims.c[f'limit_{d}'] == limits[d]
                  for d in CAPACITY_DIMENSIONS],
                *[claims.c[f'used_{d}'] == used[d]
                  for d in CAPACITY_DIMENSIONS]))
            if conn.execute(delete).rowcount == 0:
                raise _ClaimRowStale()

            outcome['deleted'] = True
            if active:
                outcome['returned_cpus'] = used['cpus']
                outcome['returned_memory_mb'] = used['memory_mb']
                outcome['returned_disk_gb'] = used['disk_gb']

        return outcome

    for _attempt_number in range(_CLAIM_STALE_MAX_ATTEMPTS):
        try:
            return _retry_transaction(
                _attempt, f'delete_namespace_claim({claim_uuid})')
        except _ClaimRowStale:
            continue
        except (OperationalError, IntegrityError) as e:
            LOG.warning(
                f'MariaDB delete_namespace_claim failed for '
                f'{claim_uuid}: {e}')
            result['success'] = False
            result['error'] = f'MariaDB error: {e}'
            return result

    LOG.warning(
        f'delete_namespace_claim({claim_uuid}): the claim row kept moving '
        f'under {_CLAIM_STALE_MAX_ATTEMPTS} attempts, giving up')
    result['success'] = False
    result['error'] = 'the claim row kept changing under concurrent writers'
    return result


def _direct_get_namespace_claim(
        claim_uuid: str) -> Optional[NamespaceClaimRow]:
    """Read one claim row by uuid, or None if there is no such claim.

    None means *absent*, never *unreadable*: a database failure raises.
    See _direct_get_namespace_claims() for why that distinction is worth
    more for a claim than for most objects.
    """
    claims = _get_namespace_claims_table()

    try:
        claim_key = UUID(claim_uuid)
    except ValueError as e:
        # A malformed uuid is genuinely not a claim, so None is the
        # honest answer here rather than an error.
        LOG.warning(f'get_namespace_claim given a malformed uuid: {e}')
        return None

    try:
        engine = _get_engine()
        with engine.connect() as conn:
            row = conn.execute(_claim_select().where(
                claims.c.uuid == claim_key)).first()
        return _claim_row_to_dict(row) if row is not None else None
    except OperationalError as e:
        LOG.warning(f'MariaDB query failed for namespace_claims: {e}')
        raise exceptions.DatabaseUnavailable(
            f'namespace claim {claim_uuid} could not be read: {e}') from e


def _direct_get_namespace_claims(
        namespace: str) -> list[NamespaceClaimRow]:
    """Read claim rows, optionally restricted to one namespace.

    The namespace restriction is a WHERE clause on the table's own
    ``idx_namespace_claims_namespace`` index rather than a Python filter
    over every row, which is what the project's filter-pushdown rule
    asks for. An empty namespace lists everything, which is what a
    cluster-wide operator view wants.

    An empty list means the namespace holds no claims. It never means
    the read failed, because one caller cannot tell the difference and
    is destructive about it: Namespace.hard_delete() deletes each claim
    it is told about and then removes the namespace regardless. Handed
    an empty list by a database that was merely unwell, it would take
    the namespace away and leave the claim row behind holding
    cluster_capacity.claimed_* -- capacity promised to a namespace that
    no longer exists, which no sweep repairs, because the claim's own
    state row is perfectly healthy and the namespace's is now gone.
    Raising instead aborts that cascade partway, which is safe: the
    namespace keeps its state row and the reaper retries the whole
    delete on its next pass.
    """
    claims = _get_namespace_claims_table()

    try:
        engine = _get_engine()
        statement = _claim_select()
        if namespace:
            statement = statement.where(claims.c.namespace == namespace)
        with engine.connect() as conn:
            rows = conn.execute(
                statement.order_by(claims.c.uuid)).fetchall()
        return [_claim_row_to_dict(row) for row in rows]
    except OperationalError as e:
        LOG.warning(f'MariaDB query failed for namespace_claims: {e}')
        raise exceptions.DatabaseUnavailable(
            f'namespace claims for {namespace!r} could not be read: '
            f'{e}') from e


# ---------------------------------------------------------------------------
# gRPC wrappers.
#
# All five use the *default* budget rather than BOUNDED_QUERY_TIMEOUT.
# The bounded budget exists for callers upstream of a systemd watchdog
# pet or on the instance-create hot path (issue 3586), and claim CRUD is
# neither: it is driven by an operator's admin REST request, runs nowhere
# in find_candidates(), the admission transaction or a daemon's
# maintenance loop, and has no reconciler to true up a call that gave up
# early. Failing an operator's create fast, so that they retry a request
# which had in fact committed, would be strictly worse than making them
# wait -- and the calls are rare enough that their worst case cannot
# aggregate into a watchdog window the way an admission's can.
# ---------------------------------------------------------------------------

def _claim_from_proto(claim: Any) -> NamespaceClaimRow:
    """Convert a NamespaceClaim proto message into the dict form."""
    return {
        'uuid': claim.uuid,
        'namespace': claim.namespace,
        'limit_cpus': int(claim.limit_cpus),
        'limit_memory_mb': int(claim.limit_memory_mb),
        'limit_disk_gb': int(claim.limit_disk_gb),
        'used_cpus': int(claim.used_cpus),
        'used_memory_mb': int(claim.used_memory_mb),
        'used_disk_gb': int(claim.used_disk_gb),
        'state': claim.state,
        'expires_at': float(claim.expires_at),
        'updated_at': float(claim.updated_at),
    }


def _grpc_create_namespace_claim(
        claim_uuid: str, namespace: str, limit_cpus: int,
        limit_memory_mb: int, limit_disk_gb: int,
        expires_in_seconds: int) -> CreateNamespaceClaimResult:
    """Create a namespace claim via the database microservice."""
    result = _empty_create_claim_result()
    try:
        stub = _get_database_stub()
        request = database_pb2.CreateNamespaceClaimRequest(
            uuid=claim_uuid,
            namespace=namespace,
            limit_cpus=limit_cpus,
            limit_memory_mb=limit_memory_mb,
            limit_disk_gb=limit_disk_gb,
            expires_in_seconds=expires_in_seconds)
        reply = _grpc_call(stub.CreateNamespaceClaim, request)
        result['success'] = bool(reply.success)
        result['error'] = reply.error
        result['created'] = bool(reply.created)
        result['refused_reason'] = reply.refused_reason
        result['dimensions'] = [
            {
                'dimension': d.dimension,
                'limit': float(d.limit),
                'used': float(d.used),
                'requested': float(d.requested),
                'exceeded': bool(d.exceeded),
            } for d in reply.dimensions]
        if reply.HasField('claim'):
            result['claim'] = _claim_from_proto(reply.claim)
        return result
    except (exceptions.DatabaseUnavailable, grpc.RpcError) as e:
        LOG.error(f'gRPC CreateNamespaceClaim failed: {e}')
        result['success'] = False
        result['error'] = f'database unavailable: {e}'
        return result


def _grpc_update_namespace_claim(
        claim_uuid: str, fields: list[str], limit_cpus: int,
        limit_memory_mb: int, limit_disk_gb: int,
        expires_in_seconds: int) -> UpdateNamespaceClaimResult:
    """Update a namespace claim via the database microservice."""
    result = _empty_update_claim_result()
    try:
        stub = _get_database_stub()
        request = database_pb2.UpdateNamespaceClaimRequest(
            uuid=claim_uuid,
            limit_cpus=limit_cpus,
            limit_memory_mb=limit_memory_mb,
            limit_disk_gb=limit_disk_gb,
            expires_in_seconds=expires_in_seconds,
            fields=fields)
        reply = _grpc_call(stub.UpdateNamespaceClaim, request)
        result['success'] = bool(reply.success)
        result['error'] = reply.error
        result['updated'] = bool(reply.updated)
        result['refused_reason'] = reply.refused_reason
        result['dimensions'] = [
            {
                'dimension': d.dimension,
                'limit': float(d.limit),
                'used': float(d.used),
                'requested': float(d.requested),
                'exceeded': bool(d.exceeded),
            } for d in reply.dimensions]
        if reply.HasField('claim'):
            result['claim'] = _claim_from_proto(reply.claim)
        return result
    except (exceptions.DatabaseUnavailable, grpc.RpcError) as e:
        LOG.error(f'gRPC UpdateNamespaceClaim failed: {e}')
        result['success'] = False
        result['error'] = f'database unavailable: {e}'
        return result


def _grpc_delete_namespace_claim(
        claim_uuid: str) -> DeleteNamespaceClaimResult:
    """Delete a namespace claim via the database microservice."""
    result = _empty_delete_claim_result()
    try:
        stub = _get_database_stub()
        request = database_pb2.DeleteNamespaceClaimRequest(uuid=claim_uuid)
        reply = _grpc_call(stub.DeleteNamespaceClaim, request)
        result['success'] = bool(reply.success)
        result['error'] = reply.error
        result['deleted'] = bool(reply.deleted)
        result['returned_cpus'] = int(reply.returned_cpus)
        result['returned_memory_mb'] = int(reply.returned_memory_mb)
        result['returned_disk_gb'] = int(reply.returned_disk_gb)
        result['clamped'] = bool(reply.clamped)
        return result
    except (exceptions.DatabaseUnavailable, grpc.RpcError) as e:
        LOG.error(f'gRPC DeleteNamespaceClaim failed: {e}')
        result['success'] = False
        result['error'] = f'database unavailable: {e}'
        return result


def _grpc_get_namespace_claim(
        claim_uuid: str) -> Optional[NamespaceClaimRow]:
    """Read one namespace claim via the database microservice.

    DatabaseUnavailable is deliberately left to propagate rather than
    collapsed into None. CLAUDE.md's rule for this layer is that a
    "not found" return value always means the object genuinely is not
    there -- a claim that read as absent because the tier blinked would
    have the object layer conclude it had been deleted.
    """
    stub = _get_database_stub()
    request = database_pb2.GetNamespaceClaimRequest(uuid=claim_uuid)
    try:
        reply = _grpc_call(stub.GetNamespaceClaim, request)
    except grpc.RpcError as e:
        LOG.error(f'gRPC GetNamespaceClaim failed: {e}')
        raise exceptions.DatabaseUnavailable(str(e)) from e
    if not reply.found:
        return None
    return _claim_from_proto(reply.claim)


def _grpc_get_namespace_claims(
        namespace: str) -> list[NamespaceClaimRow]:
    """List namespace claims via the database microservice.

    An unreachable database raises rather than returning an empty list,
    for the reason _grpc_get_namespace_claim() records.
    """
    stub = _get_database_stub()
    request = database_pb2.GetNamespaceClaimsRequest(namespace=namespace)
    try:
        reply = _grpc_call(stub.GetNamespaceClaims, request)
    except grpc.RpcError as e:
        LOG.error(f'gRPC GetNamespaceClaims failed: {e}')
        raise exceptions.DatabaseUnavailable(str(e)) from e
    return [_claim_from_proto(claim) for claim in reply.claims]


def create_namespace_claim(
        claim_uuid: str, namespace: str, limit_cpus: int,
        limit_memory_mb: int, limit_disk_gb: int,
        expires_in_seconds: int) -> CreateNamespaceClaimResult:
    """Claim aggregate capacity for a namespace, guarded (D3, D14).

    The claim's ``used_*`` counters are seeded with the namespace's
    existing drawdown, computed by the reconciler's own aggregation, and
    the same amounts come off the cluster's unclaimed sums in the same
    transaction. Without that migration a namespace that already held
    instances could place its whole claim a second time, for up to one
    reconcile period, starting from the moment an operator did the thing
    the feature exists for.

    ``expires_in_seconds`` is a duration, not a timestamp: the expiry is
    computed from the *server's* clock, because that is the only clock
    the expiry sweep ever compares against.

    Returns:

        {'success': bool, 'error': str, 'created': bool,
         'refused_reason': '' | 'capacity' | 'no_cluster_capacity'
                              | 'exists',
         'dimensions': [{'dimension': str, 'limit': float, 'used': float,
                         'requested': float, 'exceeded': bool}, ...],
         'claim': {...} | None}

    ``success`` says the RPC ran; ``created`` says what it decided.
    """
    if _use_database_service():
        return _grpc_create_namespace_claim(
            claim_uuid, namespace, limit_cpus, limit_memory_mb,
            limit_disk_gb, expires_in_seconds)
    return _direct_create_namespace_claim(
        claim_uuid, namespace, limit_cpus, limit_memory_mb, limit_disk_gb,
        expires_in_seconds)


def update_namespace_claim(
        claim_uuid: str, fields: list[str], limit_cpus: int = 0,
        limit_memory_mb: int = 0, limit_disk_gb: int = 0,
        expires_in_seconds: int = 0) -> UpdateNamespaceClaimResult:
    """Grow, shrink or re-date a claim (D8).

    ``fields`` names which of ``limit_cpus``, ``limit_memory_mb``,
    ``limit_disk_gb`` and ``expires_in_seconds`` this call sets;
    everything else is left alone. Growing any dimension is guarded
    against the cluster exactly as creation is, shrinking is permitted
    down to the claim's current usage and no further, and one call may
    do both. Nothing here ever grows a claim the caller did not ask to
    grow (D15).

    Returns:

        {'success': bool, 'error': str, 'updated': bool,
         'refused_reason': '' | 'capacity' | 'below_usage' | 'not_found'
                              | 'not_active' | 'no_cluster_capacity'
                              | 'conflict',
         'dimensions': [...], 'claim': {...} | None}
    """
    if _use_database_service():
        return _grpc_update_namespace_claim(
            claim_uuid, fields, limit_cpus, limit_memory_mb, limit_disk_gb,
            expires_in_seconds)
    return _direct_update_namespace_claim(
        claim_uuid, fields, limit_cpus, limit_memory_mb, limit_disk_gb,
        expires_in_seconds)


def delete_namespace_claim(claim_uuid: str) -> DeleteNamespaceClaimResult:
    """Delete a claim, returning what it held to the cluster.

    Returns:

        {'success': bool, 'error': str, 'deleted': bool,
         'returned_cpus': int, 'returned_memory_mb': int,
         'returned_disk_gb': int, 'clamped': bool}

    ``deleted`` is False when there was no claim to delete, which is how
    a repeat call is told from a real one. Deleting twice is harmless.
    """
    if _use_database_service():
        return _grpc_delete_namespace_claim(claim_uuid)
    return _direct_delete_namespace_claim(claim_uuid)


def get_namespace_claim(claim_uuid: str) -> Optional[NamespaceClaimRow]:
    """One claim row by uuid, or None if there is no such claim."""
    if _use_database_service():
        return _grpc_get_namespace_claim(claim_uuid)
    return _direct_get_namespace_claim(claim_uuid)


def get_namespace_claims(namespace: str = '') -> list[NamespaceClaimRow]:
    """Every claim, or every claim in one namespace.

    The namespace restriction is pushed down to SQL and served by the
    claims table's namespace index.
    """
    if _use_database_service():
        return _grpc_get_namespace_claims(namespace)
    return _direct_get_namespace_claims(namespace)
